window.__Q=window.__Q||{};window.__Q["clin/7/A1"]=[{"q":"舌体主要来源于","o":["奇结节","侧舌突","联合突","下颌突","甲状舌管"],"a":1,"e":"侧舌突由第1鳃弓腹侧间充质增生形成，左右融合构成舌体的大部分，是舌体的主要来源。奇结节仅形成舌盲孔前方舌体的一小部分；联合突实为舌根的原基，由第2～4鳃弓腹侧间充质增生形成；甲状舌管是甲状腺发生中的残留管道，不参与舌体构成"},{"q":"中动脉内膜的组成包括","o":["内皮、内皮下层、内弹性膜","内皮、内皮下层、内膜下层","内皮、基膜、内弹性膜","内皮、基膜、内皮下层","内皮、内膜下层、内弹性膜"],"a":0,"e":"中动脉内膜由内向外分为内皮、内皮下层和内弹性膜三层，内弹性膜位于内膜与中膜交界处，是该动脉的典型标志。内膜下层并非内膜的固有分层，而是心内膜的结构；基膜仅为上皮下的薄层，不等于内皮下层，故含基膜或内膜下层的组合均不成立"},{"q":"味蕾不存在于","o":["轮廓乳头","菌状乳头","丝状乳头","软腭和会厌","咽"],"a":2,"e":"丝状乳头表面为角化复层扁平上皮，不含味蕾，仅有一般触觉感受作用。轮廓乳头和菌状乳头的上皮内均含味蕾，软腭、会厌及咽部黏膜也散在分布味蕾，都是味觉感受部位，故均是味蕾存在的部位"},{"q":"神经管壁早期分化形成三层，由内向外依次为","o":["室管膜层、套层和边缘层","套层、边缘层和室管膜层","边缘层、室管膜层和套层","边缘层、套层和室管膜层","套层、室管膜层和边缘层"],"a":0,"e":"神经管形成后，神经上皮细胞不断增殖，管壁由内向外依次分化为室管膜层、套层和边缘层，室管膜层紧贴管腔，套层含成神经细胞和成神经胶质细胞，边缘层为轴突聚集区。其余排列顺序均把三层位置颠倒，不符合由内向外的基本层次"},{"q":"下列无周期性横纹的是","o":["胶原纤维","骨骼肌纤维","网状纤维","心肌纤维","平滑肌纤维"],"a":4,"e":"平滑肌纤维呈长梭形，胞质内无肌原纤维，因而不具横纹。骨骼肌和心肌纤维含由粗、细肌丝规律排列的肌节，均有明显横纹；胶原纤维与网状纤维在电镜下可见约64nm的周期性横纹，属于结缔组织纤维的特征，均非无横纹者"},{"q":"胞质含有大量脂滴的细胞位于","o":["垂体远侧部","神经垂体","肾上腺皮质","甲状腺","肾上腺髓质"],"a":2,"e":"肾上腺皮质束状带细胞属于类固醇分泌细胞，胞质内含大量滑面内质网、管状嵴线粒体和脂滴，脂滴中储存合成糖皮质激素的原料。肾上腺髓质嗜铬细胞分泌肾上腺素，胞质内为分泌颗粒而非脂滴；甲状腺滤泡上皮储存甲状腺球蛋白；垂体远侧部与神经垂体均无大量脂滴细胞"},{"q":"触觉小体分布于","o":["皮肤真皮乳头内","皮肤真皮网织层内","表皮内","真皮血管壁上","皮下组织内"],"a":0,"e":"触觉小体位于皮肤真皮乳头内，以手指掌侧最多，长轴与皮肤表面垂直，内含横列扁平细胞，感受应力参与触觉。真皮网织层为致密结缔组织，无触觉小体；表皮内为游离神经末梢和梅克尔细胞；皮下组织内主要分布环层小体"},{"q":"从丘脑进入大脑皮质的神经纤维终末主要分布在","o":["外颗粒层","内颗粒层","内锥体细胞层","多形细胞层","外锥体细胞层"],"a":1,"e":"大脑皮质第Ⅳ层即内颗粒层，是丘脑特异性投射纤维的主要终止层，接受来自丘脑的感觉传入。外颗粒层主要接受联合传入纤维；外锥体细胞层以中、小型锥体细胞为主，发出联合纤维；内锥体细胞层为运动投射神经元所在；多形细胞层以梭形细胞为主"},{"q":"人胚第5周，直接通入泄殖腔的管道是","o":["中肾管","前肾管","中肾旁管","输尿管芽","原始直肠"],"a":0,"e":"人胚第5周时中肾管尾端开口于泄殖腔，输尿管芽本身开口于中肾管，故直接通入泄殖腔的是中肾管。中肾旁管下端为盲端，突入尿生殖窦形成窦结节；输尿管芽发自中肾管，此时尚不直接开口于泄殖腔；原始直肠与泄殖腔以尿直肠隔分界"},{"q":"胚胎上、下肢芽出现于胚胎发育的","o":["第2周","第3周","第4周","第5周","第6周"],"a":2,"e":"四肢的发生始于第4周末，胚体左右外侧体壁先后出现上肢芽与下肢芽，故为第4周。第2周为胚泡植入和二胚层形成期，第3周形成三胚层与神经板，第5周肢芽已出现近端、远端缩窄环而分为三段，均非肢芽初现时间"},{"q":"中肾管的正常发育分化，依赖其管壁细胞表面的","o":["雌激素受体","雄激素受体","孕激素受体","雌激素和孕激素受体","促性腺激素受体"],"a":1,"e":"中肾管分化形成附睾管、输精管、精囊和射精管，依赖管壁细胞表面的雄激素受体；雄激素不敏感综合征患者因缺乏该受体，中肾管不能向男性方向发育。雌激素受体和孕激素受体主要分布于女性生殖管道，中肾旁管的退化则由支持细胞分泌的抗中肾旁管激素决定，与雄激素受体无关"},{"q":"胎儿期左右心房之间的血流方向是从","o":["左心房经第二房间孔至右心房","右心房经卵圆孔、第一房间孔至左心房","左心房经卵圆孔至右心房","右心房经卵圆孔至左心房","左心房经第一房间孔至右心房"],"a":3,"e":"出生前肺循环不行使功能，左心房压力低于右心房，下腔静脉血经卵圆孔由右心房直接流入左心房。卵圆孔瓣位于第一房间隔，只允许右向左分流，任何左心房经卵圆孔或第一房间孔流向右侧的表述都与该单向瓣膜机制相反"},{"q":"由成神经胶质细胞分化而来的是","o":["纤维性和原浆性星形胶质细胞","原浆性星形胶质细胞和小胶质细胞","少突胶质细胞和小胶质细胞","室管膜细胞和纤维性星形胶质细胞","纤维性星形胶质细胞和室管膜细胞"],"a":0,"e":"中枢神经系统中，成神经胶质细胞先分化为成星形胶质细胞和成少突胶质细胞，前者再分化为纤维性和原浆性星形胶质细胞。小胶质细胞起源于血液单核细胞，不属于成神经胶质细胞后代；室管膜细胞由神经管室管膜层直接分化而成，也不是其产物"},{"q":"球旁复合体的组成包括","o":["球旁细胞和致密斑","球外系膜细胞和致密斑","球旁细胞、致密斑和球内系膜细胞","球内系膜细胞和致密斑","球旁细胞、致密斑和球外系膜细胞"],"a":4,"e":"球旁复合体位于肾小体血管极，由球旁细胞、致密斑和球外系膜细胞组成，球外系膜细胞又称极垫细胞，参与信息传递。球内系膜细胞位于血管球毛细血管之间，属于肾小体内部成分，并不列入球旁复合体，故含球内系膜细胞的组合均错误"},{"q":"人体的结构非常精巧，组织结构特点与其功能发挥密切相关，例如衬覆于心脏、血管和淋巴管腔面的上皮组织，其特点中最利于血液和淋巴液流动的是","o":["细胞为多边形","细胞核位于中央","含核的部分略厚","游离面光滑","细胞间有连接结构"],"a":3,"e":"内皮为衬贴于心脏、血管和淋巴管腔面的单层扁平上皮，其游离面光滑，可显著降低血流阻力，最利于血液和淋巴液流动。细胞呈多边形、核居中、含核处略厚均为单层扁平上皮的一般形态，与流动无关；细胞间连接结构主要起封闭和黏附作用"},{"q":"以下关于精子形成的描述中，哪—项是错误的","o":["细胞核染色极度浓缩，核变长并移向细胞的一侧形成精子头","高尔基复合体形成顶体覆盖在核的前2/3","中心粒发出9＋2排列的微管，构成鞭毛中心的轴丝","线粒体汇集于轴丝中部的周围，形成线粒体鞘","残余胞质脱落"],"a":3,"e":"精子形成中线粒体聚集并缠绕在轴丝的近细胞核段周围形成线粒体鞘，该段为尾部中段，并非轴丝中部。核染色质高度浓缩使核变长移向一侧形成精子头，高尔基复合体形成顶体覆盖核前2/3，中心粒微管组成9+2轴丝，残余胞质脱落，这些描述均正确"},{"q":"化学突触是","o":["神经元内的细胞器","神经元表面的纤毛","神经元核膜与核周质接触处","神经元之间或神经元与效应细胞之间的细胞连接","神经元合成神经递质的场所"],"a":3,"e":"化学突触是神经元之间或神经元与肌纤维等效应细胞之间传递信息的特殊细胞连接，由突触前膜、突触间隙和突触后膜构成。它既不是神经元内的细胞器，也不是表面纤毛或核膜结构，神经递质在突触前神经元胞质内合成后储存于突触小泡，而非在突触处合成"},{"q":"关于内耳听觉感受器的描述，哪项错误","o":["由毛细胞和支持细胞组成","毛细胞是感受听觉的细胞","螺旋器又称Corti器","位于骨螺旋板上","毛细胞顶部有听毛"],"a":3,"e":"螺旋器即Corti器，位于基底膜即膜螺旋板上，由支持细胞和毛细胞组成，毛细胞顶部有听毛，是听觉感受细胞。骨螺旋板是蜗轴骨组织伸出的薄板，构成蜗管下壁的内侧部，上面不承载螺旋器，故位于骨螺旋板上的说法错误"},{"q":"平滑肌纤维内的细肌丝附着于","o":["密体","密斑","小凹","中间丝","粗肌丝"],"a":1,"e":"平滑肌纤维的细肌丝一端附着于密斑或密体，另一端游离并环绕粗肌丝，密斑是肌膜上的致密附着点。小凹为肌膜内陷、相当于横小管的结构，与肌丝附着无关；中间丝连接于密斑、密体之间构成细胞骨架；粗肌丝由肌球蛋白组成，是细肌丝滑动的对象而非附着点"},{"q":"关于星形胶质细胞的描述，哪项错误","o":["主要起支持和分隔神经元的作用","突起不分轴突和树突","胞质内含有大量胶质丝","仅分布于中枢神经系统的灰质","是体积最大的神经胶质细胞"],"a":3,"e":"星形胶质细胞分为纤维性和原浆性两种，前者多分布于脑脊髓白质，后者多分布于灰质，并非仅见于灰质。其突起不分轴突与树突，胞质含大量胶质丝，是体积最大的神经胶质细胞，并起支持和分隔神经元的作用，这些表述均符合其特点"},{"q":"图中结构是","o":["微静脉","小静脉","小动脉","中动脉","毛细血管"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。中动脉管壁分内膜、中膜、外膜三层，中膜含10～40层环行平滑肌纤维，故又称肌性动脉，内弹性膜明显。小动脉中膜仅3～9层平滑肌，管径小于1mm；大动脉中膜以40～70层弹性膜为主；微静脉和小静脉管壁薄、平滑肌少，中静脉中膜远薄于中动脉\n\n官方题库中缺失图片"},{"q":"哪一项不是胸腺上皮细胞的功能","o":["形成网状纤维","参与形成胸腺小体","分泌激素","辅助培育T细胞","构成支架"],"a":0,"e":"胸腺上皮细胞构成胸腺支架，参与形成胸腺小体，分泌胸腺素等激素以辅助培育T细胞。网状纤维主要由Ⅲ型胶原蛋白构成，由网状细胞产生，并非胸腺上皮细胞的产物；胸腺上皮细胞依靠突起相互连接成网，但不合成网状纤维"},{"q":"形成尿道下裂的原因是","o":["尿生殖窦膜破裂","生殖结节腹侧分裂","两侧尿生殖褶闭合不全","窦结节腹侧分裂","左右阴唇阴囊隆起闭合不全"],"a":2,"e":"尿道下裂因左、右尿生殖褶在腹侧中线闭合不全，导致阴茎腹侧留有异常尿道开口。尿生殖窦膜破裂是正常发育事件；生殖结节腹侧分裂并不形成尿道；窦结节为中肾旁管突入尿生殖窦形成的结构；阴唇阴囊隆起闭合不全与尿道形成无关"},{"q":"卵巢的间质腺由下列哪种细胞形成","o":["卵泡膜的外层细胞","卵泡周围的结缔组织细胞","卵泡细胞","闭锁次级卵泡的膜细胞","黄体细胞"],"a":3,"e":"卵巢间质腺由闭锁次级卵泡的膜细胞增大并保留形成，具有分泌雄激素的功能。卵泡膜外层细胞为一般结缔组织性被膜，不形成间质腺；卵泡细胞即颗粒细胞，闭锁时脱落被巨噬细胞清除；黄体细胞来自排卵后卵泡的颗粒细胞与膜细胞，与闭锁来源不同"},{"q":"感受压力觉的神经末梢是","o":["触觉小体","肌梭","环层小体","神经-肌连接","腱梭"],"a":2,"e":"环层小体又称帕奇尼小体，分布于皮下组织、腹膜、肠系膜等处，感受较强应力，参与压觉和振动觉。触觉小体即迈斯纳小体，感受应力参与触觉；肌梭感受骨骼肌伸缩，属本体感受器；腱梭感受肌腱张力；神经-肌连接为运动神经末梢，不感受压力"},{"q":"光镜下肾HE染色切片，近曲小管上皮细胞分界不清，是因为","o":["胞质嗜酸性强，染色深","相邻细胞的侧突相互嵌和","细胞排列紧密","细胞膜较薄","刷状缘的存在"],"a":1,"e":"近曲小管上皮细胞侧面有许多侧突，相邻细胞的侧突相互嵌合，使光镜下细胞界限显示不清。胞质嗜酸性强仅影响染色深浅；刷状缘位于腔面，与侧面分界无关；细胞排列紧密和细胞膜薄都不是分界不清的直接原因"},{"q":"感受触觉的神经末梢是","o":["帕奇尼小体","迈斯纳小体","肌梭","游离神经末梢","运动终板"],"a":1,"e":"迈斯纳小体即触觉小体，位于真皮乳头，感受应力刺激并参与触觉。帕奇尼小体即环层小体，感受较强应力产生压觉和振动觉；肌梭感受骨骼肌伸缩；游离神经末梢主要感受痛觉和温度觉；运动终板为支配骨骼肌的运动神经末梢"},{"q":"合成和分泌免疫球蛋白的细胞是","o":["巨噬细胞","浆细胞","肥大细胞","嗜碱性粒细胞","嗜酸性粒细胞"],"a":1,"e":"浆细胞由B淋巴细胞受抗原刺激后分化而成，胞质内粗面内质网和高尔基复合体发达，合成并分泌免疫球蛋白。巨噬细胞主要吞噬抗原异物并分泌细胞因子；肥大细胞释放组胺等参与过敏反应；嗜碱性粒细胞含嗜碱性颗粒；嗜酸性粒细胞参与抗寄生虫反应，均不产生抗体"},{"q":"关于T细胞，哪项正确","o":["约占血液中淋巴细胞总数的20%","在胸腺内受抗原刺激后分化成熟","成熟后多随血流迁移到淋巴小结生发中心","细胞表面有特异性抗原受体","参与体液免疫应答"],"a":3,"e":"T细胞表面具有特异性抗原受体，每个细胞只表达一种，识别抗原肽后活化增殖。T细胞约占血液淋巴细胞总数的70%～75%，20%～40%为淋巴细胞总计数；T细胞在胸腺中成熟不依赖抗原刺激；迁移至淋巴小结生发中心并分化为浆细胞、参与体液免疫的是B细胞"},{"q":"以下哪种是肾皮质的特征性结构","o":["集合管","髓放线","弓形动脉","髓袢","远端小管"],"a":1,"e":"髓放线是肾锥体底部向皮质呈辐射状伸入的条纹，位于皮质内，是皮质可辨认的特征性结构。集合管和髓袢主要位于髓质；弓形动脉位于皮髓质交界处；远端小管在皮质迷路和髓放线均有分布，均非皮质特征性结构"},{"q":"窦周隙内没有","o":["贮脂细胞","肝细胞微绒毛","网状纤维","肝巨噬细胞","血浆"],"a":3,"e":"窦周隙位于肝血窦内皮与肝细胞之间，其内有贮脂细胞、肝细胞微绒毛、网状纤维和血浆，是物质交换场所。肝巨噬细胞即库普弗细胞定居于肝血窦腔内，可伸出伪足进入窦周隙，但其本身不属于窦周隙的固有成分"},{"q":"成釉质细胞来源于","o":["外胚层","内胚层","轴旁中胚层","侧中胚层","间充质"],"a":0,"e":"成釉质细胞由成釉器分化而来，成釉器起源于口腔表面外胚层，故成釉质细胞来源于外胚层，负责形成牙釉质。牙本质和牙骨质由间充质来源的成牙本质细胞、成牙骨质细胞形成；轴旁中胚层和侧中胚层主要形成肌、骨和血管等，不参与釉质形成"},{"q":"关于小肠绒毛，哪项错误","o":["含中央乳糜管","有丰富的毛细血管网","扩大了吸收面积","上皮细胞在其顶端脱落","由黏膜和黏膜下层共同突起形成"],"a":4,"e":"小肠绒毛由黏膜上皮和固有层向肠腔突出形成，表面覆以单层柱状上皮，内含中央乳糜管。由黏膜和黏膜下层共同突起形成的是皱襞而非绒毛；绒毛含丰富毛细血管网，可扩大吸收面积；上皮细胞在绒毛顶端脱落更新，这些均为绒毛的正确特征"},{"q":"关于膜蜗管的结构，错误的是","o":["位于耳蜗内，周围充满外淋巴","围绕蜗轴盘旋两圈半，切面呈三角形","顶壁为前庭膜","外侧壁为复层扁平上皮，含血管，称血管纹","底壁上皮增厚形成螺旋器"],"a":3,"e":"膜蜗管外侧壁上皮为特殊的含毛细血管的复层上皮，称血管纹，可产生内淋巴，并非复层扁平上皮。膜蜗管位于耳蜗内，周围为外淋巴，切面呈三角形并围绕蜗轴盘旋两圈半；顶壁为前庭膜；底壁局部上皮增厚形成螺旋器，这些描述均正确"},{"q":"心内膜垫","o":["发生于动脉干和心球内","是心肌膜增生形成的隆起","背、腹心内膜垫彼此相向生长并融合","将原始心房分隔为左、右心房","参与动脉干的分隔"],"a":2,"e":"背、腹心内膜垫由房室管背腹侧壁心内膜组织增厚形成，二者相向生长并于第6周融合，将房室管分为左、右房室管。心内膜垫起源于心内膜组织而非心肌膜；它将房室管而非原始心房分隔；参与动脉干分隔的是心球嵴，与心内膜垫无关"},{"q":"经两次成熟分裂后，生成4个精子的细胞是","o":["精原细胞","初级精母细胞","次级精母细胞","精子细胞","精子"],"a":1,"e":"初级精母细胞经DNA复制后进行第一次减数分裂形成两个次级精母细胞，再经第二次减数分裂形成四个精子细胞，最终变态为四个精子。精原细胞经有丝分裂增殖；次级精母细胞仅经一次分裂产生两个精子细胞；精子细胞不再分裂，只经变态形成精子"},{"q":"以下哪种细胞一般不会出现在下图箭头所指的管中","o":["单核细胞","淋巴细胞","中性粒细胞","红细胞","嗜酸性粒细胞"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。正常淋巴管内不含红细胞，淋巴细胞、单核细胞、中性粒细胞和嗜酸性粒细胞均可随淋巴出现。红细胞局限于血管系统内，毛细血管管径6～8μm恰容一个红细胞通过，故只有在血液中才能见到红细胞\n\n官方题库中缺失图片"},{"q":"关于连续毛细血管的描述，哪项正确","o":["内皮细胞含少量吞饮小泡，内皮细胞间有紧密连接，基膜完整","内皮细胞含许多吞饮小泡，内皮细胞间有紧密连接，基膜完整","内皮细胞含许多吞饮小泡，内皮细胞间有间隙，基膜不完整","内皮细胞含少量吞饮小泡，内皮细胞间有紧密连接，基膜不完整","内皮细胞含少量吞饮小泡，内皮细胞间有间隙，基膜不完整"],"a":1,"e":"连续毛细血管内皮细胞间有紧密连接，基膜完整，胞质含大量吞饮小泡，是血液与组织间物质交换的主要方式。少量吞饮小泡不符合其结构；内皮细胞间有间隙或基膜不完整见于有孔毛细血管或窦状毛细血管，均非连续毛细血管特征"},{"q":"中动脉中膜的主要成分是","o":["胶原纤维","弹性纤维","平滑肌纤维","网状纤维","神经纤维"],"a":2,"e":"中动脉中膜由10～40层环行平滑肌纤维构成，故又称肌性动脉，是管壁最厚的一层。大动脉中膜以40～70层弹性膜为主；胶原纤维和网状纤维主要构成外膜及血管周围结缔组织；神经纤维分布于外膜，调节平滑肌舒缩，均非中膜主要成分"},{"q":"螺旋器的听弦位于","o":["盖膜","前庭膜","膜螺旋板","骨螺旋板","血管膜"],"a":2,"e":"螺旋器的听弦位于膜螺旋板即基底膜内，由胶原纤维等构成，基底膜自内侧骨螺旋板连至外侧螺旋韧带。盖膜为螺旋缘伸出的胶质薄板，覆盖于螺旋器上方；前庭膜构成膜蜗管顶壁；骨螺旋板为骨性薄板，均不含听弦"},{"q":"与睾丸相邻的中肾小管形成","o":["生精小管","睾丸网","睾丸附件","输出小管","附睾附件"],"a":3,"e":"与睾丸相邻的十余条中肾小管分化为输出小管，连接睾丸网与附睾管，上皮由高柱状纤毛细胞和矮柱状细胞相间排列。生精小管和睾丸网来源于生殖细胞索与睾丸网原基；睾丸附件和附睾附件为残留的中肾小管或中肾旁管结构，并非功能性的输出管道"},{"q":"平滑肌纤维有","o":["肌原纤维","肌节","横纹","肌丝","分支"],"a":3,"e":"平滑肌纤维胞质内含粗肌丝、细肌丝和中间丝等肌丝，以肌丝滑动实现收缩。它无肌原纤维和肌节，也不具横纹，细胞呈长梭形且无分支，这三项是骨骼肌或心肌的结构特点，均不存在于平滑肌纤维"},{"q":"不属于睾丸间质细胞特点的是","o":["常成群分布","位于血管周围","细胞大，胞质嗜酸性","具有蛋白质分泌细胞的超微结构特点","有丰富的滑面内质网、管状嵴线粒体和脂滴"],"a":3,"e":"睾丸间质细胞分泌雄激素，属类固醇分泌细胞，胞质内滑面内质网丰富、线粒体呈管状嵴并含脂滴，常成群位于血管周围，细胞大且胞质嗜酸性。具有蛋白质分泌细胞超微结构特点即粗面内质网和高尔基复合体发达，是成纤维细胞或腺泡细胞的特征，不属于间质细胞"},{"q":"脊髓内分化为内脏传出神经元的成神经细胞位于","o":["基板","翼板","翼板和基板之间","底板和基板之间","顶板和翼板之间"],"a":2,"e":"脊髓侧角由位于基板和翼板之间的成神经细胞聚集形成，其内成神经细胞分化为内脏传出神经元。基板形成前角，成神经细胞分化为躯体运动神经元；翼板形成后角，分化为中间神经元；顶板与底板主要起连接作用，不产生内脏传出神经元"},{"q":"角质形成细胞之间以（ ）相连","o":["紧密连接","中间连接","桥粒","缝隙连接","突触"],"a":2,"e":"角质形成细胞之间以桥粒相连，桥粒使细胞牢固黏附并承受摩擦，浅层细胞的桥粒消失后细胞脱落成为皮屑。紧密连接和缝隙连接有封闭或通讯功能，不是角质形成细胞间的主要连接；突触为神经元间的连接结构"},{"q":"关于喉的结构，下列错误的是","o":["喉以软骨为支架，软骨间借韧带、肌肉或关节相连","会厌舌面上皮中有味蕾","声襞膜部的上皮为复层扁平上皮","喉各部的固有层中均有腺体，血供丰富","室襞的上皮为假复层纤毛柱状上皮"],"a":3,"e":"喉的固有层并非各部均有腺体，声襞膜部固有层内无腺体，其浅层疏松易水肿。喉以软骨为支架，软骨间借韧带、肌肉或关节相连；会厌舌面上皮中含味蕾；声襞膜部覆复层扁平上皮，室襞上皮为假复层纤毛柱状上皮，这些均正确"},{"q":"关于平滑肌纤维，哪项错误","o":["肌纤维呈长梭形","单核","细胞核居中","可见横纹","肌纤维收缩时，细胞核可扭曲"],"a":3,"e":"平滑肌纤维呈长梭形，只有一个位于中央的杆状或椭圆形核，收缩时核可扭曲，胞质内无肌原纤维，不出现横纹。可见横纹是骨骼肌和心肌的特征，因两者含排列规律的肌节，故该项不符合平滑肌"},{"q":"输卵管的管壁由（ ）组成","o":["上皮、固有层、黏膜肌层","黏膜、肌层、浆膜","黏膜、肌层、纤维膜","黏膜、黏膜下层、肌层、浆膜","黏膜、黏膜下层、肌层、纤维膜"],"a":1,"e":"输卵管管壁由黏膜、肌层和浆膜三层组成，黏膜形成纵行分支皱襞，由单层柱状上皮和固有层构成。上皮、固有层、黏膜肌层只是黏膜的组成；消化管特有的黏膜下层不属于输卵管管壁，纤维膜为食管等的外膜类型，均不构成输卵管壁"},{"q":"关于晶状体结构的描述，哪项错误","o":["双凸透明体","皮质的前表面有一层立方细胞","晶状体囊由交织成网的胶原纤维组成","中心部的纤维构成晶状体核","无血管，由房水提供营养"],"a":2,"e":"晶状体囊是由基膜和胶原原纤维等构成的薄层结构，并非交织成网的胶原纤维。晶状体为双凸透明体，无血管、由房水供能；皮质前表面有单层立方上皮，赤道部细胞变长形成晶状体纤维，中央纤维构成晶状体核"},{"q":"肝巨噬细胞位于","o":["肝血窦内","窦周隙内","肝板内","门管区内","中央静脉"],"a":0,"e":"肝巨噬细胞即库普弗细胞，定居于肝血窦腔内，可伸出伪足附着于内皮或穿过内皮窗孔。窦周隙内为贮脂细胞和血浆，不含定植的肝巨噬细胞；肝板由肝细胞排列而成；门管区含门静脉、肝动脉和胆管分支；中央静脉为血窦汇集处"},{"q":"骨骼肌纤维收缩时，其肌节的变化是","o":["仅I带缩短","仅A带缩短","I带、A带均缩短","仅H带缩短","I带缩短、H带缩短或消失"],"a":4,"e":"骨骼肌收缩时细肌丝向M线滑动，明带即I带缩短，暗带即A带长度不变，H带变窄甚至消失，肌节随之缩短。仅I带或仅H带缩短都不完整；A带由粗肌丝长度决定，收缩时不会缩短，故含A带缩短一说均错误"},{"q":"下列哪项是身体的直线变速运动和静止状态的感受器","o":["螺旋器","壶腹嵴","椭圆囊斑和球囊斑","致密斑","血管纹"],"a":2,"e":"椭圆囊斑和球囊斑统称位觉斑，感受身体直线变速运动和静止状态，耳石与毛细胞相对移位使纤毛弯曲而兴奋。螺旋器感受声波，壶腹嵴感受旋转变速运动，致密斑为肾小管离子感受器，血管纹产生内淋巴，均不感受直线变速运动"},{"q":"能分泌黏液但不含杯状细胞的器官是","o":["胃","小肠","结肠","阑尾","胆囊"],"a":0,"e":"胃黏膜表面由表面黏液细胞分泌黏液，形成黏液-碳酸氢盐屏障，胃底腺无杯状细胞。小肠、结肠和阑尾的上皮内均散在杯状细胞并分泌黏液；胆囊黏膜以吸收浓缩胆汁为主，胃则以表面黏液细胞分泌黏液且无杯状细胞为典型"},{"q":"B细胞不具有下列哪项特征","o":["参与淋巴细胞再循环","由脾和淋巴结内的淋巴干细胞增殖分化而成","在抗原刺激下增殖","可分化形成记忆细胞","可转变为产生抗体的浆细胞"],"a":1,"e":"B细胞在骨髓内发育成熟，受抗原刺激后增殖分化为浆细胞和记忆细胞，参与体液免疫并参与淋巴细胞再循环。脾和淋巴结是B细胞定居及发生免疫应答的场所，并非其由淋巴干细胞增殖分化的部位"},{"q":"肌梭的主要功能是","o":["感受骨骼肌纤维的伸缩变化","感受肌腱的伸缩变化","感受心肌纤维的伸缩变化","引起平滑肌纤维的伸缩变化","感受肌上皮细胞的伸缩变化"],"a":0,"e":"肌梭是分布于骨骼肌内的梭形本体感受器，梭内肌纤维与梭外肌纤维同步舒缩，其张力变化刺激感觉神经末梢，感受骨骼肌纤维的伸缩状态。肌腱的伸缩由腱梭感受；心肌和平滑肌的伸缩不由肌梭感知；肌上皮细胞存在于腺体，与肌梭无关"},{"q":"胆小管的管壁是","o":["单层扁平上皮","单层立方上皮","单层柱状上皮","假复层柱状上皮","肝细胞膜围成"],"a":4,"e":"胆小管并非由上皮细胞围成，而是相邻肝细胞连接面的质膜局部凹陷形成的微细管道，其管壁就是肝细胞膜。胆小管周围相邻肝细胞膜形成连接复合体以防止胆汁外溢；单层扁平、立方、柱状或假复层柱状上皮均为其他管腔上皮的类型"},{"q":"关于小肠的结构特征，错误的是","o":["表面有大量绒毛","有环行皱襞","固有层内有肠腺","黏膜层及黏膜下层有淋巴组织","固有层内有明显的神经丛"],"a":4,"e":"小肠的神经丛位于黏膜下层，即黏膜下神经丛，固有层内无明显的神经丛。小肠表面有大量绒毛和环行皱襞，固有层含肠腺并可见淋巴组织，这些都是小肠扩大吸收面积和免疫防御的结构基础"},{"q":"下列哪个结构不分布在皮质迷路内","o":["入球微动脉和出球微动脉","球旁复合体","远端小管直部","致密斑","弓形集合管"],"a":2,"e":"远端小管直部位于髓放线和髓质内，不分布于皮质迷路。入球和出球微动脉、球旁复合体及致密斑位于皮质迷路内的肾小体血管极；弓形集合管位于皮质迷路内并弯入髓放线，均属皮质迷路内的结构"},{"q":"浦肯野细胞分布在","o":["大脑皮质","小脑皮质","脊髓灰质","脊神经节","脑神经节"],"a":1,"e":"浦肯野细胞是小脑皮质唯一的传出神经元，位于小脑皮质浦肯野细胞层，胞体梨形，树突呈扇状伸入分子层。大脑皮质以锥体细胞和梭形细胞为传出神经元；脊髓灰质和脊神经节、脑神经节内均不含浦肯野细胞"},{"q":"红细胞胞质中主要含有","o":["核蛋白","肌动蛋白","血影蛋白","血红蛋白","白蛋白"],"a":3,"e":"成熟红细胞无核、无细胞器，胞质内充满血红蛋白，约占细胞重量的三分之一，负责结合和运输氧与二氧化碳。核蛋白为核内成分，成熟红细胞已无核；血影蛋白构成红细胞膜骨架；肌动蛋白属细胞骨架；白蛋白为血浆蛋白，均非胞质主要成分"},{"q":"心肌闰盘处有","o":["中间连接、桥粒、紧密连接","中间连接、桥粒、缝隙连接","紧密连接、桥粒、缝隙连接","紧密连接、半桥粒、缝隙连接","中间连接、半桥粒、紧密连接"],"a":1,"e":"心肌闰盘位于相邻心肌纤维连接处，由中间连接即黏着小带、桥粒和缝隙连接组成，使心肌同步舒缩。紧密连接主要封闭上皮细胞间隙，半桥粒位于上皮基底面，均不属于闰盘的组成"},{"q":"下列哪种蛋白分子不参与细肌丝的构成","o":["肌球蛋白","肌动蛋白","原肌球蛋白","TnT亚单位","TnC亚单位"],"a":0,"e":"细肌丝由肌动蛋白、原肌球蛋白和肌钙蛋白组成，肌钙蛋白含TnT、TnI和TnC亚单位；肌球蛋白是粗肌丝的组成成分，不参与细肌丝构成。原肌球蛋白掩盖肌动蛋白位点，TnC结合钙离子，均为细肌丝的重要组分"},{"q":"睾丸和卵巢下降过程中，引带连接于","o":["生殖腺尾端与生殖结节之间","生殖腺尾端与阴唇阴囊隆起之间","生殖腺尾端与尿生殖褶之间","生殖腺尾端与阴阜之间","生殖腺尾端与后腹壁下部"],"a":1,"e":"引带为连接生殖腺尾端与阴唇阴囊隆起的纤维索状结构，随其缩短牵拉睾丸或卵巢下降。生殖结节形成外生殖器的阴茎或阴蒂；尿生殖褶参与形成尿道海绵体或小阴唇；阴阜为阴唇阴囊隆起头端合并处，均非引带附着点"},{"q":"胆汁进入血液可导致黄疸，其原因是","o":["与胆小管膜通透性增加有关","与肝血窦内皮细胞通透性增加有关","与肝细胞和肝血窦之间的窦周隙有关","与肝血窦内皮细胞间隙增大有关","与肝细胞连接面连接复合体破坏有关"],"a":4,"e":"肝细胞连接面存在由紧密连接、桥粒等组成的连接复合体，封闭胆小管周围细胞间隙，防止胆汁外溢。肝细胞变性坏死或胆道堵塞时该复合体破坏，胆汁先入窦周隙再入肝血窦而致黄疸；肝血窦内皮通透性高本就允许血浆成分通过，不是胆汁入血的直接原因"},{"q":"从支气管分支开始，肺泡最早出现于","o":["细支气管","终末细支气管","呼吸性细支气管","肺泡管","肺泡囊"],"a":2,"e":"肺呼吸部自呼吸性细支气管开始，其管壁开始出现少量肺泡，是支气管分支中最早出现肺泡的部位。终末细支气管仍属导气部，无肺泡；肺泡管和肺泡囊出现肺泡均晚于呼吸性细支气管；细支气管为导气部，壁内无肺泡"},{"q":"胚体最易受到致畸因子作用而发生畸形的时段为受精后","o":["1～2周","3～5周","3～8周","5～10周","5～12周"],"a":2,"e":"受精后第3～8周为胚期，胚胎细胞增生分化活跃，器官原基正在发生，最易受致畸因子干扰，是致畸敏感期。受精后前两周受强致畸因子作用多致胚胎死亡，弱作用可被代偿而少畸形；第5周以后各期已超出最敏感时段"},{"q":"下列哪一项不属于环境致畸因子","o":["生物","物理","化学","药物","染色体异常"],"a":4,"e":"染色体异常属于遗传因素中的染色体畸变，不属于环境致畸因子。环境致畸因子包括生物性、物理性、致畸性药物、致畸性化学因子及其他因子，药物和化学物质均在其中，生物和物理因素也是经典的环境致畸因素"},{"q":"骨骼肌纤维中贮存钙离子的部位是","o":["肌原纤维","肌浆网","横小管","线粒体","肌红蛋白"],"a":1,"e":"骨骼肌纤维肌质网发达，其终池是贮存钙离子的主要部位，兴奋时释放钙离子触发肌丝滑动。横小管负责传导冲动，不储钙；线粒体供能；肌原纤维为收缩装置；肌红蛋白结合氧，均非钙离子的主要储存处"},{"q":"关于小梁网的描述，哪项错误","o":["前方与角膜后界层相连","后方附着于虹膜","由胶原纤维交织形成","胶原纤维表面均有内皮细胞覆盖","与巩膜静脉窦相通"],"a":1,"e":"小梁网位于前房角，前方与角膜后界层相连，后方附着于巩膜突而非虹膜，由胶原纤维交织成网并被内皮细胞覆盖。小梁间隙是房水流向巩膜静脉窦的通道，阻塞可使眼压升高导致青光眼，而非其他眼病"},{"q":"下列哪项不属于胎膜","o":["羊膜","卵黄囊","尿囊","脐带","基蜕膜"],"a":4,"e":"胎膜包括绒毛膜、羊膜、卵黄囊、尿囊和脐带，对胚胎起保护、营养、呼吸和排泄作用。基蜕膜是母体子宫内膜在植入后形成的蜕膜，与丛密绒毛膜共同组成胎盘，属于母体结构而非胎膜"},{"q":"视网膜脱离多发生在","o":["脉络膜和玻璃膜之间","玻璃膜和色素上皮之间","色素上皮和视细胞层之间","视细胞层和内核层之间","内核层和节细胞层之间"],"a":2,"e":"视网膜由色素上皮层和神经层构成，神经层包括视细胞层、双极细胞层和节细胞层，视网膜脱离多发生在色素上皮层与视细胞层之间。脉络膜与玻璃膜之间、玻璃膜与色素上皮之间为眼球壁其他层次界面，不是视网膜脱离的常见部位"},{"q":"疏松结缔组织中最主要的细胞是","o":["巨噬细胞","肥大细胞","浆细胞","脂肪细胞","成纤维细胞"],"a":4,"e":"成纤维细胞是疏松结缔组织中数目最多、最主要的细胞，合成胶原纤维、弹性纤维和基质，创伤修复中起核心作用。巨噬细胞主司吞噬防御，肥大细胞释放组胺，浆细胞分泌抗体，脂肪细胞贮存脂肪，均非数量最多的固有细胞"},{"q":"输尿管芽可演变为","o":["肾小囊","肾小体","细段","集合小管","近端小管"],"a":3,"e":"输尿管芽长入中肾嵴尾端，其末端反复分支形成肾盂、肾盏和集合管，主干形成输尿管。肾小囊、肾小体和近端小管等肾单位成分由生后肾组织分化而来；细段属于肾单位，不来源于输尿管芽"},{"q":"神经元尼氏体分布在","o":["胞体和轴突内","树突和胞体内","树突和轴突内","脂褐素内","细胞核内"],"a":1,"e":"尼氏体由粗面内质网和游离核糖体构成，分布于神经元胞体和树突内，是蛋白质合成场所，轴突及轴丘内不含尼氏体。脂褐素为胞质内色素颗粒，细胞核内为染色质与核仁，均不是尼氏体的分布部位"},{"q":"肥大细胞通过合成分泌多种细胞因子和生物活性物质，发挥多种生理功能。下列关于肥大细胞分泌颗粒的特点描述，错误的是","o":["粗大，充满胞质","嗜碱性","可被甲苯胺蓝染成蓝色","易溶于水","含嗜酸性粒细胞趋化因子"],"a":2,"e":"肥大细胞颗粒粗大、充满胞质，嗜碱性且易溶于水，含组胺、嗜酸性粒细胞趋化因子等，甲苯胺蓝染色呈紫红色异染性而非蓝色。其余关于颗粒大小、嗜碱性、水溶性和所含趋化因子的描述均符合肥大细胞特点"},{"q":"临床上常以月经龄来推算胚胎龄，即从妊娠妇女末次月经的第一天算起，至胎儿娩出共约","o":["37周","38周","39周","40周","42周"],"a":3,"e":"月经龄从孕妇末次月经第一天算起至胎儿娩出约40周，临床上以此推算胚胎龄。受精龄比月经龄约少2周，为38周；37周、39周、42周均不是以末次月经为起点的标准孕周数"},{"q":"有关血管球的描述，下列哪项是错误的","o":["是一种独特的动脉性毛细血管网","与肾小体尿极相通","毛细血管为有孔型","血管系膜位于毛细血管之间","基膜较厚"],"a":1,"e":"血管球是位于肾小体血管极的一团盘曲毛细血管，由入球微动脉分支形成并汇成出球微动脉，属动脉性毛细血管网，毛细血管为有孔型且基膜较厚。与近曲小管相通的是肾小体的尿极，血管球位于血管极，并不与尿极直接相通"},{"q":"心脏是心血管系统的泵器官，其管壁结构分为","o":["心内膜、心中膜、心外膜和心瓣膜","心内皮、内皮下层、内弹性膜、心中膜和心外膜","心内膜、心肌膜和心外膜","心内皮、内皮下层、心内膜下层、心肌膜和心外膜","心内膜、心内膜下层、心肌层和心外膜"],"a":2,"e":"心脏壁由心腔向外分为心内膜、心肌膜和心外膜三层，心肌膜主要由心肌纤维构成，心外膜为浆膜。心内皮、内皮下层和心内膜下层只是心内膜的细分层次，心中膜并非标准分层名称；心瓣膜为心内膜向腔内突出的结构，不列为心壁三层之一"},{"q":"具有抗寄生虫、分泌防御素的细胞是","o":["微皱褶细胞","浆细胞","壁细胞","S细胞","帕内特细胞"],"a":4,"e":"帕内特细胞位于小肠腺基部，分泌溶菌酶和防御素，对肠道微生物有杀灭作用，参与抗寄生虫和黏膜防御。微皱褶细胞负责摄取抗原；浆细胞分泌免疫球蛋白；壁细胞分泌盐酸和内因子；S细胞分泌促胰液素，均无此功能"},{"q":"目前认为先天性畸形发生的主要原因是","o":["染色体畸变","基因突变","生物性和物理性致畸因子","化学性致畸因子","遗传因素与环境因素的相互作用和原因不明"],"a":4,"e":"先天畸形多由遗传因素与环境因素相互作用引起，尚有相当一部分病例原因不明，不能归于单一因素。染色体畸变和基因突变仅属遗传因素；生物、物理、化学致畸因子只是环境因素的不同类别，单独列项都不能概括主要病因"},{"q":"关于Ⅰ型肺泡细胞，哪项错误","o":["覆盖大部分肺泡表面","细胞扁平菲薄","胞质中细胞器丰富，具有分裂能力","相邻上皮细胞间有紧密连接","胞质内吞饮小泡多"],"a":2,"e":"Ⅰ型肺泡细胞扁平菲薄，覆盖肺泡约95%表面并参与气-血屏障形成，无分裂增殖能力，损伤后由Ⅱ型肺泡细胞增殖补充。胞质内吞饮小泡多、细胞器少才是其特点；含丰富细胞器并有分裂能力的是Ⅱ型肺泡细胞"},{"q":"关于假复层纤毛柱状上皮的描述，哪项不正确","o":["细胞形状、高矮不一","细胞都附着于基膜上","细胞表面都有纤毛","细胞核位置高低不等","主要分布于呼吸道腔面"],"a":2,"e":"假复层纤毛柱状上皮中只有纤毛细胞的游离面有纤毛，杯状细胞等无纤毛，故并非所有细胞表面都有纤毛。该上皮细胞形状高矮不一、核位置高低不等、细胞均附着于基膜，主要分布于呼吸道腔面，这些描述均正确"},{"q":"精子获得运动能力，达到功能上成熟的部位是","o":["生精小管","直精小管","睾丸网","输出小管","附睾管"],"a":4,"e":"精子在附睾管内停留8～17天，经历一系列成熟变化，获得运动能力并达到功能上的成熟。生精小管和直精小管是精子发生的部位；睾丸网仅为运输通道；输出小管主要吸收和转运精子，均不使精子获得运动能力"},{"q":"多囊肾内的囊肿是","o":["静脉曲张","集合小管积液","肾盏膨大","肾小管积液","淋巴管扩张"],"a":3,"e":"多囊肾因远曲小管与集合管未接通，尿液积聚在肾小管内形成大小不等的囊泡，压迫正常肾单位。集合管积液不是其成因；肾盏膨大和静脉曲张、淋巴管扩张均为其他病变，与本病肾小管内尿液潴留的机制不符"},{"q":"关于角膜的描述，哪项错误","o":["角膜基质含少量的血管","角膜上皮为复层扁平，含丰富的神经末梢","角膜基质层最厚","角膜上皮基底层细胞由角膜缘干细胞补充","前界层和后界层不含细胞"],"a":0,"e":"角膜基质由规则排列的胶原纤维板层构成，不含血管，营养靠房水及角膜缘血管供应，这是角膜透明的基础。角膜上皮为复层扁平且神经末梢丰富；基质层最厚；前界层和后界层无细胞；基底层由角膜缘干细胞补充，均正确"},{"q":"胸腺小体的特征是","o":["是胸腺的重要特征，散在分布于皮质内","由胸腺上皮细胞呈同心圆包绕而成","小体外周的上皮细胞较成熟","小体中心的上皮细胞较幼稚","功能尚不太明确，但对胸腺培育胸腺细胞无影响"],"a":1,"e":"胸腺小体由胸腺上皮细胞呈同心圆状排列包绕而成，是胸腺髓质的特征性结构。它位于髓质而非皮质；小体中心细胞较成熟、外周较幼稚；其功能与胸腺培育胸腺细胞相关，并非毫无影响"},{"q":"有关胃发生的描述，哪项错误","o":["胃在早期发生时为前肠尾部的梭形膨大，借腹、背系膜连于体壁上","由于胃的背、腹侧生长速度不等，分别形成胃大弯和胃小弯","当网膜囊形成时，胃大弯由背侧转向右侧，胃小弯由腹侧转向左侧","由于胃的右侧肝在发育，使胃呈左上至右下的斜向方位","胃大弯的头端膨出，形成胃底"],"a":2,"e":"胃大弯由背侧转向左侧、胃小弯由腹侧转向右侧，胃遂沿纵轴顺时针旋转90°，题述左右方向恰好相反。胃由前肠尾部梭形膨大形成，借腹背系膜连于体壁；背腹侧生长不等形成胃大弯和胃小弯；右侧肝发育使胃呈斜位；胃大弯头端膨出形成胃底"},{"q":"视网膜色素上皮来源于","o":["表面外胚层","间充质","视杯内层","视杯外层","视杯口边缘部"],"a":3,"e":"视网膜色素上皮由视杯外层分化而成。视杯内层增厚分化为节细胞、视锥细胞、视杆细胞和双极细胞等神经层；视柄形成视神经；晶状体板形成晶状体；视杯口边缘部形成视网膜盲部即睫状体和虹膜上皮"},{"q":"受精多发生于","o":["子宫体部或底部","输卵管壶腹部","输卵管峡部","输卵管漏斗部","输卵管子宫部"],"a":1,"e":"受精一般发生在输卵管壶腹部，卵子排入后停留于此，与获能精子在此相遇并结合。子宫体部或底部为受精卵着床处；输卵管峡部、漏斗部和子宫部均不是受精的常见部位"},{"q":"下面对成骨细胞的描述，错误的是","o":["可转变为骨细胞","体积较大，有多个核","排列在成骨活跃的骨组织表面","胞质内粗面质网和高尔基复合体发达","合成和分泌胶原纤维和基质，形成类骨质"],"a":1,"e":"成骨细胞为单核细胞，体积较大呈立方形，核大而圆，排列于成骨活跃的骨组织表面，合成分泌胶原纤维和基质形成类骨质并可转变为骨细胞。具有多个核的是破骨细胞；粗面内质网和高尔基复合体发达正确反映其蛋白质分泌功能"},{"q":"卵巢中黄体形成时，子宫内膜","o":["处于月经期","处于增生期","处于分泌期","处于卵泡期","剥脱、出血"],"a":2,"e":"排卵后卵巢内形成黄体，分泌孕激素和雌激素，使子宫内膜进入分泌期，又称黄体期。月经期和卵泡期即增生期与黄体形成无关；剥脱出血是黄体退化、激素撤退后月经期的表现，而非黄体形成时的改变"},{"q":"肛管下段由（ ）演变而来","o":["肛直肠管尾段","肛凹","肛膜","尿生殖窦","泄殖腔"],"a":1,"e":"肛凹为外胚层向内凹陷形成的结构，肛管下段上皮由其演变而来，上段上皮来源于内胚层，二者以齿状线分界。肛直肠管尾段演变为肛管上段；肛膜为两者的分隔，第8周末破裂；尿生殖窦和泄殖腔参与泌尿生殖道及直肠的形成，不形成肛管下段"},{"q":"发生肝憩室的部位是","o":["前肠中段腹侧壁","前肠末端背侧壁","中肠襻头支腹侧壁","中肠襻尾支背侧壁","前肠末端腹侧壁"],"a":4,"e":"肝憩室发生于前肠末端腹侧壁，第4周时该处细胞增生向外突出，是肝和胆囊的原基。前肠中段腹侧壁、中肠襻头支腹侧壁或尾支背侧壁均非肝憩室发生部位；前肠末端背侧壁则为背胰芽发生处附近"},{"q":"关于同源细胞群，哪项正确","o":["直接起源于单核细胞","属于多核细胞","来源于同一个软骨细胞","是成骨细胞的前体","是破骨细胞的前体"],"a":2,"e":"同源细胞群由同一个幼稚软骨细胞增殖分裂形成，一般为2～8个细胞聚集，因此来源于同一个软骨细胞。软骨细胞为单核，并非多核；也不是单核细胞或破骨细胞、成骨细胞的来源，这些细胞属于血液或骨组织系统"},{"q":"唇裂是由于","o":["两侧的上颌突未愈合","两侧的内侧鼻突未愈合","两侧的外侧鼻突未愈合","同侧的上颌突与内侧鼻突未愈合","同侧的上颌突与外侧鼻突未愈合"],"a":3,"e":"唇裂多因上颌突与同侧内侧鼻突未融合所致，裂沟位于人中外侧，常为单侧。两侧上颌突未愈合影响上颌骨；两侧内侧鼻突或外侧鼻突未融合导致的是正中裂或面斜裂，裂的位置与唇裂不同"},{"q":"新生小鼠切除胸腺后，体内缺乏","o":["T淋巴细胞","B淋巴细胞","K细胞","NK细胞","浆细胞"],"a":0,"e":"胸腺是T淋巴细胞发育成熟的场所，切除新生小鼠胸腺后缺乏T淋巴细胞，表现为不能排斥异体移植物、无次级淋巴小结。B淋巴细胞在骨髓成熟；NK细胞、K细胞和浆细胞均不依赖胸腺发育"},{"q":"神经系统来源于","o":["内胚层","中胚层","外胚层","内胚层与外胚层","中胚层与外胚层"],"a":2,"e":"神经系统起源神经外胚层，属于外胚层，先形成神经管和神经嵴，前者分化为中枢神经系统，后者分化为周围神经系统。内胚层形成消化和呼吸上皮；中胚层形成肌、骨和血管，均不是神经系统的来源"},{"q":"一名新生儿哭闹时会出现青紫现象，他最可能存在以下哪种先天畸形","o":["动脉导管未闭","主动脉骑跨","房间隔缺损","室间隔缺损","卵圆孔未闭"],"a":1,"e":"主动脉骑跨使主动脉同时接受左、右心室血液，大量未经氧合的血直接进入体循环，患儿哭闹等需氧增加时缺氧加重而出现青紫，是法洛四联症的关键畸形。动脉导管未闭、房间隔缺损、室间隔缺损早期多为左向右分流，卵圆孔未闭一般无青紫"},{"q":"精子获能是指","o":["在生精小管发生过程中获得受精能力","在附睾才具有受精能力","子宫和输卵管中的某些化学物质使精子具有受精能力","精子释放顶体酶的反应","透明带和放射冠被分解的过程"],"a":2,"e":"精子获能是精子通过子宫和输卵管时，覆盖于头部的精液糖蛋白被去除，从而获得使卵子受精的能力。获能发生于女性生殖管道而非生精小管或附睾；顶体酶释放为顶体反应；透明带和放射冠被分解是顶体酶作用的结果"},{"q":"关于Ⅱ型肺泡细胞，下列哪项正确","o":["细胞扁平","胞质内含有电子密度低的分泌颗粒","参与组成气血屏障","分泌表面活性物质","无分裂增殖能力"],"a":3,"e":"Ⅱ型肺泡细胞分泌表面活性物质，以胞吐方式铺展于肺泡内面，降低表面张力、稳定肺泡大小。细胞扁平且参与气-血屏障的是Ⅰ型肺泡细胞；Ⅱ型细胞胞质内含电子密度高的嗜锇性板层小体，并具有分裂增殖能力，可补充Ⅰ型细胞"},{"q":"关于视神经乳头的描述，错误的是","o":["又称视盘","是视神经穿出眼球的部位","无感光细胞","有视网膜中央动、静脉进出","中央略凹，视觉最敏锐"],"a":4,"e":"视神经乳头无感光细胞，是生理盲点，视觉最敏锐处是黄斑中央凹而非视神经乳头。视神经乳头又称视盘，为节细胞轴突穿出眼球处，中央略凹并有视网膜中央动静脉进出，这些描述均正确"},{"q":"发育成视网膜神经层的是","o":["视杯内层","视杯外层","视柄","晶状体板","间充质"],"a":0,"e":"视网膜神经层由视杯内层分化而成，包括节细胞、视锥细胞、视杆细胞和双极细胞等。视杯外层分化为色素上皮层；视柄形成视神经；晶状体板形成晶状体；间充质形成血管膜和巩膜等，均不形成神经层"},{"q":"胆小管周围的肝细胞膜有","o":["连接复合体","紧密连接","桥粒","缝隙连接","基膜"],"a":0,"e":"胆小管周围相邻肝细胞膜形成由紧密连接、桥粒等组成的连接复合体，封闭细胞间隙防止胆汁外溢。单独的紧密连接或桥粒只是连接成分之一；缝隙连接司通讯；基膜不存在于胆小管周围，均不足以概括该处结构"},{"q":"卵巢中的成熟卵泡正常情况下排卵时间约在月经周期的","o":["第1天","第7天","第14天","第21天","第28天"],"a":2,"e":"成熟卵泡排卵一般发生在月经周期第14天左右，此时子宫内膜同步转入分泌期。第1天为月经来潮；第7天处于增生期；第21天已进入分泌期；第28天为下次月经前，均非排卵时间"},{"q":"隐睾患者不育的原因是","o":["无精子生成","生精小管内无支持细胞","雄激素分泌不足","附睾管不通畅","无睾丸间质细胞"],"a":0,"e":"精子发生需低于体温2～3℃的环境，隐睾时睾丸停留于腹腔或腹股沟，温度过高使精子发生障碍，精液中无精子而不育。隐睾患者支持细胞和间质细胞存在，仍能分泌雄激素，附睾管通常通畅，问题在于生精而非管道或内分泌"},{"q":"小儿佝偻病主要是因缺乏","o":["维生素C","维生素E","维生素A","维生素D","维生素K"],"a":3,"e":"维生素D促进小肠对钙磷吸收并提高血钙血磷，有利于类骨质矿化，儿童缺乏时骨矿化障碍而发生佝偻病。维生素C缺乏致坏血病；维生素A缺乏影响骨塑形和视觉；维生素E、K缺乏均不引起佝偻病"},{"q":"脐静脉血经哪一结构入下腔静脉","o":["上腔静脉","门静脉","动脉导管","肺静脉","静脉导管"],"a":4,"e":"脐静脉入肝后，肝内小血管合并扩大形成静脉导管，一端接左脐静脉，另一端通入下腔静脉，将胎盘回流血液导入下腔静脉。动脉导管连接肺动脉与主动脉；门静脉为消化道血液回流；肺静脉和门静脉均不承接脐静脉血液"},{"q":"关于软骨组织中同源细胞群的描述，下列哪项正确","o":["来源于同一个软骨细胞","属于多核细胞","每群2～8个细胞，都是幼稚的软骨细胞","多个软骨细胞被一个软骨囊包绕","是骨细胞的前体"],"a":0,"e":"同源细胞群由同一个幼稚软骨细胞增殖形成，每群2～8个细胞，位于软骨中部。群内细胞已较成熟，并非幼稚；各细胞各有软骨囊包绕，不在同一囊内；为单核而非多核；也不是骨细胞的前体"},{"q":"卵巢门细胞分泌","o":["雌激素","雄激素","孕激素","卵泡刺激素","黄体生成素"],"a":1,"e":"卵巢门细胞位于卵巢门处基质内，分泌雄激素，过量时可致女性男性化。雌激素和孕激素由卵泡颗粒细胞、膜细胞及黄体分泌；卵泡刺激素和黄体生成素由腺垂体远侧部嗜碱性细胞分泌，均不由卵巢门细胞产生"},{"q":"下丘脑神经内分泌细胞分泌的激素不含有","o":["释放抑制激素","催产素","催乳激素","加压素","释放激素"],"a":2,"e":"下丘脑神经内分泌细胞分泌释放激素、释放抑制激素以及视上核和室旁核合成的催产素、加压素，经轴突运输至神经垂体。催乳激素由腺垂体远侧部催乳激素细胞分泌，不属于下丘脑神经内分泌细胞的产物"},{"q":"平滑肌纤维中，与骨骼肌横小管相当的结构是","o":["密体","密斑","肌膜内陷形成的小凹","中间丝","肌质网"],"a":2,"e":"平滑肌纤维肌膜向胞质内凹陷形成小凹，沿长轴带状排列，相当于骨骼肌的横小管，可传递冲动。密体和密斑为肌丝附着点；中间丝构成细胞骨架；肌质网为钙离子储存部位，均不与横小管相当"},{"q":"血管内皮下层不含有","o":["平滑肌纤维","营养血管","胶原纤维","弹性纤维","细胞外基质"],"a":1,"e":"营养血管是为外膜和中膜提供营养的血管，位于血管外膜，不属于内皮下层。内皮下层为内皮下的薄层结缔组织，含平滑肌纤维、胶原纤维、弹性纤维和细胞外基质，故这些成分均可见于内皮下层"},{"q":"以下一般不用于显示DNA的方法或试剂是","o":["原位杂交","孚尔根（Feulgen）反应","吖啶橙","甲基绿","派若宁"],"a":4,"e":"派若宁即焦宁，在甲基绿-派若宁染色中选择性显示RNA，不用于显示DNA。原位杂交可检测特定DNA序列；孚尔根反应特异显示DNA；吖啶橙和甲基绿均可与DNA结合而显示其存在"},{"q":"单核细胞的特点不包括","o":["血液中体积最大的细胞","占白细胞总数20%～25%","细胞质丰富，呈弱嗜碱性","有吞噬功能，属单核吞噬细胞系统","由骨髓内幼单核细胞转化而来"],"a":1,"e":"单核细胞占白细胞总数的3%～8%，并非20%～25%，后者接近淋巴细胞的正常比例。单核细胞是血液中体积最大的白细胞，胞质丰富呈弱嗜碱性，由骨髓幼单核细胞分化而来，具有吞噬功能并属单核吞噬细胞系统"},{"q":"下述哪一过程既不发生有丝分裂也不发生减数分裂","o":["精原细胞变为初级精母细胞","初级精母细胞变为次级精母细胞","次级精母细胞变为精子细胞","精子细胞变为精子","间质细胞的增殖"],"a":3,"e":"精子细胞不再分裂，只经复杂变态即精子形成过程转变为精子，既不发生有丝分裂也不发生减数分裂。精原细胞经有丝分裂增殖；初级精母细胞和次级精母细胞分别完成第一次和第二次减数分裂；间质细胞通过有丝分裂增殖"},{"q":"人胚第5周时，由背侧体壁突入胚内体腔的两条纵行隆起是","o":["中肾嵴","生殖腺嵴","生肾索","尿生殖嵴","脊索"],"a":3,"e":"尿生殖嵴为第4周末生肾索增生并向胚内体腔突出形成的一对纵行隆起，是泌尿和生殖系统发生的原基。中肾嵴和生殖嵴是尿生殖嵴后续分出的内外两部分；生肾索位于其之前的阶段；脊索为中轴结构，不形成泌尿生殖系统"},{"q":"神经元传导神经冲动是通过","o":["微管","轴膜","神经内膜","神经膜","神经束膜"],"a":1,"e":"神经冲动沿轴膜传导至终末，有髓纤维仅在郎飞结处轴膜兴奋，呈跳跃式传导。微管和神经丝参与轴突运输和支撑；神经内膜、神经膜和神经束膜均为神经纤维的被膜结构，不参与冲动传导"},{"q":"弹性软骨区别于透明软骨的主要特征是","o":["软骨陷窝不明显","缺乏软骨囊","无同源细胞群","基质中含有大量弹性纤维","软骨基质较多"],"a":3,"e":"弹性软骨基质中含大量交织排列的弹性纤维，故富有弹性且新鲜时呈黄色，分布于耳郭、咽喉和会厌，这是区别于透明软骨的主要特征。透明软骨基质含水多而呈半透明，纤维为胶原原纤维，两者软骨陷窝、软骨囊和同源细胞群等基本结构相似"},{"q":"血窦不存在于","o":["肝","脾","骨髓","垂体","脑"],"a":4,"e":"血窦即窦状毛细血管，管腔大而不规则，分布于肝、脾、骨髓和垂体等处。脑内为连续毛细血管，内皮间有紧密连接、基膜完整，参与构成血-脑屏障，不存在血窦"},{"q":"关于肾小体的组成，正确的是","o":["由肾小囊和血管球组成","由肾小管和血管球组成","由肾小囊和肾小管组成","由肾小囊，肾小管和集合管组成","由血管球和泌尿小管组成"],"a":0,"e":"肾小体呈球形，由肾小囊和血管球组成，血管球为有孔毛细血管团，肾小囊为杯状双层上皮囊。肾小管与集合管属于泌尿小管，与肾小体共同构成肾单位，但不属于肾小体本身，故含肾小管或集合管的组合均不成立"},{"q":"关于胃底腺壁细胞的描述，哪项是错误的","o":["主要位于腺的颈部和体部","胞质嗜碱性","有特殊的细胞内分泌小管","含丰富的线粒体","细胞萎缩可引起贫血"],"a":1,"e":"胃底腺壁细胞胞质内含丰富线粒体，呈嗜酸性而非嗜碱性，嗜碱性是主细胞等蛋白质分泌细胞的特点。壁细胞主要位于腺颈部和体部，有细胞内分泌小管，萎缩时因内因子缺乏可致恶性贫血，这些描述均正确"},{"q":"食管腔面衬覆的上皮和小肠上皮相比要耐摩擦，之所以耐摩擦是与该上皮独特的结构特点有关，下列哪项不属于这些特点","o":["组成的细胞层数多","浅层细胞胞质充满干硬的角蛋白","细胞之间有大量的桥粒","基底层的细胞与基膜之间有半桥粒","基底层细胞有很强的分裂增殖能力"],"a":1,"e":"食管衬未角化复层扁平上皮，浅层细胞有核、含角蛋白少，不形成干硬角蛋白层，故不耐角化。其耐摩擦依赖细胞层数多、细胞间大量桥粒、基底层与基膜间半桥粒以及基底层旺盛的分裂增殖能力"},{"q":"肺泡进行气体交换的主要细胞是","o":["Ⅰ型肺泡细胞","Ⅱ型肺泡细胞","肺动脉内皮细胞","尘细胞","巨噬细胞"],"a":0,"e":"Ⅰ型肺泡细胞扁平菲薄，覆盖肺泡约95%表面积并参与气-血屏障形成，是气体交换的主要细胞。Ⅱ型肺泡细胞分泌表面活性物质；肺动脉内皮为血管衬里；尘细胞为肺内巨噬细胞，均不直接进行气体交换"},{"q":"构成骺板的是","o":["透明软骨","弹性软骨","骨组织","类骨质","数层骨板"],"a":0,"e":"骺板为长骨干骺端保留的透明软骨，软骨细胞不断增生并被骨替换，实现长骨加长。弹性软骨分布于耳郭和会厌；骨组织和类骨质为成骨产物；数层骨板构成骨密质的基本结构，均不形成骺板"},{"q":"长期吸烟或反复感染可使气管和支气管","o":["纤毛细胞增加，纤毛运动增强","杯状细胞减少，分泌也减弱","腺体增生肥大，分泌增强","分泌的黏液糖蛋白成分不变","无白细胞渗出"],"a":2,"e":"长期吸烟或反复感染致慢性支气管炎，气管和支气管腺体增生肥大、分泌增强，杯状细胞增多，黏液分泌亢进。纤毛细胞反而减少且纤毛短、粘连、倒伏，黏液糖蛋白成分改变，并常有白细胞渗出，故其余选项均与实际变化相反"},{"q":"有关气管表面黏液层描述正确的是","o":["由黏液性腺泡和杯状细胞的分泌物形成，具有中和有害气体和吸附微尘作用","由黏液性腺泡和浆细胞分泌物形成，具有中和有害气体和吸附微尘作用","由黏液性腺泡和杯状细胞分泌物形成，具有阻碍通气的作用","纤毛和杯状细胞分泌物形成，具有阻碍通气的作用","Clara细胞与杯状细胞分泌物形成，具有中和有害气体和吸附微尘作用"],"a":0,"e":"气管表面黏液层由混合腺的黏液性腺泡和杯状细胞分泌物共同形成，可黏附微尘并溶解二氧化硫等有害气体，起防御作用。浆细胞不参与腺体分泌；黏液层有清除异物作用而非阻碍通气；Clara细胞主要位于细支气管"},{"q":"大脑皮质内的传出神经元主要是","o":["浦肯野细胞","锥体细胞","梭形细胞","锥体细胞和梭形细胞","水平细胞和星形细胞"],"a":3,"e":"大脑皮质的传出神经元为高尔基Ⅰ型神经元，主要是大、中型锥体细胞和梭形细胞，其轴突组成投射纤维或联合传出纤维。浦肯野细胞为小脑皮质传出神经元；水平细胞和星形细胞属局部中间神经元，不向皮质外投射"},{"q":"血小板描述正确的是","o":["是有核的细胞","细胞直径7～8μm","胞质中有嗜碱性的特殊颗粒","胞质的特殊颗粒含组胺和肝素","双凸圆盘形，直径约2～4μm"],"a":4,"e":"血小板是骨髓巨核细胞脱落的胞质小块，呈双凸圆盘状，直径2～4μm，无核。7～8μm为红细胞直径；特殊颗粒含血小板相关因子，组胺和肝素为肥大细胞或嗜碱性粒细胞颗粒成分，均不符合血小板"},{"q":"分泌雄激素结合蛋白的是","o":["精子细胞","初级精母细胞","支持细胞","睾丸间质细胞","精原细胞"],"a":2,"e":"支持细胞在卵泡刺激素和雄激素作用下合成并分泌雄激素结合蛋白，以保持生精小管内高浓度雄激素，促进精子发生。精子细胞、初级精母细胞和精原细胞为生精细胞，不分泌该蛋白；睾丸间质细胞分泌的是雄激素本身"},{"q":"围心腔最早位于","o":["生心索背侧","口咽膜的尾侧","生心索腹侧","泄殖腔腹侧","神经管尾侧"],"a":0,"e":"围心腔最初出现于生心区，位于生心索即生心板的背侧，其腹侧间充质聚集成生心板。头褶发生后心管和围心腔转位约180°，围心腔才转至腹侧、心管转到其背侧；口咽膜尾侧、泄殖腔腹侧和神经管尾侧均非围心腔初始位置"},{"q":"视上核分泌物运抵神经垂体的途径是","o":["漏斗柄","下丘脑垂体束","垂体门脉系统","结节垂体束","毛细淋巴管"],"a":1,"e":"视上核和室旁核神经内分泌细胞的轴突经漏斗下行，构成下丘脑神经垂体束，将血管升压素和催产素运至神经垂体贮存释放。垂体门脉系统连接下丘脑与腺垂体，传导释放激素；漏斗柄仅为结构通道，结节垂体束和毛细淋巴管均非该运输途径"},{"q":"巨噬细胞是体内具有强大吞噬能力的结缔组织细胞，数量多，分布广泛。该细胞胞质内与吞噬功能相关的细胞器是","o":["滑面内质网和高尔基复合体","粗面内质网和高尔基复合体","溶酶体和吞噬体","吞噬体和嗜酸性异染性颗粒","粗面内质网和滑面内质网"],"a":2,"e":"巨噬细胞吞噬异物形成吞噬体或吞饮泡，与溶酶体融合后被酶分解，故溶酶体和吞噬体是与吞噬功能直接相关的细胞器。粗面内质网和高尔基复合体主司蛋白合成分泌；滑面内质网参与脂质合成；嗜酸性异染性颗粒为肥大细胞特征"},{"q":"符合复层扁平上皮特点的是","o":["浅层为一层立方细胞","中间层细胞之间有大量缝隙连接","基底层细胞有较强的分裂增殖能力","含较多的毛细血管","与结缔组织的连接面平直"],"a":2,"e":"复层扁平上皮基底层细胞具有较强的分裂增殖能力，可不断补充浅层脱落细胞，损伤后再生修复快。浅层细胞扁平而非立方；细胞间以桥粒连接而非大量缝隙连接；上皮内无血管；与结缔组织连接面呈波浪状嵌合而非平直"},{"q":"中枢神经系统的原基是","o":["神经嵴","神经管","神经板","神经孔","神经沟"],"a":1,"e":"神经管是中枢神经系统的原基，将分化为脑和脊髓以及松果体、神经垂体和视网膜等。神经嵴分化为周围神经系统；神经板为神经管形成前的先驱结构；神经沟为神经板凹陷，神经孔为其与体表相通的开口，均非原基"},{"q":"组织固定的意义是","o":["使蛋白质迅速溶解","防止细胞自溶","使组织膨胀","使组织坚硬","加大组织成分反差"],"a":1,"e":"组织固定的主要意义是迅速杀死细胞、防止细胞自溶和组织腐败，并维持细胞与组织的原有形态结构。固定并不使蛋白质溶解或组织膨胀；保持硬度只是附带效果；加大反差主要依靠染色和切片制备，而非固定本身"},{"q":"泌尿、生殖系统的主要器官均发生于","o":["间介中胚层","侧中胚层","轴旁中胚层","间充质细胞","体节"],"a":0,"e":"泌尿系统和生殖系统的主要器官均起源于间介中胚层，其在颈部呈节段性生长称生肾节，在尾段形成生肾索。轴旁中胚层形成体节及肌骨；侧中胚层形成体壁和脏壁；间充质细胞为未分化细胞，体节属轴旁中胚层"},{"q":"小脑来源于","o":["端脑","间脑","中脑","后脑","末脑"],"a":3,"e":"小脑由后脑翼板背侧部的菱唇发生，两侧菱唇融合形成小脑板，为小脑原基。端脑演变为大脑半球；间脑形成丘脑等；中脑保持为中脑；末脑演变为延髓，均不形成小脑"},{"q":"软骨细胞的营养依靠","o":["基质中丰富的血管","软骨内小管","毛细血管直接开口于软骨陷窝","通过基质渗透","穿通管"],"a":3,"e":"软骨组织内无血管和淋巴管，深部软骨细胞借助软骨基质良好的渗透性，与周围组织进行物质交换获得营养。基质中并无丰富血管；软骨内无小管；毛细血管不直接开口于软骨陷窝；穿通管为骨组织的结构"},{"q":"心肌纤维内的钙离子主要储存于","o":["肌浆网","肌浆","线粒体","闰盘","横小管"],"a":0,"e":"心肌纤维的钙离子主要储存于肌浆网，兴奋时释放钙离子启动收缩，并依赖横小管传入的少量细胞外钙触发。闰盘为细胞连接结构；线粒体供能；肌浆为胞质基质，均不是钙离子的主要储存库"},{"q":"正中腭裂是由于","o":["外侧腭突与正中腭突未融合","双侧外侧腭突未融合","正中腭突与上颌突未融合","外侧腭突与上颌突未融合","口咽膜未破裂"],"a":1,"e":"正中腭裂因左右外侧腭突未能在中线融合，形成自切齿孔至腭垂的矢状裂隙。外侧腭突与正中腭突未融合导致前腭裂；外侧腭突与上颌突未融合及口咽膜未破裂均非正中腭裂的成因"},{"q":"以下哪项各层富含血管和色素","o":["角膜，巩膜，虹膜","虹膜，睫状体，脉络膜","虹膜，角膜，脉络膜","角膜，虹膜，视网膜","虹膜，睫状体，视网膜"],"a":1,"e":"虹膜、睫状体和脉络膜构成眼球血管膜，主要由富含血管和黑素细胞的疏松结缔组织组成。角膜和巩膜属纤维膜，血管和色素少；视网膜为神经组织，本身不含丰富血管和色素细胞"},{"q":"横小管是骨骼肌纤维的","o":["线粒体","高尔基复合体","粗面内质网","滑面内质网","肌膜向肌质内凹陷而成的小管"],"a":4,"e":"横小管是骨骼肌纤维的肌膜向肌质内凹陷形成的小管，走向与肌纤维长轴垂直，位于明暗带交界处，可传导兴奋。线粒体、高尔基复合体和粗面内质网均为普通细胞器；滑面内质网即肌质网，与横小管不是同一结构"},{"q":"对于生发中心的描述，错误的是","o":["是初级淋巴小结中央着色浅淡的区域","是次级淋巴小结中央着色浅淡的区域","含B细胞、巨噬细胞、滤泡树突状细胞和Th细胞等","分为浅部的明区和其下方的暗区","周边有一层密集的小B细胞形成小结帽"],"a":0,"e":"生发中心只见于受抗原刺激后形成的次级淋巴小结，初级淋巴小结体积小且无生发中心。生发中心含B细胞、滤泡树突状细胞、巨噬细胞和Th细胞，分浅部明区和深部暗区，周边密集小B细胞构成小结帽"},{"q":"大脑皮质运动区较发达的一层是","o":["外锥体细胞层","内颗粒层","外颗粒层","内锥体细胞层","多形细胞层"],"a":3,"e":"大脑皮质运动区以第Ⅴ层内锥体细胞层最发达，该层含大型锥体细胞即Betz细胞，轴突组成投射纤维支配骨骼肌运动。外锥体细胞层以中小型锥体细胞为主；内颗粒层为感觉传入终止层；外颗粒层和多形细胞层均非运动区主要发达层次"},{"q":"球旁细胞的特征是","o":["细胞呈梭形，胞质色浅，核圆居中","胞质内有许多肌丝和分泌颗粒","胞质内肌丝少，有较多分泌颗粒","细胞呈立方形，胞质有许多黏原颗粒","颗粒内有结晶体，含有前列腺素"],"a":2,"e":"球旁细胞由入球微动脉管壁平滑肌细胞转化而成，胞质内肌丝少，粗面内质网和高尔基复合体发达，含较多肾素分泌颗粒。梭形、胞质色浅、核圆居中为平滑肌细胞特点；立方形并含黏原颗粒为黏液细胞；含结晶性颗粒和前列腺素均不符合球旁细胞"},{"q":"与角膜缘结构和功能不符合的是","o":["位于角膜和巩膜移行处","有巩膜静脉窦和小梁网","小梁间有小梁间隙，是房水循环的通道","小梁间隙阻塞可使眼内压升高，导致白内障","巩膜静脉窦为环形小管，管内充满房水"],"a":3,"e":"小梁间隙阻塞使房水回流受阻，眼压升高导致的是青光眼，白内障为晶状体混浊所致，二者不同。角膜缘位于角膜巩膜移行处，含巩膜静脉窦和小梁网，小梁间隙为房水循环通道，巩膜静脉窦为环形管道且充满房水"},{"q":"关于肝巨噬细胞的特征，哪项正确","o":["细胞形态不规则，胞浆嗜碱性","细胞表面突起可附着于内皮细胞表面或伸入内皮间隙","巨噬细胞位于窦周隙内","巨噬细胞由血窦内皮细胞转变而成","巨噬细胞能合成细胞外基质"],"a":1,"e":"肝巨噬细胞表面有大量皱褶和微绒毛，以伪足附着于内皮细胞，或穿过内皮窗孔和细胞间隙伸入窦周隙。其胞质嗜酸性，位于肝血窦内而非窦周隙，由血液单核细胞分化而来，不合成细胞外基质"},{"q":"以下纤维中，哪种又称嗜银纤维","o":["网状纤维","弹性纤维","胶原纤维","微原纤维","肌原纤维"],"a":0,"e":"网状纤维主要由Ⅲ型胶原蛋白构成，表面被覆糖蛋白，镀银染色呈黑色，故又称嗜银纤维。胶原纤维在HE染色呈淡红色但不嗜银；弹性纤维需特殊染色显示；微原纤维和肌原纤维均非嗜银纤维"},{"q":"平滑肌纤维间存在的细胞连接是","o":["中间连接","紧密连接","缝隙连接","桥粒","闰盘"],"a":2,"e":"平滑肌纤维之间存在缝隙连接，可传递信息分子和电冲动，使众多平滑肌纤维同步收缩形成功能整体。中间连接、紧密连接和桥粒为其他细胞连接类型；闰盘为心肌纤维特有的连接结构"},{"q":"神经元的轴突不含","o":["微管","尼氏体","线粒体","微丝","神经丝"],"a":1,"e":"尼氏体由粗面内质网和游离核糖体构成，分布于神经元胞体和树突内，轴突及轴丘中不含尼氏体。微管、微丝和神经丝属于细胞骨架，参与轴突运输与支撑；线粒体供应能量，均可存在于轴突内"},{"q":"在轴突运输中起主要作用的结构是","o":["滑面内质网","高尔基复合体","微丝","突触小泡","微管"],"a":4,"e":"微管构成神经元细胞骨架，并作为轴突运输的轨道，动力蛋白与驱动蛋白沿其将物质顺向或逆向转运，神经丝、微管等也以慢速运输移向终末。微丝主要参与细胞运动与收缩，并非运输轨道；滑面内质网司脂质合成与钙储存；高尔基复合体负责蛋白加工分选；突触小泡贮存神经递质，均不承担轴突运输的主导作用"},{"q":"类骨质是指","o":["新形成未钙化的骨质","黏合线处的骨质","尚未形成骨板的骨质","软骨雏形的基质","软骨陷窝周围的基质"],"a":0,"e":"类骨质是成骨细胞分泌的未钙化骨基质，由胶原纤维和基质构成，随后钙盐沉积形成羟基磷灰石结晶而钙化变硬。软骨雏形的基质属软骨组织，软骨陷窝周围基质为软骨基质，均非骨基质；黏合线是骨重建中新旧骨板间的界限；骨板是钙化后成熟骨质的排列形式，与未钙化的类骨质不同"},{"q":"施万细胞的细胞膜和基膜形成","o":["神经内膜","神经束膜","神经外膜","神经膜","胶质膜"],"a":3,"e":"周围神经纤维中，施万细胞最外面的一层细胞膜与其外面的基膜合称神经膜，对神经纤维有保护和引导再生作用。神经内膜、神经束膜、神经外膜是神经纤维束及神经干的三层结缔组织被膜，由结缔组织构成而非施万细胞膜；胶质膜为中枢神经系统胶质细胞所形成，不属于周围神经施万细胞的结构"},{"q":"刚出生7天的婴儿一直未大便，最可能的诊断是","o":["食管闭锁","十二指肠狭窄","不通肛","环状胰","喂养不当"],"a":2,"e":"不通肛因肛膜未破裂或直肠与肛管未接通，胎便无法排出，出生后持续无大便，是该表现最直接的原因。食管闭锁以吞咽困难、唾液外溢为主；十二指肠狭窄多在生后出现喷射性呕吐；环状胰压迫十二指肠引起肠梗阻也以呕吐为著；喂养不当不致造成出生七日完全无便"},{"q":"参与体液免疫的细胞是","o":["B淋巴细胞","T淋巴细胞","肥大细胞","网状细胞","嗜碱粒细胞"],"a":0,"e":"B淋巴细胞受抗原刺激后分化为浆细胞，分泌抗体进入体液发挥免疫效应，故介导体液免疫。T淋巴细胞参与细胞免疫，其中Th2虽辅助B细胞分化但本身不分泌抗体；肥大细胞参与过敏与炎症反应；嗜碱粒细胞释放组胺等介质；网状细胞构成淋巴组织支架，均非体液免疫的主体细胞"},{"q":"透明角质颗粒存在于表皮的","o":["基底层","棘层","颗粒层","透明层","角质层"],"a":2,"e":"颗粒层由三至五层梭形细胞构成，胞质内出现形状不规则、强嗜碱性的透明角质颗粒，富含组氨酸蛋白并参与角化。基底层为干细胞层，含黑素颗粒；棘层细胞表面有棘状突起由桥粒相连；透明层细胞器已消失、界限不清；角质层为已角化的扁平死细胞，均不含透明角质颗粒"},{"q":"关于游离神经末梢的描述，哪一项是错误的","o":["是感觉神经元的轴突分支","感觉神经元的周围突末端失去髓鞘而成","分布于皮肤表皮或上皮组织内","也可分布于结缔组织和肌组织内","感受冷、热和痛觉"],"a":0,"e":"游离神经末梢是感觉神经元（假单极神经元）周围突末端失去髓鞘形成，周围突在功能上属树突而非轴突，故称其为感觉神经元的轴突分支这一说法错误。它分布于表皮、上皮及结缔组织内，感受冷、热和痛觉。运动神经末梢才是运动神经元轴突的终末结构，两者不可混淆"},{"q":"区别有粒白细胞和无粒白细胞的主要依据是","o":["细胞大小","细胞核形态","有无嗜天青颗粒","有无特殊颗粒","有无吞噬功能"],"a":3,"e":"白细胞按胞质内有无特殊颗粒分为有粒与无粒白细胞，中性、嗜酸、嗜碱粒细胞含特殊颗粒，单核细胞与淋巴细胞不含。嗜天青颗粒为两者共有的溶酶体，不能作为区分依据；细胞大小与核形态在各型间变异较大；有无吞噬功能也不特异，单核细胞与中性粒细胞均有吞噬能力"},{"q":"关于初级卵泡结构，哪项错误","o":["卵泡体积增大","卵泡细胞由单层发育为多层","卵泡周围结缔组织形成一层卵泡膜","透明带由卵泡细胞形成，出现卵泡腔","卵泡细胞之间及卵泡细胞与初级卵母细胞间有缝隙连接存在"],"a":3,"e":"初级卵泡体积增大，卵泡细胞由单层增殖为多层，周围结缔组织形成卵泡膜，细胞间及与卵母细胞间出现缝隙连接；透明带虽在此期形成，但卵泡腔要到次级卵泡期才出现，故该项错误。卵泡腔是次级卵泡的标志，与卵泡细胞多层化及放射冠形成同期出现，并不属于初级卵泡"},{"q":"采用透射电镜术制备和观察标本时，哪一项不正确","o":["取材要新鲜","组织块不需要固定","需制备超薄切片","用重金属染色","在荧光屏上观察"],"a":1,"e":"透射电镜标本需新鲜取材，组织块用戊二醛与锇酸双重固定，脱水树脂包埋后制成超薄切片（50～80nm），再经醋酸铀、柠檬酸铅重金属染色并在荧光屏上观察，故组织块不需要固定一说错误。扫描电镜同样需固定，只是观察表面形貌，二者均离不开固定这一步骤"},{"q":"有关十二指肠腺描述正确的是","o":["黏液性腺，开口于小肠腺之间","黏液性腺，开口于小肠腺底部","黏液性腺，开口于绒毛基部","浆液性腺，开口于小肠腺底部","浆液性腺，开口于胆总管开口处附近"],"a":1,"e":"十二指肠腺位于十二指肠黏膜下层，为黏液腺，导管穿过黏膜肌层开口于小肠腺底部，分泌碱性黏液保护肠黏膜免受胃酸侵蚀。其开口不在小肠腺之间或绒毛基部；称浆液性腺也不符，腮腺为纯浆液腺、胰腺分泌浆液，均与黏液性的十二指肠腺不同"},{"q":"有髓神经纤维的神经冲动传导方式是","o":["在轴膜上连续进行","在轴膜上跳跃式进行","在郎飞结间连续跳跃式进行","在髓鞘切迹间连续跳跃式进行","在结间体间连续跳跃式进行"],"a":2,"e":"有髓神经纤维的轴膜外有髓鞘绝缘，电流只能在髓鞘中断处即郎飞结使轴膜兴奋，冲动从一个郎飞结跳到下一个，故呈跳跃式传导且速度快。沿轴膜连续传导是无髓神经纤维的方式；结间体为相邻两郎飞结间的一段；髓鞘切迹并非兴奋部位，均非跳跃传导的起始点"},{"q":"毛的生长点是","o":["上皮根鞘","毛球","毛乳头","毛根","毛囊"],"a":1,"e":"毛球位于毛根下端并膨大，是毛和毛囊的生长点，其毛母质细胞分裂旺盛使毛不断生长。毛乳头为突入毛球底面的结缔组织，含丰富血管神经，对毛生长起诱导和营养作用而非生长点本身；上皮根鞘包绕毛根；毛根为毛埋入皮肤的部分；毛囊为包裹毛根的结构，均非生长点"},{"q":"小脑皮质颗粒层的神经元包括","o":["浦肯野细胞和颗粒细胞","颗粒细胞和高尔基细胞","颗粒细胞和篮状细胞","颗粒细胞与星形细胞","星形细胞与锥体细胞"],"a":1,"e":"小脑皮质由表及里分分子层、浦肯野细胞层和颗粒层，颗粒层含密集的颗粒细胞和一些高尔基细胞。浦肯野细胞位于浦肯野细胞层，是唯一的传出神经元；篮状细胞和星形细胞位于分子层，均不属于颗粒层，这是小脑皮质分层最易混淆之处"},{"q":"心肌闰盘的横向连接面上有","o":["紧密连接和桥粒","缝隙连接和桥粒","中间连接和桥粒","中间连接和缝隙连接","紧密连接和缝隙连接"],"a":2,"e":"心肌纤维闰盘的横向部分位于Z线水平，有黏着小带（曾称中间连接）和桥粒，使相邻心肌纤维连接牢固；缝隙连接主要位于闰盘的纵向部分，负责传递电冲动。紧密连接多见于上皮细胞顶部，不见于此；故含紧密连接或仅含缝隙连接的组合均与横向连接面的结构不符"},{"q":"具有吞噬功能的细胞是","o":["中性粒细胞","肥大细胞","嗜碱性粒细胞","血小板","红细胞"],"a":0,"e":"中性粒细胞具有很强的趋化作用和吞噬功能，以吞噬细菌为主，也吞噬异物，是血液中主要的吞噬细胞。肥大细胞释放肝素、组胺等参与过敏；嗜碱性粒细胞释放组胺等介质；血小板参与凝血止血；红细胞运输氧和二氧化碳，均不具备吞噬功能"},{"q":"表皮中的干细胞位于","o":["基底层","棘层","颗粒层","透明层","角质层"],"a":0,"e":"基底层附着于基膜，由一层矮柱状基底细胞组成，是表皮的干细胞，不断分裂并分化为棘层细胞。棘层、颗粒层、透明层、角质层均为基底细胞分化后的各阶段，已不同程度分化或角化，其中角质层为死亡的角化细胞，不再具有分裂增殖能力"},{"q":"人体内最坚硬的组织是","o":["牙本质","釉质","牙骨质","骨密质","纤维软骨"],"a":1,"e":"釉质位于牙冠表面，无机物约占96%，有机物极少，是人体最坚硬的结构。牙本质无机成分约占80%，比骨质坚硬但不及釉质；骨密质为骨组织，硬度更低；牙骨质的组成与结构类似骨组织；纤维软骨含大量胶原纤维，均远不及釉质坚硬"},{"q":"耳廓来自于","o":["听泡","第Ⅰ咽囊","第Ⅰ鳃沟","第Ⅰ鳃膜","耳丘"],"a":4,"e":"胚胎第六周第一鳃沟周围间充质增生形成六个结节状隆起即耳丘，围绕外耳道口演变融合成耳郭。听泡（听囊）形成内耳膜迷路；第一鳃沟形成外耳道；第一鳃膜参与鼓膜形成；耳丘是耳郭的原基，副耳郭与耳瘘均与其发育异常相关，来源与上述结构不同"},{"q":"胰岛调节血糖浓度的激素是","o":["A细胞分泌的胰岛素和B细胞分泌的高血糖素","A细胞分泌的高血糖素和B细胞分泌的胰岛素","A细胞分泌的高血糖素和D细胞分泌的生长抑素","B细胞分泌的高血糖素和D细胞分泌的生长抑素","B细胞分泌的胰岛素和D细胞分泌的生长抑素"],"a":1,"e":"A（α）细胞约占胰岛细胞百分之二十，位于胰岛周边，分泌胰高血糖素使血糖升高；B（β）细胞约占百分之七十，位于中央，分泌胰岛素使血糖降低，二者协同维持血糖平衡。D细胞分泌生长抑素，主要起旁分泌调节作用，并不直接调节血糖；将A、B细胞功能互换的选项均与事实相反"},{"q":"下列关于肾的血液循环特点，哪项是错误的","o":["肾内血流量很大","动脉在肾内三次形成毛细血管网","血液流经肾血管球时形成滤液","球后毛细血管网内的胶体渗透压较高","动脉在肾内两次形成毛细血管网"],"a":1,"e":"肾动脉入肾后，入球微动脉分支形成血管球毛细血管网，出球微动脉再形成球后毛细血管网，故肾内两次形成毛细血管网而非三次，该项错误。肾血流量大且约九成供应皮质；血液流经血管球滤过形成滤液；球后毛细血管内因滤过失水而胶体渗透压较高，其余描述均正确"},{"q":"延髓来源于","o":["端脑","间脑","中脑","后脑","末脑"],"a":4,"e":"神经管头段演变为前脑、中脑、菱脑泡，菱脑泡尾段为末脑，末脑演变为延髓。后脑演变为脑桥和小脑；端脑演变为大脑半球；间脑、中脑各自保留，均与延髓来源不同，末脑才是延髓的直接原基"},{"q":"睑板腺的性质是","o":["内分泌腺","汗腺","皮脂腺","浆液性腺","黏液性腺"],"a":2,"e":"睑板腺位于睑板内，为平行排列的分支管泡状皮脂腺，导管开口于睑缘，分泌油脂润滑睑缘并保护角膜。汗腺（如睑缘的睫腺）为单曲管状腺，与睑板腺不同；浆液性腺、黏液性腺的分泌性质也不符；内分泌腺无导管，均非睑板腺所属类型"},{"q":"角膜上皮来自于","o":["表面外胚层","间充质","神经外胚层","内胚层","表面外胚层和间充质"],"a":0,"e":"眼的发生中，眼球前方的表面外胚层分化形成角膜上皮，角膜其余各层由其后方的间充质分化而成。神经外胚层形成视网膜和视神经；内胚层不参与角膜构成；间充质形成角膜基质等层次而非上皮；表面外胚层和间充质合称过于笼统，角膜上皮本身仅源于表面外胚层"},{"q":"神经上皮最初呈","o":["单层扁平上皮","单层立方上皮","单层柱状上皮","假复层柱状上皮","复层扁平上皮"],"a":3,"e":"神经管壁最初由单层柱状上皮构成，以后演变为假复层柱状上皮，称神经上皮。单层扁平上皮见于内皮与间皮；单层立方上皮见于肾小管、甲状腺滤泡；单层柱状上皮是神经上皮的初始形态而非最终形态；复层扁平上皮见于表皮，均非神经上皮的成熟形态"},{"q":"化学突触的突触前膜指的是","o":["轴突的细胞膜","树突的细胞膜","有受体一侧的细胞膜","释放神经递质一侧的细胞膜","神经细胞胞体的细胞膜"],"a":3,"e":"化学突触由突触前成分、突触间隙和突触后成分构成，突触前膜是突触前成分释放神经递质一侧的细胞膜，突触后膜为有受体一侧的细胞膜。轴突或胞体膜的范围过泛，不能等同于突触前膜；树突膜多构成突触后膜；只有以释放递质一侧界定才准确对应突触前膜"},{"q":"组织学中最常用的制片技术是","o":["石蜡切片","火棉胶切片","冰冻切片","涂片","铺片"],"a":0,"e":"石蜡包埋切片经取材、固定、包埋、切片、脱蜡、染色等步骤制成，是组织学最常用的制片技术，配合苏木精-伊红染色应用最广。火棉胶切片用于大块或坚硬组织；冰冻切片用于快速诊断和保存酶活性；涂片用于血液与脱落细胞；铺片用于膜状组织，均非常规首选"},{"q":"大脑皮质多形细胞层内的神经元主要为","o":["颗粒细胞","梭形细胞","锥体细胞","星形细胞","篮状细胞"],"a":1,"e":"大脑皮质多形细胞层（第六层）以梭形细胞为主，还有锥体细胞和上行轴突细胞，梭形细胞轴突组成投射纤维。颗粒细胞主要位于第二、三、四层，构成局部神经环路；锥体细胞主要在第三、五层；星形细胞属神经胶质细胞；篮状细胞为小脑皮质分子层的中间神经元，均非该层主要神经元"},{"q":"关于甲状旁腺的描述，哪项错误","o":["腺细胞分为主细胞和嗜酸性细胞","分泌的激素参与血钙浓度调节","嗜酸性细胞体积大，胞质嗜酸性，核小深染","主细胞分泌的激素属于类固醇类激素","嗜酸性细胞随年龄增长而增多"],"a":3,"e":"主细胞分泌甲状旁腺激素，属含氮类激素而非类固醇激素，故该项错误；类固醇激素仅由肾上腺皮质和性腺分泌。嗜酸性细胞体积大、胞质嗜酸、核小深染且随年龄增长而增多；腺细胞分为主细胞和嗜酸性细胞；甲状旁腺激素参与血钙浓度调节，其余描述均正确"},{"q":"肌性动脉中膜内产生基质和纤维的细胞是","o":["成纤维细胞","间充质细胞","平滑肌细胞","内皮细胞","巨噬细胞"],"a":2,"e":"中动脉中膜富含平滑肌纤维，故称肌性动脉，其平滑肌细胞能产生胶原纤维、弹性纤维和基质，发挥类似成纤维细胞的作用。成纤维细胞主要位于结缔组织；间充质细胞为原始未分化细胞；内皮细胞构成内膜；巨噬细胞司吞噬，均非中膜内产生纤维和基质的细胞"},{"q":"面斜裂的成因是","o":["两侧上颌突未融合","同侧的内、外侧鼻突未融合","额鼻突和外侧鼻突未融合","上颌突与同侧的外侧鼻突未融合","上颌突与同侧的内侧鼻突未融合"],"a":3,"e":"面斜裂位于眼内眦与口角之间，因上颌突与同侧外侧鼻突未融合所致。唇裂多因上颌突与同侧内侧鼻突未融合，裂沟位于人中外侧；两侧上颌突或两侧内侧鼻突未融合导致正中裂；额鼻突与外侧鼻突未融合并非面斜裂机制，注意内侧与外侧鼻突的区别"},{"q":"早期心管的4个膨大，从头端至尾端依次为","o":["心球、心房、心室、静脉窦","心房、心室、心球、静脉窦","心球、心室、心房、静脉窦","静脉窦、心房、心室、心球","心球、心室、心房、动脉干"],"a":2,"e":"心管各段生长速度不均，由头向尾依次形成心球、心室、心房和静脉窦四个膨大，静脉窦末端分为左、右角。将心房与心室顺序颠倒、把静脉窦列于头端，或以动脉干替代静脉窦作为末端的排列，均与心管从头至尾的正常膨大顺序不符"},{"q":"后肾的发生中，来自输尿管芽的部分与生后肾组织的部分的连接点是","o":["肾盏与集合小管相连接","集合小管与远端小管相连接","远端小管与细段相连接","细段与近端小管相连接","近端小管与肾小体相连接"],"a":1,"e":"后肾由输尿管芽与生后肾组织互相诱导分化而成，输尿管芽形成集合管系统，生后肾组织形成肾小管，二者在集合小管与远端小管处接通。若远曲小管与集合管未接通，尿液积聚使肾内出现囊泡。细段、近端小管与肾小体的连接均在肾小管内部，并非两种来源的交界点"},{"q":"肾脏病变可引起蛋白尿，正常情况下重吸收原尿中蛋白质的结构是近端小管上皮的","o":["侧突","顶小管和顶小泡","质膜内褶","细胞间隙","微绒毛"],"a":1,"e":"近端小管上皮微绒毛基部之间的细胞膜凹陷形成顶小管和顶小泡，通过吞饮作用重吸收原尿中的小分子蛋白。微绒毛主要扩大游离面表面积；质膜内褶位于细胞基部，参与水和电解质转运；细胞间隙为物质旁路的通道；侧突为相邻细胞嵌合结构，均非吞饮蛋白质的部位"},{"q":"诱导外胚层增厚形成神经板的结构是","o":["原条","体节","原结","脊索","轴旁中胚层"],"a":3,"e":"脊索形成后诱导其背侧中线的外胚层增厚呈板状，称神经板，继而凹陷成神经沟并闭合为神经管。原条、原结参与三胚层形成；体节、轴旁中胚层分化为骨骼肌和骨等，均非诱导神经板形成的结构，脊索的诱导作用是其形成的关键"},{"q":"精子发生的干细胞是","o":["精子细胞","精子","次级精母细胞","初级精母细胞","精原细胞"],"a":4,"e":"精原细胞紧贴生精小管基膜，其中A型精原细胞是生精细胞中的干细胞，不断分裂增殖，一部分子细胞保持为干细胞，另一部分分化为B型后继续发育。初级、次级精母细胞经减数分裂产生；精子细胞为减数分裂后的单倍体；精子为终末分化产物，均不具备干细胞特性"},{"q":"下列关于蛛网膜和软膜的描述，哪项错误","o":["蛛网膜是薄层结缔组织，有小梁连于软膜","蛛网膜与软膜间的腔隙叫蛛网膜下腔","蛛网膜下腔内有脑脊液，可借蛛网膜颗粒吸收入硬膜静脉窦","软膜内无血管分布","软膜外表面和蛛网膜的內、外表面以及小梁表面都被覆单层扁平上皮"],"a":3,"e":"软膜富含血管，供应脑和脊髓，故软膜内无血管分布一说错误。蛛网膜为薄层结缔组织，有小梁连于软膜，二者之间为蛛网膜下腔，内含脑脊液并借蛛网膜颗粒吸收入硬膜静脉窦；软膜外表面及蛛网膜内、外表面与小梁表面均被覆单层扁平上皮，其余描述正确"},{"q":"输卵管起源于","o":["中肾旁管下段","中肾管下段","中肾旁管上段和横行的中段","尾端中肾小管","中肾管中段"],"a":2,"e":"女性缺乏雄激素及抗中肾旁管激素时，中肾旁管进一步发育，其上段和中段演化为输卵管，下段左右合并演变为子宫及阴道穹。中肾管在女性退化；尾端中肾小管不参与输卵管形成；故凡以中肾管为来源的选项均误，只有中肾旁管上段与横行中段正确"},{"q":"肌质网能够","o":["与粗肌丝相结合","与细肌丝相结合","将肌膜的兴奋迅速传到肌纤维内部","储存Ca2＋","分解ATP并释放能量"],"a":3,"e":"肌质网膜上有钙泵，能逆浓度差将肌质中的钙离子泵入肌质网内贮存，使网内浓度为肌质中的上千倍，参与肌肉舒缩的调节。与粗、细肌丝结合的是横桥等收缩蛋白；将兴奋传入肌纤维内部靠横小管；分解ATP释放能量的是肌球蛋白ATP酶，均非肌质网的功能"},{"q":"关于卵黄囊，哪项正确","o":["人胚卵黄囊内有少量卵黄","卵黄蒂演化为尿囊","卵黄囊壁外附有胚外中胚层","卵黄囊构成原始消化管的一部分","顶部为外胚层"],"a":2,"e":"卵黄囊壁由下胚层构成，其外面附有胚外中胚层，后者参与形成血岛和血管。人胚卵黄囊内并无卵黄，仅存痕迹；卵黄蒂不演化为尿囊，尿囊为后肠向体蒂的突出；卵黄囊不构成原始消化管本身；其顶为下胚层而非外胚层"},{"q":"消化管具有绒毛结构的是","o":["胃","食管","小肠","结肠","阑尾"],"a":2,"e":"小肠黏膜上皮与固有层共同向肠腔突出形成绒毛，以十二指肠和空肠头段最发达，可显著扩大吸收面积。胃黏膜形成胃小凹和皱襞而无绒毛；食管为复层扁平上皮；结肠与阑尾虽有皱襞和肠腺，但均无绒毛，绒毛是小肠的特征性结构"},{"q":"下列细胞中，哪个具有分泌功能","o":["纤毛细胞","杯状细胞","基细胞","Ⅰ型肺泡细胞","梭型细胞"],"a":1,"e":"杯状细胞顶部充满黏原颗粒，分泌黏蛋白，与水结合形成黏液，起润滑和保护上皮的作用。纤毛细胞借纤毛摆动清除异物；基细胞为干细胞；Ⅰ型肺泡细胞参与气体交换并清除表面活性物质；梭形细胞为上皮内的一类细胞，均不以分泌黏液为主要功能"},{"q":"女性体内可产生雄激素的细胞是","o":["肾上腺束状带细胞","胰岛细胞","肾间质细胞","肾上腺网状带细胞","垂体嗜酸性细胞"],"a":3,"e":"肾上腺皮质网状带细胞主要分泌雄激素，女性体内少量雄激素即来源于此，血液中绝大部分睾酮由睾丸间质细胞分泌。束状带分泌糖皮质激素；胰岛细胞分泌胰岛素等；肾间质细胞分泌红细胞生成素；垂体嗜酸性细胞分泌生长激素和催乳素，均不产生雄激素"},{"q":"心脏传导系统","o":["由特殊的神经细胞和神经纤维构成","均位于心内膜下层","包括起搏细胞、移行细胞和普肯耶纤维","各成分之间由细胞质桥连成功能整体","将神经元的起搏冲动传导给普通心肌细胞"],"a":2,"e":"心脏传导系统由起搏细胞、移行细胞和浦肯野纤维三种特殊心肌细胞组成，聚集成结或束。这些细胞是特化的心肌细胞而非神经细胞；窦房结、房室结位于心内膜下但浦肯野纤维伸入心肌，故并非均位于心内膜下层；各成分借缝隙连接构成功能整体而非细胞质桥；起搏冲动源于起搏细胞而非神经元"},{"q":"动脉管壁的分层为","o":["内皮、内皮下层、弹性膜、肌层和外膜","内膜、弹性膜、肌膜和外膜","内膜、肌膜和外膜","内膜、中膜和外膜","内膜、内膜下层、中膜和外膜"],"a":3,"e":"动脉和静脉管壁由管腔向外均分为内膜、中膜、外膜三层，内膜又分内皮、内皮下层和内弹性膜。将内皮、内皮下层、弹性膜等与中膜、外膜并列，或把肌膜单列，均为层次划分错误；内膜下层并非管壁的独立分层，正确的三层即内膜、中膜和外膜"},{"q":"关于脾的结构，哪项正确","o":["红髓色深，由淋巴小结组成","白髓色浅，由血窦组成","动脉周围淋巴鞘主要含B细胞","脾索主要含T细胞","脾索内的淋巴细胞可经内皮间隙进入脾血窦内"],"a":4,"e":"脾血窦内皮细胞间有0.2～0.5μm的间隙，脾索内血细胞可变形穿越内皮间隙进入血窦，衰老红细胞因变形性降低被滞留并由巨噬细胞清除。红髓由脾索和脾血窦组成而非淋巴小结；白髓由动脉周围淋巴鞘、淋巴小结等组成而非血窦；动脉周围淋巴鞘主要含T细胞，脾索主要含B细胞与巨噬细胞，故其余组合均误"},{"q":"二胚层胚盘形成于","o":["底蜕膜","极端滋养层","内细胞群","滋养层","中胚层"],"a":2,"e":"第二周胚泡植入过程中，内细胞群增殖分化形成由上胚层和下胚层组成的圆盘状二胚层胚盘。滋养层构成胚泡壁并参与胎盘形成；极端滋养层与胚泡植入有关；底蜕膜为母体子宫内膜；中胚层到第三周才出现，二胚层胚盘时尚无，故均非其来源"},{"q":"胰腺分泌胰岛素和高血糖素的细胞分别是","o":["A细胞和B细胞","B细胞和A细胞","A细胞和D细胞","D细胞和B细胞","D细胞和A细胞"],"a":1,"e":"胰岛B（β）细胞分泌胰岛素使血糖降低，A（α）细胞分泌胰高血糖素使血糖升高，故先后顺序为B细胞和A细胞。D细胞分泌生长抑素，主要参与旁分泌调节；将A、B细胞顺序颠倒的选项把两种激素与细胞错配，含D细胞的组合也不承担这两个功能"},{"q":"约95%的膀胱肿瘤起源于上皮组织，膀胱和肾盂、输尿管共有的结构特点是","o":["腔面被覆单层立方上皮","腔面被覆变移上皮","腔面被覆复层扁平上皮","都有骨骼肌所包绕","都有三层平滑肌包绕"],"a":1,"e":"肾盏、肾盂、输尿管、膀胱腔面均被覆变移上皮，细胞层数和形态可随器官空虚与扩张而变化。单层立方上皮见于肾小管；复层扁平上皮见于食管和阴道；膀胱肌层为内纵、中环、外纵三层平滑肌，而输尿管上三分之二仅两层，故都有三层平滑肌并非三者共有特点"},{"q":"对视网膜描述，错误的是","o":["主要细胞成分有色素上皮细胞、视细胞、双极细胞和节细胞","神经胶质细胞是müller细胞","光镜下可分为10层","黄斑中央凹处只有视杆细胞","视神经乳头无感光功能"],"a":3,"e":"黄斑中央凹处只有视锥细胞，无视杆细胞，此处视觉最敏锐，故该项错误。视网膜主要细胞成分为色素上皮细胞、视细胞、双极细胞和节细胞；神经胶质细胞为Müller细胞；光镜下可分为十层；视神经乳头因无感光细胞而无感光功能，其余描述均正确"},{"q":"关于桥粒的描述，不正确的是","o":["在上皮细胞顶部呈带状","细胞间隙可见致密的中间线","细胞膜的胞质面有较厚的附着板","附着板上连有张力丝","桥粒是很牢固的细胞连接"],"a":0,"e":"桥粒呈点状分布于细胞侧面，而在上皮细胞顶部环绕呈带状的是黏着小带（曾称中间连接），故在上皮细胞顶部呈带状一说错误。桥粒细胞间隙可见致密的中间线，胞质面有较厚的附着板，附着板上连有张力丝，是很牢固的细胞连接，其余描述均正确"},{"q":"关于动脉的描述，错误的是","o":["大动脉包括主动脉、颈总动脉、锁骨下动脉、肺动脉等","中动脉的管壁3层结构典型","中动脉中膜由10～40层环形平滑肌组成","中动脉又称弹性动脉","小动脉属肌性动脉"],"a":3,"e":"中动脉中膜以环形平滑肌为主，又称肌性动脉或分配动脉；弹性动脉指大动脉，故中动脉又称弹性动脉一说错误。大动脉包括主动脉、颈总动脉、锁骨下动脉和肺动脉等；中动脉管壁三层结构典型、中膜由十至四十层环形平滑肌组成；小动脉属肌性动脉，其余描述均正确"},{"q":"清除淋巴液内抗原的细胞主要是","o":["淋巴窦内皮细胞","淋巴窦内的巨噬细胞","淋巴窦内的星状内皮细胞","滤泡树突细胞","肥大细胞"],"a":1,"e":"淋巴在淋巴窦内缓慢流动，窦内巨噬细胞附着于内皮细胞，可清除淋巴液中的抗原，髓窦内巨噬细胞较多、滤过功能更强。淋巴窦内皮细胞构成窦壁；星状内皮细胞支撑窦腔；滤泡树突细胞参与B细胞的免疫应答；肥大细胞参与过敏反应，均非清除抗原的主要细胞"},{"q":"调节晶状体曲度的主要结构是","o":["瞳孔括约肌","瞳孔开大肌","睫状肌","睫状小带","晶状体纤维"],"a":2,"e":"睫状肌为平滑肌，是睫状体的主要成分，其收缩使睫状体向前内方移动、睫状小带松弛，从而改变晶状体曲度以调节视力。瞳孔括约肌与开大肌调节瞳孔大小；睫状小带为悬吊晶状体的纤维，本身不主动收缩；晶状体纤维为晶状体实质成分，均无调节作用"},{"q":"关于膀胱的描述，正确的为","o":["黏膜上皮为复层扁平上皮","固有层内含较多的腺体","肌层由内纵、中环、外纵三层平滑肌组成","肌层由内环、外纵两层平滑肌组成","膀胱空虚时，上皮仅有3～4层细胞，表层细胞变扁"],"a":2,"e":"膀胱肌层较厚，由内纵行、中环行和外纵行三层平滑肌组成，各层交错、分界不清。膀胱黏膜上皮为变移上皮而非复层扁平上皮；固有层含较多弹性纤维而非腺体；膀胱空虚时上皮变厚、细胞层数增多且盖细胞呈立方形，并非仅3～4层且表层变扁"},{"q":"关于胰腺的描述，下列哪项错误","o":["纯浆液性腺","可见泡心细胞","有较多的纹状管","可见胰岛","闰管较长"],"a":2,"e":"胰腺为纯浆液性腺，闰管较长，可见泡心细胞和胰岛；纹状管（分泌管）发达是下颌下腺的特点，腮腺纹状管较短、舌下腺更短，胰腺并无较多纹状管，故该项错误。泡心细胞与胰岛均为胰腺的正常结构，纯浆液性腺的性质判定也正确"},{"q":"促性腺激素释放激素主要作用于","o":["睾丸","卵巢","子宫","垂体嗜酸性细胞","垂体嗜碱性细胞"],"a":4,"e":"下丘脑分泌的促性腺激素释放激素经垂体门脉系统作用于腺垂体远侧部的嗜碱性细胞，促其分泌卵泡刺激素和黄体生成素。睾丸、卵巢是这些促激素的下游靶器官，并非该释放激素的直接作用部位；垂体嗜酸性细胞分泌生长激素和催乳素，不受促性腺激素释放激素调节"},{"q":"视泡发生于","o":["端脑","前脑","中脑","间脑","末脑"],"a":1,"e":"胚胎第四周神经管前端闭合成前脑，其两侧向外膨出一对泡状结构即视泡，是视网膜和视神经的原基。端脑、间脑、中脑、末脑均为脑的其他分部，视泡明确起源于前脑泡，这是眼发生的基本点，与听泡起源于表面外胚层不同"},{"q":"心外膜内没有","o":["滋养血管","脂肪组织","结缔组织","心肌","平滑肌"],"a":3,"e":"心外膜为浆膜，由结缔组织、脂肪组织、滋养血管及表面的间皮构成，不含心肌。心肌构成心肌膜，是心脏壁的中间层，与心外膜分属不同层次；结缔组织、脂肪组织、滋养血管以及血管壁的平滑肌均可存在于心外膜，唯独心肌不在其中"},{"q":"近端小管上皮基部纵纹在电镜下的结构为","o":["大量纵向的小管和小泡","大量纵向的微管和微丝","许多侧突的分支","质膜内褶和纵向排列的杆状线粒体","质膜内褶和纵向排列的粗面内质网"],"a":3,"e":"近端小管上皮细胞基部有发达的质膜内褶，内褶间含与其平行的纵向杆状线粒体，光镜下呈纵纹，可扩大基底面面积以利于重吸收。大量纵向小管和小泡为顶部的顶小管与顶小泡；微管微丝属细胞骨架；粗面内质网不参与基部纵纹的构成"},{"q":"呼吸性细支气管与终末细支气管的主要区别在于","o":["上皮细胞无纤毛","无杯状细胞","无混合腺","无软骨片","管壁有肺泡开口"],"a":4,"e":"呼吸性细支气管管壁开始出现少量肺泡开口，属肺呼吸部，而终末细支气管属导气部，管壁无肺泡开口。两者上皮均可有纤毛；杯状细胞、混合腺和软骨片在终末细支气管已基本消失，在呼吸性细支气管也不典型，故有无肺泡开口是最主要的区别"},{"q":"肾叶的组成是","o":["两条髓放线之间的皮质迷路","每条髓放线及其周围的皮质迷路","一个肾锥体及其相连的皮质部分","一个肾锥体是一个肾小叶","一个集合管及其相通连的肾单位"],"a":2,"e":"一个肾锥体与其相连的皮质部分构成一个肾叶，肾锥体之间的皮质称肾柱。一条髓放线及其周围的皮质迷路组成一个肾小叶，并非肾叶；两条髓放线之间的皮质迷路只是小叶的一部分；一个集合管及其相通连的肾单位也不是肾叶，注意肾叶与肾小叶的概念区别"},{"q":"阑尾炎手术时候，可根据结肠带寻找阑尾，结肠带是","o":["局部增厚的外纵肌","局部增厚的内环肌","增厚的黏膜肌","黏膜下层中的集合淋巴小结","聚集在外膜中的脂肪细胞"],"a":0,"e":"大肠的外纵行肌局部增厚形成三条结肠带，是手术中寻找阑尾的重要标志；内环行肌节段性增厚则形成结肠袋。黏膜肌为黏膜层内的薄层平滑肌；集合淋巴小结位于固有层；外膜中的脂肪细胞聚集形成脂肪垂，均非结肠带的本质"},{"q":"在HE染色的标本上某结构呈现蓝紫色，则表明该结构的化学性质是","o":["酸性","碱性","中性","嗜银性","异染性"],"a":0,"e":"苏木精为碱性染料，将细胞核等酸性物质染成蓝紫色，呈嗜碱性，故在HE标本上呈蓝紫色的结构其化学性质为酸性。伊红为酸性染料，将细胞质等碱性成分染成红色，呈嗜酸性；中性物质对两种染料亲和力均弱；嗜银性需银染显示；异染性指染色与染料颜色不符，均非蓝紫色的成因"},{"q":"关于骨细胞，下列哪项正确","o":["可同时存在于骨组织和骨膜","松质骨内不存在骨细胞","借缝隙连接与相邻骨细胞连接","粗面内质网和高尔基复合体发达","在骨的吸收过程中发挥主要作用"],"a":2,"e":"骨细胞胞体位于骨陷窝内，突起伸入骨小管，相邻骨细胞的突起以缝隙连接相连，借以传递信息并构成骨组织内的物质输送通道。骨细胞仅存在于骨组织内而不在骨膜；松质骨内同样有骨细胞；粗面内质网和高尔基复合体发达是成骨细胞的特征；骨吸收主要由破骨细胞完成"},{"q":"关于脑垂体神经部的结构成分，哪项错误","o":["含赫林体","含分泌神经元胞体","含无髓神经纤维","含丰富的毛细血管网","含垂体细胞"],"a":1,"e":"神经垂体不含神经元胞体，其内主要有下丘脑视上核、室旁核神经元轴突形成的无髓神经纤维及神经末梢、赫林体、垂体细胞和丰富毛细血管网，故含分泌神经元胞体一说错误。神经元胞体位于下丘脑而不在神经部，其余所列均为神经垂体的结构成分"},{"q":"近端小管管壁上皮的钠泵位于","o":["微绒毛","杆状线粒体外膜","细胞侧突","细胞基部质膜","细胞游离面的质膜"],"a":3,"e":"近端小管上皮细胞基部质膜内褶上有丰富的钠-钾ATP酶即钠泵，可将细胞内钠离子泵出，促进重吸收。微绒毛位于游离面以扩大吸收面积；杆状线粒体提供能量但钠泵位于质膜；细胞侧突为相邻细胞的嵌合结构；游离面质膜含多种转运体但钠泵主要在基部"},{"q":"巩膜来自于","o":["视杯周围间充质的内层","视杯周围间充质的外层","视杯口边缘部的间充质","晶状体周围的间充质","视柄周围的间充质"],"a":1,"e":"视杯周围的间充质分为内、外两层，内层富含血管和色素细胞，分化为血管膜（脉络膜、虹膜基质、睫状体主体），外层分化为巩膜。视杯口边缘部的间充质形成虹膜基质和睫状体主体；视柄形成视神经；晶状体周围的间充质不形成巩膜，故外层间充质是巩膜的来源"},{"q":"软骨的外加性生长不包括","o":["软骨膜内层骨祖细胞的分裂分化","减数分裂","新的基质和纤维的形成","向软骨组织表面添加新的软骨细胞","在发育中的软骨和成熟软骨中，均可见此种生长方式"],"a":1,"e":"软骨的外加性生长依靠软骨膜内层的骨祖细胞分裂分化为软骨细胞，在软骨组织表面添加新的软骨细胞并形成新的基质和纤维，此方式在发育中的软骨和成熟软骨均可见。减数分裂是生殖细胞成熟分裂的方式，与软骨生长无关，故不属于外加性生长"},{"q":"从受精至胎儿娩出约经历","o":["36周","37周","38周","40周","42周"],"a":2,"e":"胚胎学以受精龄计算，从受精之日到胎儿娩出约经38周（约266天）。36周、37周偏短；40周是以末次月经第一天起算的妊娠周数；42周为过期妊娠的界限，均与从受精至胎儿娩出约38周的表述不符"},{"q":"血液中数量最多的白细胞是","o":["中性粒细胞","淋巴细胞","单核细胞","嗜酸性粒细胞","嗜碱性粒细胞"],"a":0,"e":"中性粒细胞是血液中数量最多的白细胞，核呈杆状或分叶状，胞质含嗜天青颗粒和特殊颗粒，具有很强的趋化与吞噬功能。淋巴细胞数量次之；单核细胞较少；嗜酸性粒细胞、嗜碱性粒细胞更少，其中嗜碱性粒细胞数量最少，均远不及中性粒细胞"},{"q":"下列哪一项不属于畸形早发现、早诊断、早防治的常见检查手段","o":["羊水检查","绒毛膜检查","胎儿镜检查","超声检查","X线检查"],"a":4,"e":"产前筛查与诊断常用羊水检查、绒毛膜检查、胎儿镜检查和超声检查等手段。X线检查有电离辐射危害，不宜作为胎儿畸形的常规筛查方法，故不属于常见检查；超声无创可反复应用，羊水与绒毛膜可做染色体和基因诊断，胎儿镜可直视观察"},{"q":"关于外耳的描述，哪项错误","o":["外耳道的皮肤内含皮脂腺，其分泌物为耵聍","耳廓以弹性软骨为支架","鼓膜为半透明薄膜","鼓膜外层上皮与外耳道表皮相延续","鼓膜内层由单层扁平上皮和薄层疏松结缔组织构成"],"a":0,"e":"外耳道皮肤内为耵聍腺（结构类似大汗腺），分泌耵聍，而非皮脂腺，故该项错误。耳郭以弹性软骨为支架；鼓膜为椭圆形半透明薄膜，外层上皮与外耳道表皮相延续，内层由单层扁平上皮和薄层疏松结缔组织构成，其余描述均正确"},{"q":"前神经孔未闭所致的畸形是","o":["无脑儿","脊柱裂","脊膜膨出","脊髓裂","脑积水"],"a":0,"e":"前神经孔未闭会形成无脑畸形，常伴颅顶骨发育不全。后神经孔未闭导致脊髓裂和脊柱裂；脊膜膨出为脊膜经脊柱裂缺损处向外膨出；脑积水为颅内脑脊液异常增多，均非前神经孔未闭的直接结果"},{"q":"环绕脑毛细血管形成胶质膜的细胞是","o":["神经膜细胞","星形胶质细胞","小胶质细胞","少突胶质细胞","室管膜细胞"],"a":1,"e":"星形胶质细胞突起末端膨大形成脚板，附着并包绕脑毛细血管构成胶质膜，参与血-脑屏障。神经膜细胞（施万细胞）形成周围神经的髓鞘；小胶质细胞司吞噬；少突胶质细胞形成中枢神经系统的髓鞘；室管膜细胞衬覆脑室与中央管，均不形成血管周围的胶质膜"},{"q":"心肌纤维内没有","o":["横纹","糖原","脂滴","脂褐素","密体"],"a":4,"e":"密体是平滑肌纤维的特征性结构，心肌纤维内没有密体。心肌纤维有横纹，胞质内含有糖原、脂滴和脂褐素（随年龄增长而增多）；密体与密斑见于平滑肌，与中间丝相连参与收缩，故为心肌所无"},{"q":"淋巴结深层皮质","o":["在被膜下，主要含T细胞","在皮质浅部，主要含B细胞","在皮质深部，主要含T细胞","在髓质浅部，主要含B细胞","在髓质深部，主要含T细胞"],"a":2,"e":"淋巴结深层皮质（副皮质区）位于皮质深部，为弥散淋巴组织，主要含T淋巴细胞，属胸腺依赖区。被膜下淋巴窦和浅层皮质主要含B细胞；髓质位于更深部而非皮质浅部，故其余关于位置和细胞类型的描述均误"},{"q":"微循环是指","o":["小动脉和小静脉之间的血液循环","微动脉和微静脉之间的血液循环","小动脉和毛细血管后微静脉之间的血液循环","微动脉和毛细血管后微静脉之间的血液循环","毛细血管和毛细血管后微静脉之间的血液循环"],"a":1,"e":"微循环指从微动脉到微静脉之间的血液循环，是血液循环和物质交换的基本结构与功能单位。小动脉和小静脉属较大的血管；毛细血管后微静脉只是微循环输出端的一段，不足以概括其全程，故以微动脉至微静脉的界定最为准确"},{"q":"下列哪项参与绒毛膜的形成","o":["外胚层","内胚层","中胚层","胚外中胚层","侧中胚层"],"a":3,"e":"绒毛膜由滋养层和胚外中胚层共同构成，胚外中胚层参与其形成并长入绒毛内形成血管。外胚层与内胚层形成胚体及相关上皮；中胚层为胚内来源；侧中胚层分化为体壁和脏壁等结构，均非绒毛膜的组成来源，故胚外中胚层正确"},{"q":"维生素A贮存于下列何种细胞内","o":["肝细胞","内皮细胞","肝巨噬细胞","贮脂细胞","淋巴细胞"],"a":3,"e":"贮脂细胞（Ito细胞）位于肝窦周隙，胞质内含许多大脂滴，人体摄取的70%～85%的维生素A贮存于此。肝细胞有多种代谢功能但非维生素A主要贮存处；肝巨噬细胞司吞噬；内皮细胞构成血窦壁；淋巴细胞为免疫细胞，均不贮存维生素A"},{"q":"中肠袢在脐腔内旋转时围绕的血管是","o":["腹腔动脉","肠系膜上动脉","回结肠动脉","肠系膜下动脉","脐动脉"],"a":1,"e":"中肠袢以肠系膜上动脉为轴逆时针旋转九十度，头支转至右侧、尾支转至左侧。腹腔动脉供应前肠；回结肠动脉为肠系膜上动脉的分支；肠系膜下动脉供应后肠；脐动脉属胎儿脐循环血管，均非中肠袢在脐腔内旋转所围绕的轴"},{"q":"有孔毛细血管存在于","o":["肌组织","中枢神经系统","肝","骨髓","胃肠黏膜"],"a":4,"e":"有孔毛细血管内皮上有窗孔，利于血管内外中、小分子物质交换，主要分布于胃肠黏膜、某些内分泌腺和肾血管球。肌组织多为连续型毛细血管；中枢神经系统为连续型并参与构成血-脑屏障；肝和骨髓为血窦（不连续型），故胃肠黏膜符合"},{"q":"关于男性假两性畸形的描述，哪项正确","o":["同时具有睾丸和卵巢，外阴介于男女两性之间","只有卵巢，但外阴介于男女两性之间","只有睾丸，但外阴介于男女两性之间","只有卵巢，但外阴似男性","染色体有46，XX和46，XY两种组型"],"a":2,"e":"男性假两性畸形生殖腺为睾丸，核型46，XY，因雄激素分泌不足导致外生殖器向女性方向不完全分化，故外阴介于男女两性之间。同时具有睾丸和卵巢者为真两性畸形；仅有卵巢者为女性假两性畸形；核型46，XX与46，XY两种组型见于真两性畸形的嵌合型"},{"q":"小肠绒毛是","o":["黏膜上皮向肠腔伸出的指状突起","黏膜及黏膜下层向肠腔伸出的突起","上皮细胞表面的小突起","上皮与固有层共同向肠腔突出而形成","上皮、固有层及黏膜肌层共同向肠腔突出而形成"],"a":3,"e":"小肠绒毛由上皮和固有层共同向肠腔突出而成，长0.5～1.5mm，以十二指肠和空肠头段最发达。仅以上皮突出的说法不完整；黏膜与黏膜下层共同突起形成的是皱襞；上皮细胞表面的小突起为微绒毛；包含黏膜肌层的突起也非绒毛，故只有上皮加固有层正确"},{"q":"关于垂体后叶赫林体特征中，哪项是正确的","o":["为嗜碱性团块","为板层状小体","能产生血管升压素","能贮存催乳素","能贮存视上核和室旁核分泌的激素"],"a":4,"e":"赫林体为神经垂体内轴突膨大形成的嗜酸性团块，内含神经分泌颗粒，可贮存下丘脑视上核和室旁核合成的血管升压素与催产素。它并不产生激素（激素在胞体合成），不贮存催乳素（催乳素由腺垂体嗜酸性细胞分泌），板层状小体的描述也不符"},{"q":"杯状细胞的特点是","o":["分布于胃肠黏膜上皮中","胞质内充满酶原颗粒","细胞核大，染色淡","细胞不贴附于基膜","起润滑和保护的作用"],"a":4,"e":"杯状细胞分泌黏蛋白，与水结合形成黏液，起润滑和保护上皮的作用。其散在于小肠、呼吸道等上皮中，胃肠黏膜并非处处都有；胞质内充满黏原颗粒而非酶原颗粒（酶原颗粒属主细胞）；细胞核位于基部且深染并贴附基膜，故其余描述均误"},{"q":"关于弹性纤维的描述，不正确的是","o":["在三种纤维中，数量最多","由弹性蛋白和微原纤维构成","可有分支，交织成网","可被醛复红染为紫色","于HE染色切片难与胶原纤维区别"],"a":0,"e":"三种纤维中数量最多的是胶原纤维，而不是弹性纤维，故该项错误。弹性纤维由弹性蛋白和微原纤维构成，可有分支并交织成网，可被醛复红染为紫色，在HE染色切片中不易与胶原纤维区别，其余描述均正确"},{"q":"汗腺属于","o":["单泡状腺","复泡状腺","单管泡状腺","复管泡状腺","单曲管状腺"],"a":4,"e":"汗腺为单曲管状腺，分泌部盘曲成团位于真皮深层和皮下组织，导管由两层较小的立方形细胞围成。单泡状、复泡状、单管泡状、复管泡状腺的分泌部形态均与汗腺不符，且汗腺导管不分支，故属单曲管状腺"},{"q":"分泌黄体酮的细胞是","o":["膜细胞","颗粒细胞","膜黄体细胞","颗粒黄体细胞","门细胞"],"a":3,"e":"颗粒黄体细胞体积较大、着色浅、位于黄体中央，主要分泌孕激素（黄体酮）和松弛素。膜黄体细胞较小、染色较深、位于周边，与颗粒黄体细胞协同分泌雌激素；膜细胞和颗粒细胞为卵泡细胞阶段；门细胞分泌雄激素，均非黄体酮的来源"},{"q":"红细胞脱去细胞核发生在","o":["原红细胞","早幼红细胞","中幼红细胞","晚幼红细胞","网织红细胞"],"a":3,"e":"红细胞发生历经原红细胞、早幼红细胞、中幼红细胞和晚幼红细胞，晚幼红细胞脱去细胞核成为网织红细胞，入血后变为成熟红细胞。网织红细胞已无细胞核；脱核发生在晚幼红细胞阶段而非更早各期，巨噬细胞可吞噬脱出的细胞核"},{"q":"关于垂体的发生，下列哪项错误","o":["来自外胚层和神经外胚层","由拉特克氏囊和神经垂体芽共同发育而成","拉特克氏囊腔将大部分消失，仅留一小裂隙","神经垂体芽中神经元较少","腺垂体可分化出多种腺细胞"],"a":3,"e":"神经垂体由间脑底部神经外胚层形成的神经垂体芽发育而来，其内主要是下丘脑神经元的轴突，本身并无神经元胞体，故称神经垂体芽中神经元较少一说不成立。垂体来自外胚层和神经外胚层，由拉特克囊与神经垂体芽共同发育，拉特克囊腔大部消失仅留小裂隙，腺垂体分化出多种腺细胞，其余描述正确"},{"q":"内、中、外三个胚层均起源于","o":["胚外中胚层","胚内中胚层","上胚层","下胚层","滋养层"],"a":2,"e":"二胚层胚盘的上胚层细胞增殖，经原条迁移形成内、中胚层，剩余的上胚层改称外胚层，故三胚层均起源于上胚层。下胚层主要形成卵黄囊衬里；胚外中胚层与胚内中胚层仅为中胚层的部分来源；滋养层形成胎盘的胎儿部分，均非三胚层的共同来源"},{"q":"关于皮肤真皮的描述，正确的是","o":["由角化的复层扁平上皮构成","由上皮组织和结缔组织共同构成","由结缔组织构成","为上皮组织的基膜","由平滑肌组织构成"],"a":2,"e":"真皮位于表皮下方，由致密结缔组织构成，分乳头层和网织层。角化的复层扁平上皮构成表皮；表皮由上皮组织构成而非真皮；基膜是上皮与结缔组织之间的薄膜；平滑肌仅见于立毛肌等局部，真皮的主体是结缔组织"},{"q":"关于鼻的呼吸部，错误的是","o":["呼吸部占鼻黏膜的大部分","固有层内有较多的腺体","假复层纤毛柱状上皮的纤毛向外鼻孔摆动","有较多的静脉丛","有温暖湿润空气的作用"],"a":2,"e":"鼻呼吸部假复层纤毛柱状上皮的纤毛向咽部摆动，将黏液及黏附的尘埃、细菌推向咽部咳出，而非向外鼻孔摆动，故该项错误。呼吸部占鼻黏膜的大部分，固有层内有较多腺体和静脉丛，具有温暖湿润空气的作用，其余描述均正确"},{"q":"胞质颗粒内含组胺的细胞是","o":["浆细胞","巨噬细胞","肥大细胞","成纤维细胞","脂肪细胞"],"a":2,"e":"肥大细胞胞质颗粒内含有肝素、组胺、中性粒细胞趋化因子等，脱颗粒释放后参与过敏和炎症反应。浆细胞分泌抗体；巨噬细胞司吞噬和抗原呈递；成纤维细胞合成纤维与基质；脂肪细胞贮存脂肪，均不含组胺颗粒"},{"q":"增生期通常是月经周期的","o":["第1～5天","第4～14天","第5～14天","第5～15天","第5～16天"],"a":2,"e":"增生期（卵泡期）为月经周期的第5～14天，此期卵巢内次级卵泡发育并分泌雌激素，使子宫内膜由残存的基底层增生修复并增厚。第1～5天为月经期；第15～28天为分泌期（黄体期）；第4天仍属月经期，均与增生期不符"},{"q":"关于消化管的外膜描述，错误的是","o":["咽和食管为纤维膜","胃、空肠、回肠为浆膜","十二指肠、升结肠和降结肠的前壁为浆膜","盲肠、横结肠和乙状结肠为浆膜","十二指肠、升结肠和降结肠的前壁为纤维膜"],"a":4,"e":"十二指肠、升结肠和降结肠的前壁为浆膜，后壁为纤维膜，故称其前壁为纤维膜一说错误。咽和食管为纤维膜；胃、空肠、回肠为浆膜；盲肠、横结肠和乙状结肠为浆膜，其余描述均正确"},{"q":"纤毛可见于","o":["小肠上皮","气管上皮","变移上皮","口腔上皮","血管内皮"],"a":1,"e":"气管上皮为假复层纤毛柱状上皮，纤毛细胞游离面有密集纤毛并向咽部摆动以净化空气。小肠上皮为单层柱状，具微绒毛而非纤毛；变移上皮、口腔的复层扁平上皮以及血管内皮均无纤毛，故只有气管上皮可见纤毛"},{"q":"肾上腺皮质球状带","o":["较厚，分泌盐皮质激素","较薄，分泌盐皮质激素","较厚，分泌糖皮质激素","较薄，分泌糖皮质激素","较薄，分泌性激素"],"a":1,"e":"肾上腺皮质由外向内依次为球状带、束状带和网状带，球状带较薄，分泌盐皮质激素（醛固酮）。束状带最厚，分泌糖皮质激素；网状带主要分泌雄激素，故较厚或分泌糖皮质激素、性激素的组合均与球状带不符"},{"q":"患过敏性鼻炎时，鼻分泌物内可见","o":["T淋巴细胞","嗜碱性粒细胞","红细胞","单核细胞","巨噬细胞"],"a":1,"e":"嗜碱性粒细胞与肥大细胞作用基本相同，来源于骨髓同种造血祖细胞，释放组胺等介质并参与过敏反应，故过敏性鼻炎时鼻分泌物中可见。T淋巴细胞参与细胞免疫；红细胞运输气体；单核细胞和巨噬细胞司吞噬与抗原呈递，均非过敏反应的特征性细胞"},{"q":"骨陷窝和骨小管内有","o":["骨细胞","毛细血管","组织液","骨细胞和组织液","血液"],"a":3,"e":"骨细胞胞体位于骨陷窝内，突起伸入骨小管，骨陷窝与骨小管内均含少量组织液，共同构成骨内的物质输送通道。仅有骨细胞或仅有组织液都不完整；毛细血管位于中央管等处，不在骨陷窝和骨小管内；血液更不在其中"},{"q":"关于胃肠道内分泌细胞，下列错误的是","o":["分布于上皮与腺体中","有基底侧突与邻近细胞相接触","在HE染色切片上容易辨认","底部胞质含大量分泌颗粒","分开放型与封闭型两类"],"a":2,"e":"胃肠内分泌细胞单个夹在其他上皮细胞之间，HE染色切片上细胞质染色浅淡、不易辨认，需借助免疫组织化学显示，故该项错误。其分布于上皮与腺体中，有基底侧突与邻近细胞接触，底部胞质含大量分泌颗粒，可分开放型与封闭型两类，其余描述正确"},{"q":"红细胞的血红蛋白可以携带","o":["大量一氧化碳","氧和少量二氧化碳","部分一氧化碳和全部二氧化碳","全部二氧化碳","不包括二氧化碳"],"a":1,"e":"血红蛋白主要运输氧，也能结合并运输少量二氧化碳，大部分二氧化碳则以碳酸氢盐等形式运输。一氧化碳与血红蛋白亲和力极高但属病理情况，并非生理携带对象；全部二氧化碳或完全不包括二氧化碳的说法均不符事实"},{"q":"关于嗜碱性粒细胞，描述正确的是","o":["占白细胞总数的比例最高","细胞质含大量溶酶体","胞核呈圆形","胞质中含嗜碱性特殊颗粒","在急性细菌性感染疾病时明显增多"],"a":3,"e":"嗜碱性粒细胞胞质内含嗜碱性的特殊颗粒，颗粒内有肝素、组胺等介质，参与过敏反应。占白细胞比例最高的是中性粒细胞；胞质含大量溶酶体多见于中性粒细胞；胞核呈分叶状或S形而非圆形；急性细菌感染时明显增多的是中性粒细胞，均非其特点"},{"q":"垂体远侧部腺细胞主要受下列哪种激素调节","o":["结节部分泌的激素","下丘脑弓状核分泌的激素","下丘脑室旁核分泌的激素","神经垂体分泌的激素","下丘脑视上核分泌的激素"],"a":1,"e":"下丘脑弓状核等核团的神经内分泌细胞合成释放激素和抑制激素，经垂体门脉系统到达腺垂体远侧部，调节其各种腺细胞的分泌活动。视上核与室旁核合成血管升压素和催产素，经轴突运输至神经垂体；结节部与神经垂体并不分泌调节远侧部的激素"},{"q":"组成脾白髓的结构有","o":["脾索和淋巴小结","脾索和脾血窦","血窦和边缘窦","脾血窦和动脉周围淋巴鞘","动脉周围淋巴鞘和淋巴小结"],"a":4,"e":"脾白髓由动脉周围淋巴鞘、淋巴小结（脾小体）和边缘区组成，本题以动脉周围淋巴鞘和淋巴小结合乎白髓的构成。脾索和脾血窦属于红髓；边缘窦为边缘区内的血窦，故凡包含脾索、脾血窦的组合均为红髓成分，不能代表白髓"},{"q":"喉气管憩室将发育为","o":["喉和气管","喉、气管和支气管","喉、气管、支气管和肺","气管、支气管和肺","支气管和肺"],"a":2,"e":"喉气管憩室上端发育为喉，中段发育为气管，末端膨大形成肺芽，肺芽反复分支形成主支气管以及肺内各级支气管和肺泡，故其发育为喉、气管、支气管和肺。仅列喉和气管，或仅列支气管和肺均不完整，遗漏了其余衍生结构"},{"q":"与厚表皮比较，薄表皮缺少以下哪一层","o":["透明层","基底层","角化层","棘层","颗粒层"],"a":0,"e":"厚表皮（手掌、足底）由基底到表面分基底层、棘层、颗粒层、透明层和角质层五层，薄表皮的颗粒层和透明层不明显、角质层较薄，其中透明层在薄表皮基本缺如。基底层、棘层和角质层为两者共有，故透明层是薄表皮缺少的层次"},{"q":"大脑皮质多形细胞层的细胞主要有","o":["水平细胞","梭形细胞","篮状细胞","星形细胞","颗粒细胞"],"a":1,"e":"大脑皮质多形细胞层以梭形细胞为主，还有锥体细胞和上行轴突细胞。水平细胞见于小脑皮质分子层；篮状细胞为小脑分子层的中间神经元；星形细胞属神经胶质细胞；颗粒细胞主要位于大脑皮质第二至四层，均非多形细胞层的主要神经元"},{"q":"胞质内有大量粗面内质网、游离核糖体和高尔基复合体的细胞是","o":["未分化的间充质细胞","骨原细胞（或骨祖细胞）","骨细胞","破骨细胞","成骨细胞"],"a":4,"e":"成骨细胞分泌活动旺盛，胞质嗜碱性，电镜下含大量粗面内质网、高尔基复合体和游离核糖体，分泌类骨质。骨原细胞为干细胞，细胞器不发达；骨细胞细胞器减少；破骨细胞富含溶酶体和皱褶缘；未分化的间充质细胞分化程度低，均不符合"},{"q":"巨噬细胞可延化学物质的浓度梯度朝浓度高的部位定向移动，聚集到产生和释放这些物质的部位，这种特点是","o":["吞噬作用","趋化性","抗原呈递作用","分泌功能","变形特性"],"a":1,"e":"巨噬细胞受细菌产物、炎症变性蛋白等趋化因子刺激，沿其浓度梯度朝高浓度部位定向移动并聚集，此特性称趋化性，是发挥功能的前提。吞噬作用指摄取消化异物；抗原呈递指处理提呈抗原；分泌功能指释放细胞因子；变形特性仅指形态改变，均非该定向移动的定义"},{"q":"食管腺","o":["为纯浆液性腺","为管状腺","分泌淀粉酶","位于固有层","位于黏膜下层"],"a":4,"e":"食管腺为黏液性腺，位于食管黏膜下层，导管穿过黏膜开口于食管腔，分泌黏液润滑食管。其并非纯浆液性腺；属复管泡状腺而非管状腺；不分泌淀粉酶；也不位于固有层，故其余描述均误"},{"q":"对伊红亲和力强的结构是","o":["细胞膜","细胞质","细胞核膜","细胞核","核糖体"],"a":1,"e":"伊红为酸性染料，能将细胞质染成红色，细胞质对伊红亲和力强称嗜酸性。苏木精为碱性染料，将细胞核（染色质）染成蓝紫色，核与核膜均嗜碱；核糖体富含RNA而嗜碱；细胞膜主要由脂质和蛋白构成，均非伊红强亲和的结构"},{"q":"可见浆半月的是","o":["胰腺和舌下腺","腮腺和下颌下腺","胰腺和腮腺","腮腺和舌下腺","舌下腺和下颌下腺"],"a":4,"e":"浆半月见于混合腺中黏液腺泡末端由浆液细胞形成的帽状结构，下颌下腺和舌下腺均为混合腺，可见浆半月。腮腺为纯浆液腺，无黏液腺泡故无浆半月；胰腺也是纯浆液腺，故凡含腮腺或胰腺的组合均不出现浆半月"},{"q":"产生肾上腺素的细胞是","o":["嗜铬细胞","肾上腺束状带细胞","肾上腺球状带细胞","肾上腺网状带细胞","交感神经节细胞"],"a":0,"e":"肾上腺髓质的嗜铬细胞中，肾上腺素细胞分泌肾上腺素，占髓质细胞百分之八十以上，其分泌受交感节前纤维支配。束状带分泌糖皮质激素，球状带分泌盐皮质激素，网状带分泌雄激素；交感神经节细胞为神经元，均不产生肾上腺素"},{"q":"箭头所指细胞的功能是","o":["吞噬抗原","分泌抗体","分泌穿孔素杀伤感染细胞","分泌肝素、白三烯等生物活性物质","生成网状纤维"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。依据相关知识点，浆细胞由B淋巴细胞在抗原刺激下分化而来，能分泌抗体，抗体与抗原结合可中和毒素、阻止病原体黏附细胞，参与体液免疫。吞噬抗原主要是巨噬细胞的功能；分泌穿孔素杀伤感染细胞为NK细胞；分泌肝素、白三烯等为肥大细胞；生成网状纤维为成纤维细胞\n\n官方题库中缺失图片"},{"q":"要检测某一组织中是否含有特定的某一非糖蛋白类的蛋白质，并要对该蛋白质进行细胞定位，最佳的检测技术是","o":["扫描电镜技术","PAS反应","孚尔根（Feulgen）反应","免疫组织化学术","原位杂交术"],"a":3,"e":"免疫组织化学术基于抗原与抗体特异性结合的原理，能在组织切片上定性、定位地检测肽和蛋白质，是检测特定非糖蛋白类蛋白质并定位的最佳技术。扫描电镜观察表面形貌；PAS反应显示糖蛋白与糖原；孚尔根反应显示DNA；原位杂交在转录水平检测mRNA，均不适用"},{"q":"下列哪种细胞在功能活跃状态下可形成皱褶缘","o":["软骨细胞","骨祖细胞","成骨细胞","骨细胞","破骨细胞"],"a":4,"e":"破骨细胞功能活跃时贴近骨组织一侧形成皱褶缘，在此释放多种水解酶和有机酸，溶解骨盐、分解有机成分以完成骨吸收。软骨细胞、骨祖细胞、成骨细胞、骨细胞均不形成皱褶缘；骨硬化症患者破骨细胞皱褶缘形成障碍，致骨吸收缺陷、骨质异常硬化"},{"q":"大动脉管壁的主要结构特点是","o":["弹性膜和弹性软骨多","弹性纤维和胶原纤维多","弹性膜和弹性纤维多","弹性纤维和平滑肌纤维多","胶原纤维多"],"a":2,"e":"大动脉中膜含多层弹性膜和大量弹性纤维，而平滑肌纤维较少，故又称弹性动脉，弹性膜与弹性纤维多是其结构特点。血管壁中并无弹性软骨；胶原纤维多见于外膜且非主要特点；平滑肌纤维多是中动脉（肌性动脉）的特点，均与大动脉不符"},{"q":"排卵时卵母细胞处于","o":["第一次减数分裂前期","第一次减数分裂中期","第二次减数分裂前期","第二次减数分裂中期","第二次减数分裂末期"],"a":3,"e":"排卵前36～48小时初级卵母细胞完成第一次减数分裂形成次级卵母细胞，随即进入第二次减数分裂并停滞于中期，故排卵时卵母细胞处于第二次减数分裂中期。第一次减数分裂前期和中期属排卵前阶段；第二次减数分裂需在受精时方完成，末期更不相符"},{"q":"内、外弹性膜均明显的血管是","o":["大静脉","中静脉","小静脉","大动脉","中动脉"],"a":4,"e":"中动脉内膜与中膜交界处有一至二层明显的内弹性膜，中膜与外膜交界处有断续的外弹性膜，故内、外弹性膜均明显。大动脉的内弹性膜不明显；静脉的内弹性膜不如中动脉明显且无外弹性膜，各型静脉均不符合"},{"q":"关于螺旋器的结构，哪项错误","o":["位于膜蜗管的基底膜上","由支持细胞和毛细胞组成","支持细胞主要有柱细胞和指细胞","柱细胞的胞质内有丰富的张力原纤维，起支持作用","毛细胞顶部的静纤毛伸入壶腹帽的胶质内"],"a":4,"e":"螺旋器位于膜蜗管的基底膜上，由支持细胞和毛细胞组成，支持细胞主要有柱细胞和指细胞，柱细胞胞质内含丰富的张力原纤维起支持作用；毛细胞顶部的静纤毛插入盖膜胶质，而非壶腹帽。壶腹帽是壶腹嵴的结构，故该项错误"},{"q":"来自内、中、外三个胚层的是","o":["外耳道","鼓膜","咽鼓管","听小骨","膜蜗管"],"a":1,"e":"鼓膜外层为复层扁平上皮，来自第一鳃沟底部的外胚层；内层为单层扁平上皮，来自第一咽囊的内胚层；中层结缔组织来自两者之间的间充质（中胚层），故鼓膜由内、中、外三个胚层共同形成。外耳道来自外胚层，咽鼓管来自内胚层，听小骨来自中胚层，膜蜗管来自表面外胚层，均为单一胚层来源"},{"q":"有关位觉和听觉感受器，哪项错误","o":["均有毛细胞","均有感觉神经元","均有柱形支持细胞","均有传入神经末梢","表面均有胶状物覆盖"],"a":1,"e":"位觉和听觉感受器（壶腹嵴、位觉斑、螺旋器）均含毛细胞、支持细胞和传入神经末梢，表面覆有胶状物（壶腹帽、耳石膜、盖膜），但感受器本身并不含感觉神经元胞体，其神经元胞体位于前庭神经节和耳蜗神经节，故该项错误"},{"q":"视杆细胞和视锥细胞来自胚胎的","o":["视柄","视杯外层","视杯内、外两层","视杯内层","晶状体泡"],"a":3,"e":"视杯内层增厚，自第五周起先后分化出节细胞、视锥细胞、水平细胞、视杆细胞和双极细胞等；视杯外层分化为色素上皮层。视柄形成视神经；视杯内、外两层共同构成视网膜视部但视细胞仅来自内层；晶状体泡形成晶状体，故视杆与视锥细胞源于视杯内层"},{"q":"关于眼球壁血管膜的分部，哪项正确","o":["血管层、色素上皮层、睫状体","虹膜、睫状体、脉络膜","睫状体、脉络膜、色素上皮层","血管层、睫状体、色素上皮层","虹膜、血管层、睫状体"],"a":1,"e":"血管膜由富含血管和黑素细胞的疏松结缔组织构成，从前向后依次分为虹膜、睫状体和脉络膜三部分。色素上皮层属于视网膜而非血管膜；血管层并非血管膜的分部名称；故含色素上皮层或以血管层替代的分部均误"},{"q":"在肝纤维化病变中，贮脂细胞的作用类似于","o":["单泡脂肪细胞","多泡脂肪细胞","肝巨噬细胞","成纤维细胞","肥大细胞"],"a":3,"e":"贮脂细胞位于肝窦周隙，具有产生胶原的功能，在肝纤维化等病理状态下增多并转化为成纤维细胞，合成胶原的功能增强，故其作用类似成纤维细胞。单泡与多泡脂肪细胞主司贮脂；肝巨噬细胞司吞噬；肥大细胞参与过敏，均不大量合成胶原"},{"q":"用煌焦油蓝染色呈细网状的血细胞是","o":["红细胞","淋巴细胞","单核细胞","网织红细胞","中性粒细胞"],"a":3,"e":"网织红细胞是尚未完全成熟的红细胞，胞内尚残留部分核糖体，用煌焦油蓝染色呈细网状，故名。成熟红细胞的核糖体已消失，不呈网状；淋巴细胞、单核细胞和中性粒细胞均为有核白细胞，其胞质颗粒的染色特征与此不同"},{"q":"消化管的上皮来源于","o":["内胚层","外胚层","胚内中胚层","胚外中胚层","间介中胚层"],"a":0,"e":"内胚层被包入胚体形成原始消化管，分化为咽喉及其以下的消化管、消化腺、呼吸道和肺的上皮组织等。外胚层形成肛管下段上皮及口腔部分；胚内中胚层形成结缔组织与肌层；胚外中胚层不参与；间介中胚层形成泌尿生殖系统，均非消化管上皮的来源"},{"q":"气管上皮由以下哪组细胞组成","o":["纤毛细胞、杯状细胞、基细胞、克拉拉细胞","柱状细胞、杯状细胞、基底细胞、潘氏细胞、小颗粒细胞","纤毛细胞、杯状细胞、梭形细胞、刷细胞、颗粒细胞","纤毛细胞、杯状细胞、基底细胞、刷细胞、小颗粒细胞","柱状细胞、壁细胞、基细胞、杯状细胞、刷细胞"],"a":3,"e":"气管上皮为假复层纤毛柱状上皮，由纤毛细胞、杯状细胞、刷细胞、基细胞（基底细胞）和小颗粒细胞组成。克拉拉细胞位于细支气管；潘氏细胞位于小肠腺；梭形、锥形细胞为该上皮细胞的别称但未列全；壁细胞位于胃底腺，均不属于气管上皮的组成"},{"q":"有关胃底腺的主细胞，哪项正确","o":["主要分布在胃底腺上部","分泌胃蛋白酶","分泌胃蛋白酶原","分泌内因子","大量粗面内质网聚集于顶部胞质"],"a":2,"e":"胃底腺主细胞又称胃酶细胞，主要分布于腺的下半部，分泌胃蛋白酶原，其粗面内质网聚集于基部胞质而非顶部。分泌胃蛋白酶是其激活后的形式，并非主细胞直接分泌；内因子由壁细胞分泌，故其余描述均误"},{"q":"心球的一部分参与形成","o":["左心室","右心室","左心房","右心房","静脉窦"],"a":1,"e":"心球尾段膨大并被心室吸收，成为原始右心室，原来的心室成为原始左心室。左、右心房由心房分隔形成；静脉窦参与形成右心房固有部等结构，均非心球直接形成，故右心室是心球参与形成的结构"},{"q":"在化学突触的突触前成分胞质内，含神经递质的结构是","o":["突触小泡","微丝","微管","线粒体","滑面内质网"],"a":0,"e":"突触小泡内含神经递质或神经调质，不同递质对应圆形清亮、小颗粒型、扁平清亮等不同类型的小泡。微丝与微管属细胞骨架；线粒体为突触活动供能；滑面内质网参与脂质合成与钙调节，均不贮存神经递质"},{"q":"出生后血循环发生变化的主要原因是","o":["动脉导管的闭锁","静脉导管的闭锁","卵圆孔的关闭","左右心房不再相通","胎盘血循环中断和肺开始呼吸"],"a":4,"e":"胎儿出生后胎盘循环停止、肺开始呼吸，引起脐静脉和静脉导管闭锁、动脉导管闭锁、卵圆孔关闭等一系列改变，是血液循环发生变化的根本原因。动脉导管闭锁、静脉导管闭锁、卵圆孔关闭均为其具体结果；左右心房不再相通是卵圆孔关闭的表现，均属继发改变"},{"q":"对神经元描述错误的是","o":["细胞核大，染色淡，核仁明显","胞质含嗜酸性的尼氏体","硝酸银染色可见胞体和突起内含神经原纤维","突起可分为轴突和树突","可接受刺激，产生和传导冲动"],"a":1,"e":"尼氏体具有强嗜碱性，由发达的粗面内质网和游离核糖体构成，并非嗜酸性，故该项错误。神经元细胞核大、染色淡、核仁明显；硝酸银染色可见胞体和突起内的神经原纤维；突起分轴突与树突；神经元能接受刺激、产生并传导冲动，其余描述均正确"},{"q":"生后肾原基可演变为","o":["肾盂","肾盏","集合小管","输尿管","肾小管"],"a":4,"e":"输尿管芽末端诱导生后肾组织细胞团先形成小泡，再演化为S形肾小管，进而分化为近端小管、细段和远端小管，其一端膨大凹陷形成肾小体。肾盂、肾盏、集合小管和输尿管均来自输尿管芽，而非生后肾组织，故肾小管正确"},{"q":"关于甲状腺滤泡旁细胞的描述，正确的是","o":["胞质内有嗜银颗粒，分泌物多由细胞基底面释放","胞质内有嗜银颗粒，分泌物多由细胞顶部释放","胞质内有嗜铬颗粒，分泌物多由细胞侧面释放","胞质内有嗜铬颗粒，分泌物多由细胞顶部释放","胞质内有嗜铁颗粒，分泌物多由细胞基底面释放"],"a":0,"e":"甲状腺滤泡旁细胞用镀银染色可见胞质内黑色的嗜银分泌颗粒，其分泌的降钙素多由细胞基底面释放入血。该细胞为嗜银颗粒而非嗜铬或嗜铁颗粒；其顶部被相邻的滤泡上皮细胞覆盖，分泌物并不从顶部释放，故含嗜铬、嗜铁或顶部释放的选项均误"},{"q":"被覆肾盂和肾盏腔面的上皮是","o":["单层柱状上皮","复层柱状上皮","假复层柱状上皮","复层扁平上皮","变移上皮"],"a":4,"e":"肾盏、肾盂、输尿管、膀胱的腔面均被覆变移上皮，其细胞层数和形态可随器官空虚与扩张而改变。单层柱状上皮见于胃、肠、胆囊；复层柱状上皮见于睑结膜和男性尿道；假复层柱状上皮见于呼吸道；复层扁平上皮见于食管和阴道，均非肾盂肾盏的上皮"},{"q":"内耳上皮来源于","o":["表面外胚层","神经外胚层","内胚层","菱脑两侧壁的神经细胞","间充质"],"a":0,"e":"内耳的原基为听泡，由菱脑两侧的表面外胚层在诱导下增厚形成听板，继而内陷为听窝、听泡，成为内耳膜迷路的原基，故内耳上皮源于表面外胚层。神经外胚层形成视泡；内胚层形成中耳等结构；菱脑神经细胞与间充质均非内耳上皮的来源"},{"q":"上皮细胞侧突最发达的是","o":["近端小管","远端小管","细段","直集合管","弓形集合管"],"a":0,"e":"近端小管上皮细胞侧面有许多侧突，相邻细胞的侧突相互嵌合，使光镜下细胞分界不清，侧突与基部质膜内褶共同扩大重吸收面积，是重吸收原尿成分的主要部位。远端小管细胞较小且无刷状缘；细段上皮薄；集合管上皮侧突不发达，均不及近端小管"},{"q":"血-睾屏障结构异常，会导致精子抗原物质溢出到生精小管外而发生自体免疫反应，从而引起男性不育。关于血-睾屏障的叙述，哪项是正确的","o":["是支持细胞间的紧密连接构成","是由生精上皮、基膜和支持细胞的紧密连接构成","防止细菌侵入生精小管影响精子发生","血-睾屏障影响生精小管的雄激素浓度，不利于精子发生","是由毛细血管内皮及基膜、结缔组织、生精上皮基膜和支持细胞间紧密连接构成"],"a":4,"e":"血-睾屏障由毛细血管内皮及其基膜、结缔组织、生精上皮基膜和支持细胞间的紧密连接构成，可阻止精子抗原逸出引发自身免疫，并维持有利于精子发生的微环境。仅以支持细胞紧密连接概括并不完整；生精上皮只是其中一层；屏障阻挡有害物质而非专门防细菌；且有助于维持较高的雄激素浓度以利生精，故其余选项均误"},{"q":"关于嫌色细胞的描述，错误的是","o":["细胞体积小","细胞着色浅","细胞数量较多","分布于腺垂体","属于神经胶质细胞"],"a":4,"e":"嫌色细胞是腺垂体远侧部的一类腺细胞，体积小、着色浅、数量较多，并非神经胶质细胞，故该项错误。神经胶质细胞属神经系统，包括星形胶质细胞、少突胶质细胞、小胶质细胞等，与腺垂体的嫌色细胞在来源和功能上完全不同"},{"q":"次级卵母细胞的第二次减数分裂完成时间和部位是","o":["排卵前；卵巢内","受精前；输卵管外","排卵时；输卵管内","受精时；输卵管内","受精时；子宫腔内"],"a":3,"e":"次级卵母细胞停滞于第二次减数分裂中期，排卵后进入并停留在输卵管壶腹部，受精时受精子穿入的激发才完成第二次减数分裂。第一次减数分裂在排卵前完成；未受精则退化而不完成第二次分裂；受精部位在输卵管而非子宫腔，故其余组合均误"},{"q":"哪一项不是血-胸腺屏障的组成","o":["连续型毛细血管和内皮细胞间的紧密连接","内皮细胞周围不连续的基膜","血管周隙及其内含的巨噬细胞","胸腺上皮细胞基膜","连续的胸腺上皮细胞突起"],"a":1,"e":"血-胸腺屏障由连续毛细血管及其内皮细胞间完整的紧密连接、内皮周围连续的基膜、含巨噬细胞的血管周隙、上皮基膜和一层连续的胸腺上皮细胞突起组成，故内皮细胞周围不连续的基膜不是其组成。连续型内皮、血管周隙巨噬细胞、上皮基膜与胸腺上皮突起均为屏障成分"},{"q":"下列细胞分化方向正确的是","o":["骨祖细胞→成软骨细胞→骨细胞","成骨细胞→破骨细胞","单核细胞→破骨细胞","成软骨细胞→软骨细胞→破骨细胞","骨祖细胞→成骨细胞→软骨细胞"],"a":2,"e":"破骨细胞是一种可游走的多核巨细胞，一般认为由多个单核细胞融合而成，属单核吞噬细胞系统，故单核细胞分化为破骨细胞的方向正确。骨祖细胞分化为成骨细胞或成软骨细胞，并不跨分为骨细胞或软骨细胞；成骨细胞不分化为破骨细胞；成软骨细胞分化为软骨细胞后不再变为破骨细胞"},{"q":"胞质内含嗜碱性分泌颗粒的细胞是","o":["成纤维细胞","浆细胞","巨噬细胞","纤维细胞","肥大细胞"],"a":4,"e":"肥大细胞胞质内充满粗大的嗜碱性分泌颗粒，可被醛复红染为紫色，颗粒含肝素、组胺等介质，参与过敏和炎症反应。成纤维细胞与纤维细胞合成纤维和基质；巨噬细胞司吞噬；浆细胞胞质虽嗜碱但富粗面内质网并分泌抗体，其颗粒并非嗜碱性分泌颗粒，故肥大细胞最符合"},{"q":"关于缝隙连接的特点哪项错误","o":["也见于心肌细胞之间","由6个柱状亚单位组成，中央有小管通连","未连接处相邻细胞间有狭小间隙","相邻细胞间有许多细丝相连","有传递化学信息和电冲动作用"],"a":3,"e":"缝隙连接处相邻细胞膜高度平行，细胞间隙仅约3nm，连接点由六个柱状亚单位围成中央小管通连，可传递化学信息和电冲动，也见于心肌细胞之间。相邻细胞间由细丝状物相连是黏着小带、桥粒等连接的特点，并非缝隙连接，故该项错误"},{"q":"长骨增长的主要原因是","o":["初级骨化中心的出现","骺板软骨的不断生长和骨化","次级骨化中心的出现","骨膜内成骨细胞的成骨","骨领的出现"],"a":1,"e":"长骨的加长依靠骺板软骨不断增生并替换成骨来实现，骺板是长骨继续延长的结构基础。初级、次级骨化中心的出现参与骨化过程但非持续加长的原因；骨膜成骨细胞的成骨使骨增粗；骨领的出现是早期骨膜成骨现象，均非长骨纵向增长的主因"},{"q":"对消化管皱襞形成的正确描述是","o":["上皮突向管腔","上皮和固有层突向管腔","上皮、固有层和黏膜肌层突向管腔","黏膜和部分黏膜下层突向管腔","黏膜、黏膜下层和肌层突向管腔"],"a":3,"e":"消化管皱襞由黏膜与黏膜下层共同向管腔突起形成，可扩大黏膜表面积。仅上皮突起或上皮加固有层突起形成的是绒毛；连同黏膜肌层的描述仍限于黏膜范围；连同肌层突起更非皱襞，故只有黏膜和部分黏膜下层突向管腔正确"},{"q":"对于球旁细胞的最佳描述是","o":["由入球微动脉的平滑肌细胞分化而成","由肾小囊壁层的上皮细胞分化而成","形成致密斑","由入球微动脉的内皮细胞分化而成","分泌抗利尿激素"],"a":0,"e":"球旁细胞位于近肾小体血管极处，由入球微动脉管壁的平滑肌细胞分化为上皮样细胞，分泌肾素。致密斑由远曲小管上皮细胞分化而成；球旁细胞并非由内皮细胞分化；抗利尿激素由下丘脑视上核合成并经神经垂体释放，均非球旁细胞的结构或功能"},{"q":"甲状腺滤泡上皮来源于","o":["表面外胚层","神经外胚层","中胚层","内胚层","间充质"],"a":3,"e":"甲状腺滤泡上皮来源于内胚层。内胚层被包入胚体形成原始消化管，其上皮向腹侧突出形成甲状腺原基，故滤泡上皮属内胚层来源。表面外胚层主要形成表皮与神经嵴以外的表层结构，神经外胚层形成神经管和神经嵴，中胚层与间充质形成结缔组织、血管等，均不构成甲状腺滤泡上皮"},{"q":"神经嵴演化所形成的结构是","o":["脑神经节、肾上腺嗜铬细胞","脊神经节、小脑","脑神经节、脑垂体","脊神经节、髓核","脊神经节、肾上腺皮质"],"a":0,"e":"神经嵴演化所形成的结构是脑神经节、肾上腺嗜铬细胞。神经嵴细胞迁移分化为脑神经节、脊神经节的感觉神经元，并迁入肾上腺原基分化为髓质嗜铬细胞。小脑源于神经管，脑垂体源于口凹表面外胚层与脑泡神经外胚层，髓核源于脊索，肾上腺皮质源于中胚层，均非神经嵴产物"},{"q":"胰腺炎是胰腺因蛋白酶的自身消化作用而引起的疾病，导致胰腺炎的蛋白酶源自","o":["胃底腺的主细胞合成分泌","胃底腺的壁细胞合成分泌","胰腺的腺泡合成分泌","肝细胞合成分泌","小肠腺潘氏细胞合成分泌"],"a":2,"e":"胰腺炎的蛋白酶源自胰腺的腺泡。胰腺外分泌部的腺泡细胞分泌胰蛋白酶原等多种消化酶原，入小肠后被肠激酶激活为胰蛋白酶，自身消化即由此而来。胃底腺主细胞分泌胃蛋白酶原，壁细胞分泌盐酸与内因子，肝细胞分泌胆汁，小肠腺潘氏细胞分泌溶菌酶，均非胰蛋白酶来源"},{"q":"胰岛PP细胞分泌","o":["胰高血糖素","胰岛素","生长抑素","胰多肽","促胰液素"],"a":3,"e":"胰岛PP细胞分泌胰多肽。PP细胞即胰多肽细胞，分泌胰多肽，可抑制胃肠运动、胰液分泌及胆囊收缩。胰高血糖素由A细胞分泌，胰岛素由B细胞分泌，生长抑素由D细胞分泌，促胰液素由十二指肠S细胞分泌，这些细胞类型与其产物常被互换设错"},{"q":"肝小叶内不与血浆接触的是","o":["肝细胞血窦面的微绒毛","库普弗细胞","肝细胞胆小管面的微绒毛","肝血窦内皮细胞","贮脂细胞"],"a":2,"e":"肝小叶内不与血浆接触的是肝细胞胆小管面的微绒毛。胆小管面朝向相邻肝细胞间的胆小管，内含胆汁而非血浆；血窦面的微绒毛则浸于窦周隙的血浆中。库普弗细胞位于肝血窦内，肝血窦内皮细胞构成血窦壁，贮脂细胞位于窦周隙，三者均直接接触血浆或血液成分"},{"q":"间皮可见于","o":["肺泡上皮","腹膜腔表面","血管外表面","心脏内表面","肾小囊壁层"],"a":1,"e":"间皮可见于腹膜腔表面。间皮是覆盖胸膜、腹膜和心包膜表面的单层扁平上皮，腹膜腔表面即由间皮覆盖。肺泡上皮为单层扁平上皮但属肺泡上皮而非间皮；血管外表面为结缔组织；心脏内表面为内皮；肾小囊壁层为单层扁平上皮，均不称间皮"},{"q":"参与心房分隔的结构有","o":["第一房间隔和第二房间隔","房间隔和心内膜垫","房间隔和动脉干嵴","房间隔和室间隔膜部","房间隔和心球嵴"],"a":1,"e":"参与心房分隔的结构有房间隔和心内膜垫。心房分隔时第一、第二房间隔相继发生，向心内膜垫生长并与之融合，卵圆孔瓣即由第一房间隔形成，故两者共同参与。仅列第一、第二房间隔而遗漏心内膜垫并不完整；心球嵴参与心室膜部及动脉干分隔，室间隔膜部属心室分隔结构，与心房分隔无关"},{"q":"与鼻腔形成有关的结构是","o":["内侧鼻突","外侧鼻突","鼻窝","口咽膜","正中腭突"],"a":2,"e":"与鼻腔形成有关的结构是鼻窝。鼻窝向深部扩大形成原始鼻腔，口鼻膜破裂后与口腔相通，是鼻腔发生的直接原基。内侧鼻突主要形成上唇内侧部与鼻中隔，外侧鼻突形成鼻侧壁与鼻翼，口咽膜为原始口腔与咽之间的薄膜，正中腭突形成腭前部，均非鼻腔本体来源"},{"q":"肝小叶缺血性坏死通常先发生于小叶中央部位，与此现象无关的血流因素是","o":["携带丰富营养物质的门静脉分支形成小叶间静脉","携带丰富氧气的肝动脉分支形成小叶间动脉","源于小叶间静脉的血液注入肝血窦","源于小叶间动脉的血液注入肝血窦","中央静脉的血液汇入小叶下静脉"],"a":4,"e":"与此现象无关的血流因素是中央静脉的血液汇入小叶下静脉。肝血窦血液由周边小叶间动脉、小叶间静脉汇入，向中央静脉方向流动，氧与营养渐被肝细胞摄取，故小叶中央先缺血坏死。中央静脉将血导出至小叶下静脉属流出环节，不决定中央区的氧供，与缺血无关；其余四项均为血液进入肝血窦的途径"},{"q":"关于肾上腺网状带的特征，哪项是错误的","o":["细胞索吻合成网状","网孔中有窦状毛细血管","胞质的脂滴含量是三个带中最多的","具有分泌类固醇激素细胞的超微结构特征","可分泌雄激素"],"a":2,"e":"关于肾上腺网状带，错误的是胞质的脂滴含量是三个带中最多的。脂滴最多的是束状带细胞，其胞质富含脂滴呈泡沫状；网状带细胞脂滴较少，主要分泌雄激素。网状带细胞索吻合成网、网孔含窦状毛细血管、具类固醇激素分泌细胞超微结构并分泌雄激素，均属实"},{"q":"鼻呼吸部黏膜不具备哪个结构特点","o":["上皮为复层扁平上皮","生活状态的黏膜呈淡红色","固有层的静脉丛丰富","固有层有丰富的淋巴组织","固有层内有丰富的腺体"],"a":0,"e":"鼻呼吸部黏膜不具备的特点是上皮为复层扁平上皮。鼻呼吸部黏膜上皮为假复层纤毛柱状上皮，夹有杯状细胞，并非复层扁平上皮。其固有层静脉丛丰富可调节气流温度，淋巴组织与腺体发达，生活状态因充血呈淡红色，这些都是呼吸部黏膜的正常特征"},{"q":"心肌的二联体位于","o":["A带和I带交界处","Z线","H带","M线","A带中间"],"a":1,"e":"心肌的二联体位于Z线。心肌横小管较粗，位于Z线水平，与一侧终池紧贴形成二联体，因终池少而小故贮钙能力低。A带与I带交界处是骨骼肌横小管的位置，H带为暗带中央浅带，M线为H带中央，A带中间为暗带中部，均非心肌二联体所在水平"},{"q":"形成女性生殖管道的结构是","o":["中肾旁管","中肾管","中肾小管","前肾管","尿生殖窦"],"a":0,"e":"形成女性生殖管道的结构是中肾旁管。中肾旁管又称米勒管，卵巢形成后因无雄激素及抗中肾旁管激素，其中段发育为输卵管，下段合并形成子宫及阴道穹。中肾管在无雄激素时退化，中肾小管仅形成输出小管相关结构，前肾管趋于退化，尿生殖窦主要形成阴道下段及泌尿窦衍生物"},{"q":"Turner综合征属于","o":["性染色体单体型","性染色体三体型","常染色体数目增多","常染色体数目减少","染色体结构畸变"],"a":0,"e":"Turner综合征属于性染色体单体型。其核型为45，X，仅有一条X染色体，故属性染色体数目减少中的单体型。性染色体三体型如Klinefelter综合征核型47，XXY；常染色体数目增减如21三体为常染色体畸变；染色体结构畸变指易位、缺失等，均与Turner综合征的45，X核型不符"},{"q":"泄殖腔是","o":["后肠末段膨大","原始直肠末段膨大","尿囊末段膨大","尿生殖窦末段膨大","由后肠与尿囊汇合形成"],"a":0,"e":"泄殖腔是后肠末段膨大。后肠末端膨大形成泄殖腔，其腹侧与尿囊相通，尾端以泄殖腔膜封闭。原始直肠末段、尿囊末段、尿生殖窦末段均非泄殖腔本体：尿生殖窦是泄殖腔被尿直肠隔分隔后的腹侧份，泄殖腔也非后肠与尿囊简单汇合，而是一个独立膨大结构"},{"q":"睾丸内吞噬并消化精子残余胞质的细胞是","o":["精原细胞","精子细胞","管周肌样细胞","间质细胞","支持细胞"],"a":4,"e":"睾丸内吞噬并消化精子残余胞质的细胞是支持细胞。支持细胞在精子形成中吞噬消化脱落的残余胞质，并分泌雄激素结合蛋白、抑制素，参与构成血睾屏障。精原细胞为生精干细胞，精子细胞为单倍体生精细胞，管周肌样细胞参与排精，间质细胞分泌雄激素，均不承担吞噬残余胞质功能"},{"q":"在骨骼肌纤维收缩过程中","o":["肌膜的兴奋直接传向肌浆网","大量钙离子从肌浆转入肌浆网内","细肌丝向A带内滑入","A带变窄","粗肌丝变短"],"a":2,"e":"骨骼肌纤维收缩过程中，细肌丝向A带内滑入。收缩时细肌丝沿粗肌丝滑行，粗肌丝与细肌丝长度不变，A带宽度恒定，I带与H带缩短。肌膜兴奋经横小管传入而非直接到肌浆网；钙离子由肌浆网释放入肌浆而非转入网内；A带不窄、粗肌丝不短，这些均为对滑行学说的常见误解"},{"q":"食管黏膜上皮及食管腺源于","o":["外胚层","胚内中胚层","胚外中胚层","内胚层","间充质"],"a":3,"e":"食管黏膜上皮及食管腺源于内胚层。原始消化管的内胚层上皮分化形成消化管黏膜上皮及腺上皮，食管由前肠演变，其黏膜上皮与食管腺均来自内胚层。外胚层和神经外胚层主要形成表皮与神经组织，胚内、胚外中胚层及间充质形成结缔组织、肌组织和血管，不构成腺上皮"},{"q":"大脑皮质的主要神经元有","o":["锥体细胞和梨状细胞","锥体细胞和星形细胞","锥体细胞和篮状细胞","锥体细胞和颗粒细胞","颗粒细胞和水平细胞"],"a":3,"e":"大脑皮质的主要神经元有锥体细胞和颗粒细胞。锥体细胞为高尔基Ⅰ型投射神经元，颗粒细胞为高尔基Ⅱ型局部联络神经元，二者构成皮质主要神经元。梨状细胞为小脑浦肯野细胞的别称；星形细胞、水平细胞主要位于分子层，篮状细胞属中间神经元，均非皮质主要神经元类型"},{"q":"下列关于浅表肾单位的描述，下列哪项是正确的","o":["发生早，数量多，分布在皮质浅层和中层，肾小体小，肾单位髓袢较短","发生早，数量少，分布在皮质浅层和中层，肾小体小，肾单位髓袢较短","发生晚，数量少，分布在皮质浅层和中层，肾小体小，肾单位髓袢较长","发生晚，数量多，分布在皮质浅层和中层，肾小体小，肾单位髓袢较短","发生晚，数量多，分部在皮质浅层和中层，肾小体大，肾单位髓袢较短"],"a":3,"e":"浅表肾单位发生晚、数量多、位于皮质浅层和中层、肾小体小、髓袢较短。其肾小体占总数约85%，在尿液形成中起重要作用，髓袢短故而发生较晚。髓旁肾单位则发生早、数量少、位于皮质深部、肾小体大、髓袢长，与尿液浓缩有关；数量少、髓袢长、肾小体大的描述均与浅表肾单位不符"},{"q":"汗腺的肌上皮细胞分布于","o":["导管上皮细胞间","导管上皮细胞与基膜间","分泌部上皮细胞间","分泌部上皮细胞与基膜间","导管和分泌部上皮细胞与基膜间"],"a":3,"e":"汗腺的肌上皮细胞分布于分泌部上皮细胞与基膜间。肌上皮细胞位于腺细胞与基膜之间，胞质含肌动蛋白丝，收缩有助排出分泌物，汗腺中主要见于分泌部。导管上皮细胞间及导管上皮与基膜间并非其主要分布；将肌上皮细胞同时归入导管与分泌部两处，则超出了其在汗腺的实际分布范围"},{"q":"光镜下所见的纹状缘和刷状缘，电镜下观察是密集排列的","o":["微丝","微管","微绒毛","纤毛","张力丝"],"a":2,"e":"光镜下的纹状缘和刷状缘，电镜下是密集排列的微绒毛。小肠吸收细胞游离面的纹状缘、肾小管上皮的刷状缘均由大量微绒毛整齐排列而成，可显著扩大细胞表面积以利吸收。微丝、微管为细胞骨架成分，张力丝为中间丝；纤毛为可摆动的较长突起，均不构成纹状缘或刷状缘的光镜形态"},{"q":"软骨和骨中含有血管的结构是","o":["软骨陷窝","骨陷窝","中央管","骨小管","软骨囊"],"a":2,"e":"软骨和骨中含有血管的结构是中央管。骨单位的中央管及穿通管内含结缔组织、血管和神经，为骨组织提供营养。软骨陷窝、软骨囊位于无血管的软骨内；骨陷窝为骨细胞居所，骨小管为骨细胞突起通道，管内容纳突起而非血管，均不含血管"},{"q":"尿直肠隔起源于","o":["泄殖腔与尿囊之间的间充质","泄殖腔与尿生殖窦之间的间充质","后肠与尿囊起始部之间的间充质","直肠与尿囊之间的间充质","泄殖腔与直肠之间的间充质"],"a":2,"e":"尿直肠隔起源于后肠与尿囊起始部之间的间充质。第4至7周，尿囊与后肠之间的间充质增生向尾端生长，形成尿直肠隔并突入泄殖腔，将其分为尿生殖窦与直肠。泄殖腔与尿囊之间、泄殖腔与尿生殖窦之间、直肠与尿囊之间等表述均非尿直肠隔的确切来源，尿生殖窦是被分隔的产物而非起源处"},{"q":"关于巩膜的描述，哪项错误","o":["主要由致密结缔组织构成","呈乳白色，坚韧而不透明","维持眼球形状及保护眼内含物","无血管和神经","是纤维膜的大部分"],"a":3,"e":"关于巩膜，错误的是无血管和神经。巩膜为致密结缔组织，含少量血管和神经，并非完全无血管神经。其主要由粗大胶原纤维构成，呈乳白色坚韧不透明，构成纤维膜的大部分并维持眼球形状、保护眼内结构；无血管和神经实为晶状体的特征，靠房水供给营养，不可与巩膜混淆"},{"q":"下列哪种结构为完整的细胞","o":["胶原纤维","弹性纤维","肌纤维","神经纤维","网状纤维"],"a":2,"e":"完整的细胞是肌纤维。肌纤维即肌细胞，骨骼肌纤维为多核细胞，具完整细胞膜、胞质与细胞核，属完整细胞。胶原纤维、弹性纤维、网状纤维均为细胞外基质的纤维成分，无细胞结构；神经纤维由神经元轴突及包绕的神经胶质构成，只是细胞的一部分，均非完整细胞"},{"q":"关于胰岛的特征，哪项错误","o":["由内分泌细胞组成","HE切片中可分辨出A、B、D、PP四型细胞","细胞间有丰富的毛细血管","胰岛大小不等","成团位于腺泡之间"],"a":1,"e":"关于胰岛，错误的是HE切片中可分辨出A、B、D、PP四型细胞。四种胰岛细胞在HE染色切片中形态相似，无法区分，须用免疫组化或特殊染色才能鉴别。胰岛由内分泌细胞组成，大小不等，成团位于腺泡之间，细胞间有丰富的有孔毛细血管，这些均为胰岛的正确特征"},{"q":"能分泌抗中肾旁管激素的细胞是","o":["卵巢的卵原细胞","卵巢的卵泡细胞","睾丸的精原细胞","睾丸支持细胞","睾丸间质细胞"],"a":3,"e":"能分泌抗中肾旁管激素的细胞是睾丸支持细胞。睾丸支持细胞产生抗中肾旁管激素，使中肾旁管退化，故男性输卵管、子宫不发育。卵巢卵原细胞、卵泡细胞不分泌此激素；精原细胞为生精细胞；睾丸间质细胞分泌雄激素而非抗中肾旁管激素，二者功能常被混淆"},{"q":"肾上腺盐皮质激素作用于肾脏的","o":["近端小管曲部","远端小管曲部","细段","近端小管直部","远端小管直部"],"a":1,"e":"肾上腺盐皮质激素作用于肾脏的远端小管曲部。醛固酮等盐皮质激素促进远曲小管和集合管重吸收钠与水、排钾，远曲小管即远端小管曲部。近端小管曲部、近端小管直部主要重吸收原尿中大部分物质，细段管壁薄利于水离子通透，远端小管直部为髓袢升支的一部分，均非盐皮质激素的主要靶部位"},{"q":"胃溃疡时，胃黏膜黏液碳酸氢盐屏障受到破坏，胃酸和活化的胃蛋白酶损伤胃黏膜，其中参与分泌胃黏膜表面黏液的细胞是","o":["主细胞","壁细胞","颈黏液细胞","内分泌细胞","表面黏液细胞"],"a":4,"e":"参与分泌胃黏膜表面黏液的细胞是表面黏液细胞。表面黏液细胞覆盖胃黏膜表面，顶部胞质富含黏原颗粒，分泌含糖蛋白和碳酸氢根的黏液，形成黏液碳酸氢盐屏障。主细胞分泌胃蛋白酶原，壁细胞分泌盐酸和内因子，颈黏液细胞位于胃底腺颈部，内分泌细胞分泌胃肠激素，均非表面黏液屏障的构成者"},{"q":"构成气血屏障的结构应该除外","o":["Ⅰ型肺泡细胞","肺泡上皮的基膜","Ⅱ型肺泡细胞","毛细血管的内皮细胞","肺泡上皮和毛细血管内皮之间的结缔组织"],"a":2,"e":"构成气血屏障的结构应除外Ⅱ型肺泡细胞。气-血屏障由肺泡表面液体层、Ⅰ型肺泡细胞及其基膜、薄层结缔组织、毛细血管基膜与内皮构成，Ⅰ型肺泡细胞扁平菲薄覆盖大部分肺泡表面并参与气体交换。Ⅱ型肺泡细胞分泌表面活性物质、降低肺泡表面张力，不参与屏障构成，故应除外"},{"q":"白内障的主要原因是","o":["房水产生过多","房水流出受阻","角膜混浊","晶状体混浊","玻璃体混浊"],"a":3,"e":"白内障的主要原因是晶状体混浊。晶状体因老化、遗传、代谢异常等因素致蛋白质变性混浊，透明度下降即形成白内障，是主要致盲原因。房水产生过多或流出受阻影响眼压，导致青光眼；角膜混浊、玻璃体混浊虽也影响视力，但均非白内障的病变基础，病变部位在晶状体而非这些结构"},{"q":"细胞内含大量溶酶体的细胞是","o":["破骨细胞","成骨细胞","骨祖细胞","骨细胞","软骨细胞"],"a":0,"e":"细胞内含大量溶酶体的细胞是破骨细胞。破骨细胞在骨吸收时释放大量溶酶体水解酶和有机酸，溶解骨盐、分解有机成分，其皱褶缘深面胞质富含溶酶体及吞饮吞噬泡。成骨细胞合成胶原与基质，骨祖细胞为前体细胞，骨细胞维持骨组织，软骨细胞产生软骨基质，均不以大量溶酶体为特征"},{"q":"复层柱状上皮组织分布于","o":["气管","食管","肠管","眼睑结膜","女性尿道"],"a":3,"e":"复层柱状上皮分布于眼睑结膜。复层柱状上皮主要分布于睑结膜和男性尿道腔面，眼睑结膜即为其典型分布处。气管为假复层纤毛柱状上皮，食管为未角化复层扁平上皮，肠管为单层柱状上皮，女性尿道并非复层柱状上皮分布区，男性尿道才是，选项以女性尿道设错"},{"q":"生殖腺发生的描述中，下列哪一项是错误的","o":["精原细胞和卵原细胞均由原始生殖细胞分化而来","支持细胞和卵泡细胞均起源于初级性索","若胚胎细胞的性染色体为XY时，则分化为睾丸","早期生精小管只含支持细胞和精原细胞","卵原细胞在胎儿出生前已分化为初级卵母细胞"],"a":1,"e":"生殖腺发生描述中，错误的是支持细胞和卵泡细胞均起源于初级性索。支持细胞确由初级性索上皮演变而来，但卵巢形成时初级性索退化，卵泡细胞起源于表面上皮形成的皮质索，故均起源不成立。精原细胞与卵原细胞均由原始生殖细胞分化，XY分化为睾丸，早期生精小管含支持细胞和精原细胞，卵原细胞出生前已变为初级卵母细胞"},{"q":"关于泄殖腔的演变，哪项错误","o":["由尿生殖膈分割泄殖腔","腹侧份为尿生殖窦","背侧份为原始直肠","腹侧份分化为外生殖器","背侧份分化为直肠和肛管上段"],"a":3,"e":"关于泄殖腔演变，错误的是腹侧份分化为外生殖器。泄殖腔被尿直肠隔分为腹侧尿生殖窦和背侧原始直肠，尿生殖窦主要分化为膀胱、尿道等，外生殖器由泄殖腔褶、生殖结节等演变，并非尿生殖窦直接分化。腹侧份为尿生殖窦、背侧份为原始直肠并分化为直肠和肛管上段，均属正确描述"},{"q":"唾液腺中，浆液性腺泡的特点是","o":["腺细胞染色浅","细胞基部有较多分泌颗粒","细胞顶部有较多粗面内质网","细胞基部有大量滑面内质网","分泌物含较多唾液淀粉酶"],"a":4,"e":"唾液腺浆液性腺泡的特点是分泌物含较多唾液淀粉酶。浆液性腺泡由浆液细胞构成，其顶部胞质含酶原颗粒，分泌物富含唾液淀粉酶，腮腺为纯浆液腺即其代表。浆液细胞基底部粗面内质网丰富、染色深，故染色浅错误；分泌颗粒位于顶部而非基部；粗面内质网在基部而非顶部；滑面内质网并非其主要特征"},{"q":"脾滤血的主要部位是","o":["脾小体和脾血窦","脾索和边缘区","边缘区和动脉周围淋巴鞘","动脉周围淋巴鞘和脾小体","脾索和脾小体"],"a":1,"e":"脾滤血的主要部位是脾索和边缘区。脾索由富含血细胞的淋巴组织构成，血流缓慢，巨噬细胞可吞噬衰老红细胞与异物，是滤血的主要结构，边缘区亦参与血液过滤。脾小体与动脉周围淋巴鞘属白髓，分别为B细胞区和T细胞区，主司免疫应答而非滤血；脾血窦虽通血，选项组合中脾索与边缘区最符合滤血功能定位"},{"q":"有关心肌纤维横小管的结构，哪项是错误的","o":["由肌膜凹陷形成","与终池相贴近，组成二联体","同一水平的横小管吻合成网","位于A带和I带交界水平","可传导肌膜兴奋"],"a":3,"e":"有关心肌纤维横小管，错误的是位于A带和I带交界水平。心肌横小管较粗，位于Z线水平，与一侧终池紧贴形成二联体，而非位于明暗带交界处；A带与I带交界是骨骼肌横小管的位置。横小管由肌膜凹陷形成，同一水平吻合成网，可传导肌膜兴奋并与终池组成二联体，这些描述对心肌均正确"},{"q":"衬于心血管和淋巴管腔面的单层扁平上皮称为","o":["间皮","内皮","表皮","基膜","桥粒"],"a":1,"e":"衬于心血管和淋巴管腔面的单层扁平上皮称为内皮。内皮分布于心脏、血管和淋巴管腔面，表面光滑利于血液淋巴流动并便于物质交换。间皮分布于胸膜、腹膜和心包膜表面；表皮为皮肤表面的复层扁平上皮；基膜为上皮下方的薄膜结构；桥粒为细胞连接，均非衬贴管腔面的内皮"},{"q":"卵裂是指","o":["卵细胞的第一次成熟分裂","卵细胞的无丝分裂","卵细胞的第二次成熟分裂","卵细胞的分裂","受精卵的早期分裂"],"a":4,"e":"卵裂是指受精卵的早期分裂。受精卵边向子宫移行边进行特殊的有丝分裂，分裂间期无生长、细胞体积渐小，产生的子细胞称卵裂球。卵细胞的第一次、第二次成熟分裂属减数分裂，是受精前后卵子完成的分裂；卵细胞为单细胞配子，其无丝分裂或单纯分裂均不构成受精卵早期的卵裂过程"},{"q":"鼓膜来自于","o":["听泡","第Ⅰ咽囊","第Ⅰ鳃沟底","间充质","3个胚层"],"a":4,"e":"鼓膜来自于3个胚层。鼓膜由外胚层来源的第1鳃沟底、中胚层来源的间充质及内胚层来源的第1咽囊共同构成，故为三胚层来源。听泡形成内耳膜迷路，第Ⅰ咽囊主要形成中耳鼓室与咽鼓管上皮，第Ⅰ鳃沟底仅构成鼓膜外层，间充质仅为其中一层，单独任一项都不能概括鼓膜的全部来源"},{"q":"在体液免疫应答时，淋巴结内（ ）增多变大","o":["初级淋巴小结","次级淋巴小结","副皮质区","深层皮质","髓质"],"a":1,"e":"体液免疫应答时，淋巴结内次级淋巴小结增多变大。次级淋巴小结含生发中心，接触抗原后B细胞增殖分化使其增大增多，是体液免疫应答的重要标志。初级淋巴小结无生发中心、体积较小；副皮质区与深层皮质为T细胞区，主司细胞免疫；髓质含髓索髓窦，均非体液免疫时显著增大增多的结构"},{"q":"关于直精小管的描述，哪项是错误的","o":["位于近睾丸纵隔处","细而短","由生精小管移行而来","进入睾丸纵隔后互相吻合成睾丸网","管壁上皮为单层扁平上皮"],"a":4,"e":"关于直精小管，错误的是管壁上皮为单层扁平上皮。直精小管由生精小管近睾丸纵隔处移行而来，细而短，进入纵隔后互相吻合成睾丸网，其管壁为单层立方上皮而非单层扁平上皮。单层扁平上皮可见于肺泡、肾小囊壁层等处；直精小管位于近纵隔处、由生精小管移行、吻合形成睾丸网等描述均属实"},{"q":"胎儿出生后，脐静脉萎缩形成下列哪种结构","o":["肝圆韧带","动脉韧带","静脉韧带","脐正中韧带","脐外侧韧带"],"a":0,"e":"胎儿出生后，脐静脉萎缩形成肝圆韧带。出生后胎盘循环停止，脐静脉闭锁形成肝圆韧带，静脉导管闭锁形成静脉韧带，动脉导管闭锁形成动脉韧带。脐正中韧带为脐尿管闭锁的遗迹；脐外侧韧带由脐动脉闭锁形成。这些韧带来源各异，肝圆韧带与静脉韧带、动脉韧带最易被互换设错"},{"q":"扫描电镜术主要用于观察","o":["组织和细胞内部的微细结构","器官和细胞表面的立体微细结构","细胞断裂面的微细结构","各种细胞器的微细结构","细胞膜内蛋白质颗粒的分布"],"a":1,"e":"扫描电镜术主要用于观察器官和细胞表面的立体微细结构。扫描电镜以电子束扫描标本表面，收集二次电子成像，景深长、图像具立体感，适合观察较大组织与细胞表面的凹凸形态。组织和细胞内部、细胞断裂面及细胞器的微细结构主要用透射电镜观察；细胞膜内蛋白质颗粒分布需借助冷冻蚀刻等特殊技术，均非扫描电镜的主要用途"},{"q":"肛管的黏膜上皮来自","o":["外胚层","内胚层","中胚层","内胚层和外胚层","中胚层和外胚层"],"a":3,"e":"肛管的黏膜上皮来自内胚层和外胚层。肛管上段上皮来源于内胚层，下段来源于外胚层向内凹陷形成的肛凹，二者以齿状线为界。仅内胚层或仅外胚层都只能解释一段；中胚层主要形成结缔组织、肌组织和血管，不构成肛管上皮，故单一胚层或中胚层参与的说法均不成立"},{"q":"心室分隔后的室间隔包括","o":["心内膜垫和室间隔肌部","心内膜垫和室间隔膜部","室间隔肌部和室间隔膜部","室间隔肌部和心球嵴","室间隔膜部和心球嵴"],"a":2,"e":"心室分隔后的室间隔包括室间隔肌部和室间隔膜部。室间隔肌部由心室壁向腔内生长形成，其上方与心球嵴、心内膜垫融合形成室间隔膜部，二者共同封闭室间孔，完成心室分隔。心内膜垫与心球嵴是形成膜部的来源成分，并非室间隔的独立分部；单列肌部或膜部均不完整，唯有肌部加膜部才是室间隔的完整组成"},{"q":"结缔组织由大量细胞和细胞外基质构成。细胞数量少，种类多。多种细胞可分泌生物活性物质，参与多种生理功能。其中与过敏反应有关的两种细胞是","o":["成纤维细胞和巨噬细胞","巨噬细胞和浆细胞","肥大细胞和嗜碱性粒细胞","肥大细胞和单核细胞","单核细胞和成纤维细胞"],"a":2,"e":"与过敏反应有关的两种细胞是肥大细胞和嗜碱性粒细胞。肥大细胞与嗜碱性粒细胞均来源于骨髓造血祖细胞，胞质颗粒含组胺、白三烯等，脱颗粒引发过敏反应，二者作用基本相同。成纤维细胞、巨噬细胞主司基质合成与吞噬，浆细胞分泌抗体，单核细胞为巨噬细胞前体，均非直接启动过敏反应的细胞"},{"q":"对于规则致密结缔组织的描述，哪一项错误","o":["主要构成肌腱和腱膜，使骨骼肌附于骨上","大量胶原纤维顺应力学方向排列成束","腱细胞很多，位于纤维束之间","腱细胞是一种特殊的成纤维细胞","腱细胞胞体伸出多个薄翼状突起插入纤维束之问"],"a":2,"e":"对于规则致密结缔组织，错误的是腱细胞很多，位于纤维束之间。规则致密结缔组织主要构成肌腱和腱膜，大量胶原纤维顺应力学方向平行排列成束，细胞成分少，腱细胞数量并不多，仅位于纤维束之间。腱细胞是一种形态特殊的成纤维细胞，胞体伸出多个薄翼状突起插入纤维束之间，这些描述正确，而腱细胞很多与致密结缔组织细胞稀少的特点矛盾"},{"q":"关于骨组织的特点，哪项错误","o":["含有四种细胞类型","胶原纤维多且排列紧密","骨基质呈板层状","细胞外基质钙化","骨盐的主要成分为氯化钠"],"a":4,"e":"关于骨组织，错误的是骨盐的主要成分为氯化钠。骨盐占干骨重量约65%，以钙、磷离子为主，主要形式为羟基磷灰石结晶，并非氯化钠。骨组织含骨祖细胞、成骨细胞、骨细胞、破骨细胞四种细胞；胶原纤维多且排列紧密；骨基质呈板层状；细胞外基质钙化，这些均为骨组织的正确特点"},{"q":"关于胆囊的描述，正确的是","o":["胆囊壁由黏膜、黏膜下层和外膜组成","黏膜和黏膜下层凸起形成高而分支的皱襞","胆囊的功能为分泌并浓缩胆汁","上皮为单层柱状，凹陷形成黏膜窦","外膜大部分为纤维膜"],"a":3,"e":"关于胆囊，正确的是上皮为单层柱状，凹陷形成黏膜窦。胆囊黏膜上皮为单层柱状，上皮向固有层凹陷形成黏膜窦，是其结构特点。胆囊壁分黏膜、肌层和外膜三层，无黏膜下层；皱襞由黏膜和肌层凸起形成；胆囊功能为贮存和浓缩胆汁，胆汁由肝细胞分泌而非胆囊分泌；外膜大部分为浆膜而非纤维膜"},{"q":"血管升压素和缩宫素合成于","o":["垂体远侧部","垂体神经部","垂体中间部","正中隆起","下丘脑部分神经内分泌细胞"],"a":4,"e":"血管升压素和缩宫素合成于下丘脑部分神经内分泌细胞。下丘脑视上核、室旁核的神经内分泌细胞合成这两种激素，经轴突运输至垂体神经部贮存并释放入血。垂体神经部只贮存释放而不合成；远侧部、中间部属腺垂体，分泌其他激素；正中隆起为下丘脑与垂体的连接结构，均非合成部位"},{"q":"与花粉引起的过敏反应关系密切的两种细胞是","o":["成纤维细胞和巨噬细胞","巨噬细胞和浆细胞","肥大细胞和浆细胞","肥大细胞和单核细胞","单核细胞和成纤维细胞"],"a":2,"e":"与花粉引起的过敏反应关系密切的两种细胞是肥大细胞和浆细胞。花粉作为过敏原进入机体，刺激浆细胞产生IgE抗体，IgE结合于肥大细胞表面使其致敏，再次接触花粉时肥大细胞脱颗粒释放组胺等介质，引发过敏反应，故二者关系密切。成纤维细胞、脂肪细胞不参与免疫；巨噬细胞主司吞噬提呈；单核细胞为巨噬细胞前体，均非花粉过敏的关键效应细胞"},{"q":"肾小叶的组成是","o":["两条髓放线之间的皮质迷路","一条髓放线及其周围的皮质迷路","肾锥体及其相连的皮质部分","一条髓放线和相邻的肾柱","一个集合管及与其相通连的肾单位"],"a":1,"e":"肾小叶的组成是一条髓放线及其周围的皮质迷路。肾皮质中，从肾锥体底呈辐射状伸入皮质的条纹为髓放线，髓放线之间的皮质为皮质迷路，一条髓放线连同其周围的皮质迷路构成一个肾小叶。两条髓放线之间的皮质迷路范围不完整；一个肾锥体与相连皮质构成一个肾叶而非肾小叶；肾柱为锥体间皮质；一个集合管及其相通肾单位不构成肾小叶"},{"q":"脾内发生细胞免疫应答的主要变化是","o":["脾小体增多、增大","动脉周围淋巴鞘增厚","边缘区增大","脾血窦充血","脾索增大"],"a":1,"e":"脾内发生细胞免疫应答的主要变化是动脉周围淋巴鞘增厚。动脉周围淋巴鞘为脾内T细胞区，相当于淋巴结副皮质区，细胞免疫应答时其内T淋巴细胞分裂增殖使鞘增厚。脾小体为B细胞区，增大增多是体液免疫应答的标志；边缘区主要滤血；脾血窦充血、脾索增大均与细胞免疫应答的特征性变化无关"},{"q":"消化管各段之间结构差异最大、功能关系最密切和消化管中最常出现病变的部分是","o":["黏膜","黏膜肌层","黏膜下层","肌层","外膜"],"a":0,"e":"消化管各段间结构差异最大、功能关系最密切且最常出现病变的部分是黏膜。黏膜由上皮、固有层和黏膜肌层组成，各段上皮类型、腺体种类差异显著，承担消化吸收与保护功能，是病变的好发部位。黏膜肌层仅为一薄层平滑肌；黏膜下层为结缔组织，含血管神经；肌层与外膜各段相对恒定，结构差异远不如黏膜明显"},{"q":"有单层立方上皮的器官或结构是","o":["肾小管","男性尿道","胆囊","眼睑结膜","肺泡"],"a":0,"e":"有单层立方上皮的器官或结构是肾小管。单层立方上皮分布于肾小管、甲状腺滤泡等处，肾小管上皮细胞呈立方形，执行重吸收与分泌功能。男性尿道为复层柱状上皮；胆囊为单层柱状上皮；眼睑结膜为复层柱状上皮；肺泡为单层扁平上皮，这些器官的上皮类型均与肾小管不同"},{"q":"肾小管细段的显微结构是","o":["单层扁平上皮，核扁圆形凸向管腔","单层柱状上皮，无刷状缘","单层立方上皮，胞质着色浅","单层柱状上皮，胞质着色深","细胞呈锥体形，胞质着色浅"],"a":0,"e":"肾小管细段的显微结构是单层扁平上皮，核扁圆形凸向管腔。细段管径细，管壁为单层扁平上皮，细胞核椭圆形、含核部分突向管腔，胞质着色浅且无刷状缘，利于水和离子通透。单层柱状、单层立方上皮以及胞质深染、锥体形细胞等描述属于近端或远端小管的特点；有刷状缘是近曲小管的特征，均非细段结构"},{"q":"透明软骨的基质不包括","o":["胶原蛋白","毛细血管","硫酸软骨素","硫酸角质素","透明质酸"],"a":1,"e":"透明软骨的基质不包括毛细血管。透明软骨基质由无定形基质和纤维构成，含Ⅱ型胶原蛋白及硫酸软骨素、硫酸角质素、透明质酸等糖胺多糖，软骨组织内无血管。毛细血管属于循环系统结构，不存在于软骨基质中；胶原蛋白与硫酸软骨素、硫酸角质素、透明质酸均为软骨基质的正常成分"},{"q":"分泌物以唾液淀粉酶为主的是","o":["腮腺","汗腺","胰腺","下颌下腺","食管腺"],"a":0,"e":"分泌物以唾液淀粉酶为主的是腮腺。腮腺为纯浆液腺，全部腺泡为浆液性，分泌物含丰富唾液淀粉酶，可分解淀粉为麦芽糖。汗腺分泌汗液；胰腺分泌胰液含多种消化酶，非唾液淀粉酶为主；下颌下腺为混合腺，分泌物含唾液淀粉酶和黏液；食管腺分泌黏液，均不以唾液淀粉酶为主要分泌物"},{"q":"平滑肌纤维的肌丝单位的组成是","o":["细肌丝和粗肌丝","细肌丝和中间丝","粗肌丝和中间丝","粗肌丝，细肌丝和中间丝","只有中间丝"],"a":0,"e":"平滑肌纤维的肌丝单位由细肌丝和粗肌丝组成。若干条粗肌丝和细肌丝聚集形成肌丝单位，又称收缩单位，是平滑肌收缩的结构基础。中间丝连接于密斑、密体之间，构成梭形细胞骨架，并不属肌丝单位成分；故含中间丝的组合以及仅中间丝的说法均不准确，肌丝单位的核心是粗、细两种肌丝"},{"q":"关于胃底腺结构，哪项正确","o":["由壁细胞、主细胞、颈黏液细胞、干细胞和内分泌细胞组成","位于胃底和胃体黏膜下层内","为混合性腺","其壁细胞主要位于腺的体、底部","其主细胞主要位于腺的颈、体部"],"a":0,"e":"关于胃底腺，正确的是由壁细胞、主细胞、颈黏液细胞、干细胞和内分泌细胞组成。胃底腺为分支管状腺，位于固有层内，属单腺而非混合性腺。壁细胞主要位于腺的颈、体部，分泌盐酸和内因子；主细胞主要位于腺的体、底部，分泌胃蛋白酶原；故位于黏膜下层、混合性腺以及两种细胞定位颠倒的描述均有误"},{"q":"大脑皮质组织发生中最先出现的是","o":["旧皮质","新皮质","梨状皮质","海马和梨状皮质","古皮质"],"a":4,"e":"大脑皮质组织发生中最先出现的是古皮质。大脑皮质发生依次经历古皮质、旧皮质、新皮质三个阶段，海马和齿状回最早出现，相当于古皮质。梨状皮质于胚胎第7周出现，属旧皮质；新皮质出现最晚，出生时已具六层结构；古皮质和旧皮质分层不规则，均晚于或不同于古皮质的先后顺序"},{"q":"下列细胞具有形成胶原纤维的功能的是","o":["间充质细胞","成骨细胞","破骨细胞","骨原细胞","骨细胞"],"a":1,"e":"下列细胞中具有形成胶原纤维功能的是成骨细胞。成骨细胞合成并分泌胶原纤维与基质，参与骨组织形成，维生素C缺乏会影响此功能。间充质细胞为未分化前体，需分化为成骨细胞等才发挥作用；破骨细胞司骨吸收；骨原细胞为骨祖细胞，分化后才成骨；骨细胞由成骨细胞转变而来，主要维持骨组织，均非直接大量形成胶原纤维的主要细胞"},{"q":"神经元树突的特点是","o":["是胞体的延续，与胞体结构相似","细长均匀，分支较少","分支常呈直角发出","表面光滑无棘刺","无粗面内质网"],"a":0,"e":"神经元树突的特点是胞体的延续，与胞体结构相似。树突内胞质结构与胞体相似，含尼氏体和微管等，功能为接受刺激，树突及树突棘极大扩展了接受面积。树突短而多分支、常呈锐角发出，表面有大量树突棘，并含粗面内质网；细长均匀分支少、表面光滑无棘刺、无粗面内质网均为轴突的特点"},{"q":"使用普通光学显微镜观察HE染色切片时，低倍镜下结构清楚，但高倍镜下看不见或看不清楚，最可能的原因是","o":["虹彩未打开","对光不好","载玻片太厚","盖玻片太厚","盖玻片朝下"],"a":4,"e":"普通光镜观察HE切片，低倍清楚而高倍看不见，最可能是盖玻片朝下。盖玻片朝下时标本面远离物镜，高倍镜工作距离极短，无法聚焦成像，而低倍镜工作距离长仍可看清。虹彩未打开、对光不好会影响整个视野亮度，低倍同样受影响；载玻片或盖玻片过厚一般不影响低倍与高倍的这种差异，均非最可能原因"},{"q":"平滑肌组织可分布于","o":["心脏壁","眼周","食管壁上三分之一段","胃壁","肌腱"],"a":3,"e":"平滑肌组织可分布于胃壁。平滑肌广泛分布于消化管、呼吸道和血管等中空器官管壁，胃壁肌层即由平滑肌构成。心脏壁为心肌；眼周的眼外肌为骨骼肌；食管壁上三分之一段为骨骼肌，下三分之一为平滑肌，中段混合，笼统归为平滑肌不准确；肌腱为致密结缔组织，均非平滑肌分布处"},{"q":"中枢神经系统有髓神经纤维的髓鞘形成细胞是","o":["原浆性星形胶质细胞","少突胶质细胞","小胶质细胞","施万细胞","纤维性星形胶质细胞"],"a":1,"e":"中枢神经系统有髓神经纤维的髓鞘形成细胞是少突胶质细胞。少突胶质细胞突起末端扩展成扁平薄膜包卷轴突形成中枢髓鞘，是中枢神经系统的髓鞘形成细胞。施万细胞形成周围神经系统的髓鞘；原浆性与纤维性星形胶质细胞主司支持营养；小胶质细胞为中枢的巨噬细胞，均不形成中枢髓鞘"},{"q":"小脑皮质可分为三层，由外向内分别是","o":["分子层、锥体细胞层和颗粒层","分子层、颗粒层和浦肯野细胞层","分子层、浦肯野细胞层和节细胞层","分子层、浦肯野细胞层和颗粒层","颗粒层、分子层、浦肯野细胞层"],"a":3,"e":"小脑皮质三层由外向内依次为分子层、浦肯野细胞层和颗粒层。分子层最浅、含水平细胞等；浦肯野细胞层居中，由一排大型浦肯野细胞胞体构成；颗粒层最深、含大量颗粒细胞。大脑皮质为六层结构，含外颗粒层、内颗粒层、锥体细胞层等；节细胞层为视网膜结构，均非小脑皮质的分层"},{"q":"肠壁内神经丛的组成是","o":["交感神经元和无髓神经纤维","交感神经元和有髓神经纤维","副交感神经元和无髓神经纤维","副交感神经元和有髓神经纤维","感觉神经元和神经纤维"],"a":2,"e":"肠壁内神经丛的组成是副交感神经元和无髓神经纤维。肠壁的黏膜下神经丛与肌间神经丛属肠神经系统，为副交感性质，由副交感神经元胞体及其无髓神经纤维构成，调节胃肠运动与分泌。交感神经元、有髓神经纤维及感觉神经元均非肠壁内神经丛的主要成分；脊神经节内多见有髓神经纤维，与肠壁神经丛不同"},{"q":"神经元胞体是细胞的营养中心，这主要是胞体内富含","o":["线粒体","粗面内质网和游离核糖体","脂肪","高尔基复合体","滑面内质网"],"a":1,"e":"神经元胞体是营养中心，主要因胞体内富含粗面内质网和游离核糖体。二者构成尼氏体，是蛋白质合成的场所，可合成更新细胞器所需结构蛋白及神经递质相关酶类，体现胞体的代谢合成功能。线粒体供能但非营养中心主因；脂肪为储能物质；高尔基复合体加工包装；滑面内质网主司脂质合成与解毒，均非胞体作为营养中心的主要结构基础"},{"q":"关于球旁复合体的描述，下列哪项是正确的","o":["也称肾小球旁器，由球旁细胞、致密斑及球内系膜细胞组成","球旁细胞来自上皮细胞","球旁细胞分泌物肾素易通过血管基膜及内皮细胞释放入血","致密斑来自于远端小管靠近肾小体血管极侧的上皮细胞","致密斑可感受尿液中各种离子的浓度变化"],"a":3,"e":"关于球旁复合体，正确的是致密斑来自远端小管靠近肾小体血管极侧的上皮细胞。致密斑为远端小管近血管极一侧上皮细胞增高密集形成的椭圆形斑，感受滤液钠离子浓度变化。球旁复合体由球旁细胞、致密斑和球外系膜细胞组成，而非球内系膜细胞；球旁细胞由入球微动脉平滑肌细胞分化而来，非上皮细胞；肾素为大分子不易透过基膜内皮；致密斑仅感受钠离子而非各种离子"},{"q":"具有分泌黏液功能的细胞是","o":["柱状细胞","潘氏细胞","干细胞","杯状细胞","内皮细胞"],"a":3,"e":"具有分泌黏液功能的细胞是杯状细胞。杯状细胞散在于小肠、大肠及呼吸道上皮中，分泌黏液，具润滑和保护作用，从十二指肠至回肠末端逐渐增多。柱状细胞为吸收细胞，主司吸收；潘氏细胞分泌溶菌酶等防御物质；干细胞为增殖细胞；内皮细胞构成血管腔面，均不以分泌黏液为主要功能"},{"q":"视网膜中感受强光和色觉的细胞是","o":["视锥细胞","视杆细胞","色素细胞","双极细胞","水平细胞"],"a":0,"e":"视网膜中感受强光和色觉的细胞是视锥细胞。视锥细胞主要分布于视网膜中部，感受强光和颜色，中央凹处仅有视锥细胞，与双极细胞、节细胞形成一对一联系，视觉精确。视杆细胞主要分布于视网膜周围部，感受弱光且数量远多于视锥细胞；色素细胞吸收光线；双极细胞、水平细胞为联络神经元，均不直接感受强光与色觉"},{"q":"次级卵泡中的卵母细胞是","o":["卵原细胞","初级卵母细胞","次级卵母细胞","成熟卵细胞","卵泡细胞"],"a":1,"e":"次级卵泡中的卵母细胞是初级卵母细胞。初级卵母细胞自胚胎期形成后长期停滞于第一次减数分裂前期，在次级卵泡及成熟卵泡阶段仍为初级卵母细胞，直至排卵前36至48小时才完成第一次减数分裂。卵原细胞为胚胎早期的生殖细胞，出生前已分化为初级卵母细胞；次级卵母细胞、成熟卵细胞均在第一次减数分裂之后出现；卵泡细胞为体细胞"},{"q":"胎儿的右心房大部分来源于下列何种结构","o":["原始肺静脉","原始心房","右肺静脉","静脉窦右角","腔静脉"],"a":3,"e":"胎儿右心房大部分来源于静脉窦右角。静脉窦右角因接收较多回流血液而逐渐扩大，第7至8周被吸收并入右心房，形成永久性右心房的平滑部。原始心房形成右心房的粗糙部；原始肺静脉与右肺静脉参与左心房形成；腔静脉为回流血管，均非右心房大部分的来源，静脉窦左角则退化为冠状窦等"},{"q":"光镜下心肌纤维与骨骼肌纤维区别，哪项是错误的","o":["两种肌纤维的大小和粗细不同","骨骼肌纤维有横纹，心肌纤维没有横纹","骨骼肌纤维没有闰盘，心肌纤维有闰盘","骨骼肌纤维没有分支，心肌纤维有分支","骨骼肌纤维含有多个细胞核，位于周边，心肌纤维只有一两个细胞核，位于中央"],"a":1,"e":"光镜下心肌与骨骼肌区别，错误的是骨骼肌纤维有横纹，心肌纤维没有横纹。心肌纤维与骨骼肌纤维同属横纹肌，均有明暗相间的横纹，只是心肌横纹不如骨骼肌明显，该说法否认心肌横纹故错误。骨骼肌纤维粗大无分支、多核且核位于周边、无闰盘；心肌纤维短柱状有分支、核一至两个位于中央、有闰盘，这些区别均正确"},{"q":"不属于单核吞噬细胞系统的有","o":["尘细胞","库普弗细胞","小胶质细胞","破骨细胞","白细胞"],"a":4,"e":"不属于单核吞噬细胞系统的有白细胞。单核吞噬细胞系统由单核细胞及其进入组织后分化形成的巨噬细胞及其衍生细胞组成，尘细胞、库普弗细胞、小胶质细胞、破骨细胞均属此系统。白细胞是血液中各类白细胞的总称，含中性粒细胞、淋巴细胞等，并非单核吞噬细胞系统的特定成员，概念范围不同"},{"q":"毛细血管的构成是","o":["内膜、中膜和外膜和间皮","内皮、基膜和平滑肌","内皮和基膜","内皮、基膜和周细胞","内皮、基膜、周细胞和平滑肌"],"a":3,"e":"毛细血管的构成是内皮、基膜和周细胞。毛细血管壁由内皮细胞、其基膜和周细胞构成，管径6至8微米，仅容一个红细胞通过。内膜、中膜、外膜及间皮为较大血管或浆膜的结构；平滑肌见于微动脉等血管壁，毛细血管本身不含平滑肌；肠系膜铺片所见毛细血管网仅为整体形态，不改变其基本构成"},{"q":"原始心脏发生于","o":["脊索腹侧的中胚层","脊索头端的中胚层","口咽膜头端的中胚层","口咽膜尾端的中胚层","前肠背侧的中胚层"],"a":2,"e":"原始心脏发生于口咽膜头端的中胚层。三胚层胚盘形成时，部分中胚层细胞在胚盘前缘口咽膜头端汇聚形成生心区，人胚第18至19天生心区出现围心腔与心管，是心脏发生的原基。脊索腹侧、脊索头端中胚层并非生心区所在；口咽膜尾端中胚层位置不符；前肠背侧中胚层与心脏发生无关"},{"q":"对于胸腺依赖区的描述，哪一项错误","o":["由弥散淋巴组织构成","以T细胞为主","是细胞免疫应答的主要场所","是体液免疫应答的主要场所","常分布着毛细血管后微静脉"],"a":3,"e":"关于胸腺依赖区，错误的是其为体液免疫应答的主要场所。胸腺依赖区为淋巴结副皮质区及脾动脉周围淋巴鞘，富含T淋巴细胞，是细胞免疫应答的主要场所。该区由弥散淋巴组织构成、以T细胞为主、常含毛细血管后微静脉，均属正确；体液免疫应答主要发生于非胸腺依赖区的淋巴小结与髓索，故此项为错误描述"},{"q":"关于泌尿系统的畸形，下列哪一项是错误的","o":["多囊肾是因集合小管未与远端小管接通所致","马蹄肾是因两肾上端异常融合所致","双输尿管是因输尿管芽过早分支所致","脐尿瘘是因脐尿管未闭锁所致","异位肾是因肾在上升过程中受阻所致"],"a":1,"e":"关于泌尿系统畸形，错误的是马蹄肾是因两肾上端异常融合所致。马蹄肾是肾上升过程中受阻于肠系膜下动脉根部，两肾下端融合呈马蹄形，而非上端融合。多囊肾因集合小管未与远端小管接通；双输尿管因输尿管芽过早分支；脐尿瘘因脐尿管未闭锁；异位肾因肾上升受阻，这些病因描述均正确"},{"q":"关于远曲小管的特点描述，下列哪项正确","o":["胞质染色较深，嗜酸性","上皮细胞为立方形，染色浅","是糖皮质激素的靶细胞","有刷状缘","上皮细胞核位于基部"],"a":1,"e":"关于远曲小管，正确的是上皮细胞为立方形，染色浅。远曲小管管腔较大而规则，上皮细胞呈立方形，较近端小管细胞小，胞质染色较浅，核居中或近管腔，游离面无刷状缘。近曲小管胞质嗜酸性深染、有刷状缘、核近基底；远曲小管是盐皮质激素靶细胞而非糖皮质激素靶细胞，故其余各项均有误"},{"q":"初级卵母细胞完成第一次成熟分裂是在","o":["青春期前","次级卵泡时期","成熟卵泡形成时","排卵前36～48小时","受精时"],"a":3,"e":"初级卵母细胞完成第一次成熟分裂是在排卵前36至48小时。此时初级卵母细胞完成第一次减数分裂，形成次级卵母细胞和第一极体，次级卵母细胞随即进入第二次减数分裂并停滞于中期。青春期前、次级卵泡时期、成熟卵泡形成时初级卵母细胞均未完成第一次分裂；第二次减数分裂的完成则在受精时，均与第一次分裂的时点不同"},{"q":"肾上腺皮质细胞超微结构特点是富含","o":["粗面内质网和滑面内质网","粗面内质网和高尔基复合体","粗面内质网和溶酶体","高尔基复合体和线粒体","滑面内质网和线粒体"],"a":4,"e":"肾上腺皮质细胞超微结构特点是富含滑面内质网和线粒体。肾上腺皮质细胞分泌类固醇激素，属类固醇激素分泌细胞，胞质内含丰富的滑面内质网及管泡状嵴的线粒体，参与类固醇合成。粗面内质网、高尔基复合体与分泌颗粒为含氮激素分泌细胞的特征；以粗面内质网为主或富含溶酶体的组合均非类固醇分泌细胞的典型超微结构"},{"q":"角膜的营养来自","o":["角膜内血管和房水","角膜缘血管和房水","虹膜血管","睫状体血管层","脉络膜血管"],"a":1,"e":"角膜的营养来自角膜缘血管和房水。角膜内不含血管和淋巴管，其营养由房水和角膜缘的血管以渗透方式供应。角膜内血管并不存在；虹膜血管、睫状体血管层、脉络膜血管虽为眼内血管，但均不直接供应角膜；角膜透明依赖无血管及纤维规则排列，故含角膜内血管或远端血管的选项均不成立"},{"q":"滤泡旁细胞的特征中，哪项是错误的","o":["位于滤泡之间或滤泡上皮细胞之间","胞质中有较丰富的粗面内质网和高尔基复合体","胞质中有嗜银颗粒","HE染色胞质呈强嗜伊红性","分泌降钙素"],"a":3,"e":"滤泡旁细胞的特征中，错误的是HE染色胞质呈强嗜伊红性。滤泡旁细胞在HE染色切片中胞质着色较淡，镀银染色可见嗜银颗粒，并非强嗜伊红。其位于滤泡之间或滤泡上皮细胞之间，胞质含较丰富的粗面内质网和高尔基复合体，分泌降钙素，这些描述均属实；强嗜伊红性实为嗜酸性细胞的特点"},{"q":"食管是食物进入胃的通道，容易受到摩擦，胃酸反流也容易引起黏膜损伤。食管黏膜上皮是","o":["单层扁平上皮","单层柱状上皮","变移上皮","未角化的复层扁平上皮","角化的复层扁平上皮"],"a":3,"e":"食管黏膜上皮是未角化的复层扁平上皮。食管黏膜上皮为未角化复层扁平上皮，在食物通过时起机械性保护作用，下端与胃贲门单层柱状上皮骤然相接，为食管癌好发处。单层扁平上皮见于血管腔面；单层柱状上皮见于胃、肠；变移上皮见于膀胱；角化复层扁平上皮见于皮肤表皮，均非食管上皮类型"},{"q":"肢端肥大症是由垂体哪种细胞分泌过盛引起的","o":["垂体细胞","嗜碱性细胞","嫌色细胞","嗜酸性细胞","弓状核神经内分泌细胞"],"a":3,"e":"肢端肥大症由垂体嗜酸性细胞分泌过盛引起。腺垂体远侧部嗜酸性细胞分生长激素细胞和催乳激素细胞，成人期生长激素分泌过盛，骨骼末端增生肥大即致肢端肥大症。嗜碱性细胞分泌促甲状腺激素等；嫌色细胞无分泌功能；垂体细胞为神经垂体胶质细胞；弓状核神经内分泌细胞分泌促性腺激素释放激素，均非生长激素来源"},{"q":"关于皮下组织的描述，下列哪项是正确的","o":["为位于皮肤下方的结缔组织","为位于表皮下方的结缔组织","与皮肤有明显的分界线","是皮肤的一个组成部分","可见丰富的触觉小体"],"a":0,"e":"关于皮下组织，正确的是其为位于皮肤下方的结缔组织。皮下组织位于真皮下方，由疏松结缔组织和脂肪组织构成，又称浅筋膜，将皮肤与深部组织相连并赋予皮肤活动性。表皮下方的结缔组织是真皮而非皮下组织；皮下组织与皮肤无明显分界且不属于皮肤本身；触觉小体位于真皮乳头层，均非皮下组织的正确描述"},{"q":"光镜下，相邻肺泡开口处有结节状膨大的结构是","o":["终末细支气管","呼吸性细支气管","肺泡管","肺泡囊","细支气管"],"a":2,"e":"光镜下相邻肺泡开口处有结节状膨大的结构是肺泡管。肺泡管管壁上有大量肺泡开口，相邻肺泡开口之间残留的管壁形成结节状膨大，表面覆单层立方或扁平上皮，深部含弹性纤维和环行平滑肌。终末细支气管、呼吸性细支气管无此典型膨大；肺泡囊为若干肺泡的共同开口处，相邻开口间无平滑肌，故无结节状膨大"},{"q":"骨骼肌纤维三联体的结构","o":["由一条横小管和两侧的终池形成","由两条横小管和中间的终池形成","由两条纵小管和中间的终池形成","由一条横小管和一个终池形成","由一条纵小管和一个终池形成"],"a":0,"e":"骨骼肌纤维三联体由一条横小管和两侧的终池形成。横小管为肌膜向肌质内凹陷的管道，其两侧各紧贴一个终池，共同构成三联体，在此将肌膜兴奋传至肌质网膜。两条横小管加中间终池、两条纵小管加终池、一条横小管仅配一个终池或纵小管配终池等组合均不符合三联体的定义；心肌则为横小管配一侧终池的二联体"},{"q":"骨骼肌纤维的肌节是由","o":["1/2明带＋1/2暗带组成","1/2明带＋暗带＋1/2明带组成","明带＋暗带组成","1/2暗带＋明带＋1/2暗带组成","1/2明带＋1/2暗带＋1/2明带组成"],"a":1,"e":"骨骼肌纤维的肌节由1/2明带＋暗带＋1/2明带组成。相邻两条Z线之间的一段肌原纤维为肌节，由1/2I带（明带）＋A带（暗带）＋1/2I带构成，是骨骼肌结构和功能的基本单位。仅1/2明带加1/2暗带、明带加暗带、1/2暗带加明带加1/2暗带等组合均未按Z线界限划分，不符合肌节的实际构成"},{"q":"由中肠演化形成的器官是","o":["肝","空肠","胃","胆总管","胰"],"a":1,"e":"由中肠演化形成的器官是空肠。中肠袢头支演化为空肠和回肠的大部分，尾支形成回肠尾段及结肠右三分之二。肝、胆总管、胰由前肠末端腹侧壁的肝憩室及胰原基演化而来；胃由前肠尾段膨大形成，均属前肠衍生物，而非中肠来源"},{"q":"脊髓内分化为中间神经元的成神经细胞位于","o":["基板","翼板","顶板","底板","翼板和基板之间"],"a":1,"e":"脊髓内分化为中间神经元的成神经细胞位于翼板。神经管尾段分化为脊髓，翼板形成灰质后角，其中成神经细胞分化为中间神经元。基板形成前角，其成神经细胞分化为躯体运动神经元；顶板、底板为连接板；基板与翼板之间的侧角内成神经细胞分化为内脏传出神经元，均非中间神经元的来源部位"},{"q":"生肾索发生于","o":["尿生殖嵴","中肾嵴","生殖腺嵴","间介中胚层","侧中胚层"],"a":3,"e":"生肾索发生于间介中胚层。胚胎第4周，胚内中胚层由脊索向外分为轴旁中胚层、间介中胚层和侧中胚层，间介中胚层尾段增生形成纵行的生肾索，继而凸向体腔形成尿生殖嵴。尿生殖嵴、中肾嵴、生殖腺嵴均为生肾索增生或分化后的结构而非其来源；侧中胚层主要形成体壁和脏壁，均非生肾索发生处"},{"q":"运动终板突触小泡内含有的主要神经递质是","o":["脑啡肽","乙酰胆碱","去甲肾上腺素","5-羟色胺","多巴胺"],"a":1,"e":"运动终板突触小泡内含有的主要神经递质是乙酰胆碱。运动终板为运动神经元轴突终末与骨骼肌纤维形成的神经肌接头，突触小泡内含乙酰胆碱，释放后与突触后膜受体结合，引发肌纤维兴奋收缩。脑啡肽为神经肽；去甲肾上腺素、多巴胺、5-羟色胺属单胺类递质，多见于其他突触，均非运动终板的主要递质"},{"q":"神经元细胞核的特点是","o":["球形，较大，着色较淡，核仁明显","分叶状，较大，着色较深，核仁不明显","球形，较小，着色较淡，核仁明显","球形，较大，着色较深，核仁不明显","梭形，较小，着色淡，核仁明显"],"a":0,"e":"神经元细胞核的特点是球形、较大、着色较淡、核仁明显。神经元胞体大，核圆位于中央，异染色质少故着色淡，核仁大而明显，反映其蛋白质合成活跃。分叶状、较小、着色深、核仁不明显为白细胞或小型细胞的特点；梭形核见于平滑肌等，均与神经元核大而圆、染色浅、核仁显著的典型形态不符"},{"q":"巩膜的主要成分是","o":["网状纤维","粗大的胶原纤维","弹性纤维","胶原原纤维","平滑肌"],"a":1,"e":"巩膜的主要成分是粗大的胶原纤维。巩膜呈瓷白色，主要由大量粗大的胶原纤维交织而成，质地坚韧，构成眼球纤维膜的大部分并起保护作用。网状纤维主要存在于网状组织；弹性纤维为弹性组织主要成分；胶原原纤维为胶原纤维的亚单位；平滑肌纤维不构成巩膜，这些均非巩膜的主要成分"},{"q":"电镜下微绒毛与纤毛不同点是","o":["前者细长，后者粗短","前者能摆动，后者不可摆动","前者光镜下可见，后者不可见","前者内含微丝，后者内含微管","前者内含线粒体，而后者则无"],"a":3,"e":"电镜下微绒毛与纤毛的不同点是前者内含微丝，后者内含微管。微绒毛核心由肌动蛋白微丝构成，终末网中肌球蛋白收缩可使微绒毛伸缩；纤毛轴心含微管，具九对周边双联微管加中央两根微管的结构。微绒毛较短不能摆动，纤毛可摆动，说前者能摆动后者不能正好相反；光镜下纹状缘由微绒毛构成、纤毛亦可见；线粒体均非两者轴心的特征性成分"},{"q":"以下哪两种细胞均不参与机体免疫反应","o":["成纤维细胞和脂肪细胞","脂肪细胞和浆细胞","浆细胞和肥大细胞","肥大细胞和巨噬细胞","巨噬细胞和成纤维细胞"],"a":0,"e":"两种细胞均不参与机体免疫反应的是成纤维细胞和脂肪细胞。结缔组织固有细胞包括未分化间充质细胞、成纤维细胞和脂肪细胞，主司基质纤维合成与储能，不参与免疫。巨噬细胞吞噬提呈抗原，浆细胞分泌抗体，肥大细胞释放过敏介质，均属游走细胞并参与免疫应答；含这些细胞的组合均不满足均不参与的条件"},{"q":"和肝纤维化肝硬化有关的是","o":["贮脂细胞形成脂滴的能力增强","贮脂细胞形成脂滴的能力减弱","贮脂细胞合成胶原的功能增强","贮脂细胞合成胶原的功能抑制","贮脂细胞摄取和贮存维生素A的功能减弱"],"a":2,"e":"与肝纤维化肝硬化有关的是贮脂细胞合成胶原的功能增强。贮脂细胞位于窦周隙，正常参与维生素A代谢贮存；病理状态下增多并转化为成纤维细胞，合成胶原功能增强，导致肝纤维化。形成脂滴能力增强或减弱、摄取贮存维生素A功能减弱均非纤维化的直接机制；合成胶原受抑制则与纤维化相反，均不成立"},{"q":"以下对神经元突起的描述，哪项错误","o":["分为轴突和树突","轴突细而长，每一个神经细胞只有一个轴突，中途很少分支，末端可有大量分支","树突较短多分支，尼氏体可伸入其内","由细胞体发出轴突处称轴丘，内含尼氏体","神经原纤维沿轴突长轴平行排列"],"a":3,"e":"对神经元突起的描述，错误的是由细胞体发出轴突处称轴丘，内含尼氏体。轴丘为胞体发出轴突的圆锥形区域，此区无尼氏体故染色淡，说其内含尼氏体错误。每个神经元仅一个轴突，细长且中途少分支、末端分支多；树突较短多分支，尼氏体可伸入；神经原纤维沿轴突长轴平行排列，这些描述均正确"},{"q":"最常见的突触方式是","o":["轴-树突触","轴-体突触","轴-轴突触","树-树突触","树-棘突触"],"a":0,"e":"最常见的突触方式是轴-树突触。突触常见形式为一个神经元的轴突终末与另一神经元的胞体、树突或树突棘相接，分别形成轴-体、轴-树或轴-棘突触，其中以轴-树突触最为多见。轴-轴突触、树-树突触相对少见；突触小泡含圆形清亮小泡、颗粒型小泡等，分别对应不同递质，与突触方式分类无关"},{"q":"腺上皮的是指","o":["含有腺细胞的上皮","具有分泌功能的上皮","具有吸收功能的上皮","以分泌功能为主的上皮","以吸收功能为主的上皮"],"a":3,"e":"腺上皮是指以分泌功能为主的上皮。腺上皮由腺细胞组成，以分泌功能为主，分泌物含酶类、黏液和激素等，由腺细胞构成的器官或结构称腺。仅具有分泌功能未突出为主的特点，不够准确；吸收功能为主的上皮为被覆上皮如小肠吸收细胞，故以吸收功能为主的两项均与腺上皮的定义相悖"},{"q":"分泌房水的是","o":["角膜上皮","角膜内皮","晶状体上皮","虹膜色素上皮","睫状体非色素上皮"],"a":4,"e":"分泌房水的是睫状体非色素上皮。睫状体上皮由外层色素上皮和内层非色素上皮组成，内层矮柱状非色素上皮细胞分泌房水，并产生睫状小带和玻璃体的生化成分。角膜内皮、晶状体上皮不分泌房水；虹膜色素上皮也不承担分泌房水功能；房水由后房经瞳孔入前房，回流受阻可致眼压升高即青光眼"},{"q":"关于致密斑的描述，哪项正确","o":["由近曲小管上皮细胞紧密排列形成","靠近肾小体血管极的远端小管上皮细胞增高密集排列呈斑状结构","能感受滤液中Na＋的变化，分泌肾素","致密斑的细胞与球旁细胞关系密切，二者之间有基膜","细胞排列紧密，呈斑状，细胞为立方形"],"a":1,"e":"关于致密斑，正确的是靠近肾小体血管极的远端小管上皮细胞增高密集排列呈斑状结构。致密斑由远端小管近血管极侧上皮细胞变高、密集排列形成，感受滤液中钠离子浓度变化。它不是由近曲小管上皮形成；分泌肾素的是球旁细胞而非致密斑；致密斑与球旁细胞间无基膜分隔以利信息传递；其细胞呈高柱状而非立方形"},{"q":"骨骼肌纤维的肌膜向内凹陷形成","o":["小凹","肌浆网","横小管","闰盘","终池"],"a":2,"e":"骨骼肌纤维的肌膜向内凹陷形成横小管。横小管是肌膜向肌质内凹陷形成的管状结构，走向与肌纤维长轴垂直，位于明暗带交界处，可将肌膜兴奋迅速传入肌纤维深部。小凹为平滑肌肌膜凹陷的类似结构；肌浆网为滑面内质网，非肌膜凹陷；闰盘为心肌细胞连接；终池为肌浆网末端膨大，均非肌膜内陷所成"},{"q":"关于后肾发生部位，下列哪项是正确的","o":["前肾管末端的输尿管芽和中肾嵴末端的生后肾原基","中肾管末端的输尿管芽和生殖腺嵴末端的生后肾原基","中肾管末端的输尿管芽和中肾嵴末端的生后肾原基","中肾管末端的生后肾原基和中肾嵴末端的输尿管芽","中肾旁管末端的输尿管芽和中肾嵴末端的生后肾原基"],"a":2,"e":"后肾发生的部位是中肾管末端的输尿管芽和中肾嵴末端的生后肾原基。第5周中肾管近泄殖腔处发出输尿管芽，长入中肾嵴尾端，诱导周围中胚层形成生后肾组织，二者互相诱导分化成永久肾。前肾管末端、生殖腺嵴末端、中肾旁管末端均非输尿管芽发出处；把生后肾原基与输尿管芽的来源对调亦错误"},{"q":"软骨膜的纤维主要是","o":["网状纤维","胶原纤维","胶原原纤维","微原纤维","弹性纤维"],"a":1,"e":"软骨膜的纤维主要是胶原纤维。软骨膜为包绕软骨的致密结缔组织，含较多胶原纤维，对软骨起营养与保护作用。网状纤维主要构成网状组织支架；胶原原纤维为胶原纤维的亚单位，需黏合质黏结后才成胶原纤维；微原纤维为弹性纤维的组成成分；弹性纤维主要见于弹性软骨基质而非软骨膜的主要纤维"},{"q":"幼稚红细胞合成血红蛋白的结构是","o":["游离核糖体","粗面内质网","高尔基复合体","线粒体","滑面内质网"],"a":0,"e":"幼稚红细胞合成血红蛋白的结构是游离核糖体。血红蛋白为胞质内的蛋白质，由游离核糖体合成，幼稚红细胞胞质中游离核糖体丰富，随血红蛋白增多核糖体逐渐减少。粗面内质网合成蛋白并进入膜系统或分泌，主要用于膜蛋白与分泌蛋白；高尔基复合体加工包装；线粒体供能并参与血红素合成但不合成珠蛋白；滑面内质网主司脂质合成，均非合成血红蛋白的场所"},{"q":"黏液性腺细胞分泌的黏液是","o":["糖蛋白","蛋白多糖","脂蛋白","糖脂","蛋白质"],"a":0,"e":"黏液性腺细胞分泌的黏液是糖蛋白。黏液性腺细胞顶部胞质含黏原颗粒，分泌的黏液主要成分为糖蛋白，具润滑保护作用，胃表面黏液细胞分泌物也富含糖蛋白和碳酸氢根。蛋白多糖为基质成分；脂蛋白、糖脂为膜脂或转运形式；单纯蛋白质未体现黏液富含糖链的特点，均非黏液的主要成分"},{"q":"关于生后肾组织的描述，错误的是","o":["来源于生肾索的尾端部分","在输尿管芽的诱导下分化","分化为肾单位","形成肾小管和集合小管","外周部分形成肾被膜"],"a":3,"e":"关于生后肾组织，错误的是形成肾小管和集合小管。生后肾组织在输尿管芽诱导下分化形成肾单位，包括肾小体与肾小管，其外周部分形成肾被膜；而集合管由输尿管芽末端反复分支形成，并非生后肾组织的产物。生后肾组织来源于生肾索尾端、在输尿管芽诱导下分化、分化为肾单位等描述均属实，唯集合小管的归属错误"},{"q":"髓袢的组成部分是","o":["近直小管和细段","近直小管、细段和远直小管","细段和远直小管","远直小管和集合管","近直小管和远直小管"],"a":1,"e":"髓袢的组成部分是近直小管、细段和远直小管。近端小管直部、细段与远端小管直部三者构成U形髓袢，深入髓质后折返，与尿液浓缩密切相关。近直小管与细段的组合缺少远直小管；细段与远直小管缺少近直小管；远直小管与集合管无关，集合管不属于髓袢；仅近直小管与远直小管缺少中间的细段，均不完整"},{"q":"初级卵母细胞的第一次减数分裂完成于","o":["原始卵泡阶段","初级卵泡阶段","排卵前36～48小时","排卵时","排卵后"],"a":2,"e":"初级卵母细胞的第一次减数分裂完成于排卵前36至48小时。此时初级卵母细胞完成第一次减数分裂，产生一个次级卵母细胞和一个第一极体，次级卵母细胞迅速进入第二次减数分裂并停滞于中期。原始卵泡、初级卵泡阶段初级卵母细胞长期停滞于分裂前期；排卵时已完成第一次分裂；排卵后才可能完成第二次分裂，均非第一次分裂的时点"},{"q":"分泌类固醇激素的器官/部位是","o":["甲状腺","肾上腺皮质","肾上腺髓质","腺垂体远侧部","下丘脑视上核"],"a":1,"e":"分泌类固醇激素的器官或部位是肾上腺皮质。类固醇激素分泌细胞仅包括肾上腺皮质和性腺的内分泌细胞，肾上腺皮质球状带、束状带、网状带分别分泌盐皮质激素、糖皮质激素和雄激素。甲状腺分泌含氮激素；肾上腺髓质分泌肾上腺素等胺类激素；腺垂体远侧部与下丘脑视上核分泌肽类或胺类激素，均非类固醇激素分泌部位"},{"q":"下列关于透明带的描述中，哪项是错误的","o":["由三种糖蛋白分子ZP1、ZP2、ZP3构成，其中ZP3为精子受体","为一层均质状、折光性强的嗜酸性膜","位于膜细胞与卵泡细胞之间","卵母细胞表面突起与卵泡细胞的微绒毛在透明带内形成缝隙连接","从初级卵泡开始出现"],"a":2,"e":"关于透明带，错误的是位于膜细胞与卵泡细胞之间。透明带由初级卵母细胞与卵泡细胞共同分泌形成，位于卵母细胞与卵泡细胞之间，而非膜细胞与卵泡细胞之间。透明带由ZP1、ZP2、ZP3三种糖蛋白构成，ZP3为精子受体；为均质状折光性强的嗜酸性膜；卵母细胞微绒毛与卵泡细胞突起在其内形成缝隙连接；自初级卵泡开始出现，这些均属实"},{"q":"骨骼肌纤维收缩时，长度不变的是","o":["I带","A带","H带","肌节","肌原纤维"],"a":1,"e":"骨骼肌纤维收缩时，长度不变的是A带。收缩时细肌丝向A带内滑行，粗肌丝与细肌丝本身长度不变，故暗带宽度恒定，而明带和H带缩短、肌节缩短。明带、H带在收缩时明显变窄；肌节为相邻Z线间结构，随收缩而缩短；肌原纤维由肌节串联而成，整体亦缩短，均非长度不变者"},{"q":"长期炎症等刺激下，胃黏膜可能出现化生现象，但正常胃黏膜的结构和功能特点不包括","o":["黏膜上皮为夹有杯状细胞的单层柱状上皮","上皮中尚有少量内分泌细胞","胃小凹的上皮与表面上皮一样，可分泌黏液","胃小凹的底与胃腺相通","胃体部的胃腺可分泌黏液、盐酸、酶原和激素"],"a":0,"e":"正常胃黏膜结构和功能特点不包括黏膜上皮为夹有杯状细胞的单层柱状上皮。正常胃黏膜上皮由表面黏液细胞构成，不含杯状细胞；杯状细胞出现在胃黏膜肠上皮化生时，属病理改变。胃上皮含少量内分泌细胞；胃小凹上皮与表面上皮相续并分泌黏液，底部与胃腺相通；胃体部胃腺分泌黏液、盐酸、酶原和激素，这些均为正常胃黏膜的特点"},{"q":"性未分化期，胚胎有两套生殖管道，分别是","o":["中肾小管和中肾管","中肾管和中肾旁管","中肾小管和中肾旁管","中肾管和前肾小管","前肾小管和中肾旁管"],"a":1,"e":"性未分化期，胚胎的两套生殖管道是中肾管和中肾旁管。第6周时胚体内同时存在一对中肾管和一对中肾旁管。中肾小管为中肾的组成成分，非独立生殖管道；前肾小管属前肾，趋于退化；中肾小管与前肾小管的组合均不符合未分化期两套生殖管道的定义，唯中肾管与中肾旁管正确"},{"q":"泪腺来源于","o":["中胚层","表面外胚层","神经外胚层","内胚层","神经外胚层和中胚层"],"a":1,"e":"泪腺来源于表面外胚层。泪腺由眼睑内表面的表面外胚层发生，属表面外胚层来源。中胚层形成结缔组织等；神经外胚层形成神经管和神经嵴衍生结构；内胚层形成消化呼吸管上皮；神经外胚层和中胚层的组合适用于垂体等，均非泪腺的上皮来源，故泪腺表面外胚层的归属明确"},{"q":"腺垂体嗜酸性细胞可合成和分泌","o":["生长激素和促甲状腺激素","促甲状腺激素、促肾上腺皮质激素和促性腺激素","催乳激素和生长激素","催产素和生长激素","催乳激素和催产素"],"a":2,"e":"腺垂体嗜酸性细胞可合成和分泌催乳激素和生长激素。远侧部嗜酸性细胞分生长激素细胞和催乳激素细胞，分别分泌生长激素和催乳素。促甲状腺激素、促肾上腺皮质激素、促性腺激素由嗜碱性细胞分泌；催产素由下丘脑视上核、室旁核合成，经神经垂体释放，均非嗜酸性细胞的产物"},{"q":"人胚发育3个月后，胎儿的尿液通过尿道外口排入","o":["胚内体腔","卵黄囊","羊膜腔","泄殖腔","胚外体腔"],"a":2,"e":"人胚发育3个月后，胎儿尿液通过尿道外口排入羊膜腔。妊娠中期以后胎儿吞咽羊水，其泌尿系统等排泄物及脱落上皮进入羊水，尿液经尿道外口排入羊膜腔，成为羊水来源之一。胚内体腔、胚外体腔为胚胎早期腔隙；卵黄囊与卵黄管相关；泄殖腔为胚胎早期直肠与泌尿生殖窦的共同腔，出生前已分隔，均非胎儿尿液排出处"},{"q":"以下哪一种细胞产生纤维和基质","o":["巨噬细胞","肥大细胞","浆细胞","成纤维细胞","脂肪细胞"],"a":3,"e":"产生纤维和基质的细胞是成纤维细胞。成纤维细胞分泌胶原纤维、网状纤维、弹性纤维和无定形基质，是结缔组织纤维与基质的主要来源，创伤修复时亦由其产生纤维基质充填缺损。巨噬细胞司吞噬；肥大细胞释放过敏介质；浆细胞分泌抗体；脂肪细胞储存脂肪，均不承担产生纤维和基质的功能"},{"q":"关于气管与支气管的细胞，下列错误的是","o":["刷细胞表面的纤毛较短","杯状细胞数量较多，分泌黏蛋白","基细胞可分化为纤毛细胞及杯状细胞","纤毛细胞的纤毛向咽部快速摆动","管壁内的神经内分泌细胞又称小颗粒细胞"],"a":0,"e":"关于气管与支气管的细胞，错误的是刷细胞表面的纤毛较短。刷细胞表面为密集的微绒毛呈刷状，并非短纤毛，纤毛细胞才具有向咽部快速摆动的纤毛。杯状细胞数量较多、分泌黏蛋白；基细胞可分化为纤毛细胞和杯状细胞；管壁神经内分泌细胞又称小颗粒细胞，这些描述均属实，唯刷细胞纤毛的说法错误"},{"q":"法洛四联症的最主要原因是","o":["右心室肥大","室间隔膜部缺损","主动脉骑跨","肺动脉狭窄","主动脉肺动脉隔偏位"],"a":4,"e":"法洛四联症最主要原因是主动脉肺动脉隔偏位。主动脉肺动脉隔偏于肺动脉一侧，导致肺动脉狭窄、主动脉骑跨、室间隔膜部缺损和右心室肥大四畸形并存，故隔偏位为根本原因。右心室肥大、室间隔膜部缺损、主动脉骑跨、肺动脉狭窄均为四联症的表现之一，而非最初的主要成因，单列任一项均不全面"},{"q":"胚泡植入后的子宫内膜称为","o":["胎膜","蜕膜","绒毛膜","羊膜","基膜"],"a":1,"e":"胚泡植入后的子宫内膜称为蜕膜。植入时子宫内膜处于分泌期，植入后内膜进一步增厚，基质细胞肥大富含糖原脂滴，称蜕膜反应，此时内膜改称蜕膜，并按与胚的位置关系分为基蜕膜、包蜕膜和壁蜕膜。胎膜、绒毛膜、羊膜为胚体来源的结构；基膜为上皮下方薄膜，均非植入后内膜的称谓"},{"q":"关于次级精母细胞的描述，错误的是","o":["位置靠近管腔","较初级精母细胞小，核圆，染色较深","染色体核型为23，X或23，Y","经DNA复制和第2次成熟分裂后形成精子细胞","存在时间短，故生精小管切面上不易见到"],"a":3,"e":"关于次级精母细胞，错误的是经DNA复制和第2次成熟分裂后形成精子细胞。次级精母细胞由初级精母细胞经第一次减数分裂形成，核型为23，X或23，Y，不再进行DNA复制，迅速进入第二次减数分裂形成精子细胞。其靠近管腔、较初级精母细胞小而核圆染色深、存在时间短故切面不易见到，这些描述均正确，错误在于DNA复制"},{"q":"精子的顶体是特殊的","o":["线粒体","滑面内质网","溶酶体","中心粒","粗面内质网"],"a":2,"e":"精子的顶体是特殊的溶酶体。顶体覆盖于精子头部核的前三分之二，由高尔基复合体演变而成，内含顶体素、透明质酸酶、磷酸酯酶等多种水解酶，受精时释放以穿越卵丘和透明带，本质为特殊溶酶体。线粒体位于精子中段供能；滑面内质网、中心粒、粗面内质网均不构成顶体，顶体酶体系与溶酶体同源"},{"q":"理论上讲，一个初级精母细胞最终能形成精子的数目是","o":["2个","4个","6个","8个","10个"],"a":1,"e":"理论上一个初级精母细胞最终形成4个精子。初级精母细胞经第一次减数分裂形成两个次级精母细胞，后者各经第二次减数分裂形成两个精子细胞，精子细胞再经变形成为精子，故总计四个。两个为次级精母细胞数目或卵子发生中一个初级卵母细胞的产物；六、八、十个均不符合两次减数分裂后数目翻两番的规律"},{"q":"子宫内膜的上皮是","o":["单层立方上皮，含分泌细胞","单层立方上皮或单层扁平上皮，以分泌细胞为主","单层柱状上皮，以分泌细胞为主","单层柱状或假复层纤毛柱状上皮，以纤毛细胞为主","单层柱状上皮，以纤毛细胞为主"],"a":2,"e":"子宫内膜的上皮是单层柱状上皮，以分泌细胞为主。子宫内膜表面上皮为单层柱状，由分泌细胞和少量纤毛细胞组成，以分泌细胞为主，腺体亦由单层柱状上皮构成。单层立方上皮见于甲状腺滤泡、肾小管；以纤毛细胞为主的单层柱状或假复层纤毛柱状上皮见于输卵管、呼吸道，均非子宫内膜上皮类型"},{"q":"微皱褶细胞","o":["是组成肠腺的一种细胞","其基底面有许多微皱褶","在光镜下很容易辨认","可摄取抗原并传递给下方的淋巴细胞","产生的分泌片与IgA结合形成sIgA"],"a":3,"e":"微皱褶细胞可摄取抗原并传递给下方的淋巴细胞。微皱褶细胞位于小肠集合淋巴小结表面，电镜下胞质富含囊泡，可摄取肠腔内抗原，以囊泡形式转运并传递给下方免疫细胞，进而提呈给淋巴细胞，启动黏膜免疫。该细胞并非肠腺组成细胞；其基底面无大量微皱褶；光镜下不易辨认；分泌片由上皮细胞产生并与IgA结合成sIgA，均非其特点"},{"q":"下列哪种细胞是周围神经系统的神经胶质细胞","o":["卫星细胞","嗅细胞","锥体细胞","味细胞","毛细胞"],"a":0,"e":"下列细胞中属于周围神经系统神经胶质细胞的是卫星细胞。卫星细胞包绕周围神经节内节细胞胞体及其突起，与施万细胞同属周围神经系统的神经胶质细胞。嗅细胞为嗅觉感受细胞；锥体细胞为大脑皮质神经元；味细胞为味觉感受细胞；毛细胞为听觉与位觉感受细胞，均属感受器或神经元，而非神经胶质细胞"},{"q":"毛细血管可分为","o":["连续型、不连续型、有孔型和血窦","连续型、有孔型和血窦","无孔型和有孔型","连续型、不连续型、有孔型和无孔型","连续型和不连续型"],"a":1,"e":"毛细血管可分为连续型、有孔型和血窦三类。连续毛细血管内皮连续、有紧密连接；有孔毛细血管内皮有窗孔，见于胃肠黏膜、内分泌腺、肾血管球；血窦又称窦状或不连续毛细血管，管腔大形态不规则。无孔型并非独立分类，不连续型即血窦的别称，故含不连续型与有孔型并列或分出无孔型的选项会造成分类重复或错误"},{"q":"软骨分类的依据是","o":["软骨细胞的数量","软骨基质中硫酸软骨素的含量","软骨基质中纤维的种类","软骨细胞的形态","软骨的功能"],"a":2,"e":"软骨分类的依据是软骨基质中纤维的种类。根据基质中纤维的种类和含量，软骨分为透明软骨、弹性软骨和纤维软骨三类，分别含Ⅱ型胶原原纤维、弹性纤维和大量胶原纤维束。软骨细胞数量、形态及硫酸软骨素含量不是分类依据；软骨的功能与分布虽不同，但分类标准仍是基质纤维的类型"},{"q":"早期的神经板为","o":["假复层柱状上皮","单层柱状上皮","单层立方上皮","复层柱状上皮","假复层纤毛柱状上皮"],"a":1,"e":"早期的神经板为单层柱状上皮。神经管及神经板最初由单层柱状上皮构成，以后演变为假复层柱状上皮称神经上皮。随着发育，神经上皮细胞增殖迁移，形成套层与边缘层。假复层柱状上皮、复层柱状上皮为后续或他处上皮类型；假复层纤毛柱状上皮见于呼吸道；单层立方上皮见于肾小管、甲状腺滤泡，均非早期神经板上皮"},{"q":"膀胱腔面上皮的特点为","o":["细胞形状可发生变化","上皮的厚度恒定不变","浅层细胞为柱状","表层细胞角化以防止尿液侵蚀","基底面凹凸不平"],"a":0,"e":"膀胱腔面上皮的特点为细胞形状可发生变化。膀胱腔面为变移上皮，其细胞形状和层数可随器官空虚与扩张而改变：空虚时上皮变厚、细胞层数多、盖细胞呈大立方形；充盈时上皮变薄、层数减少、盖细胞扁平。变移上皮厚度并非恒定；浅层盖细胞空虚时呈立方形而非柱状；表层细胞不角化；基底面平坦附着于基膜，均非其特点"},{"q":"肾的哪段血管胶体渗透压高","o":["入球微动脉","球内毛细血管","球后毛细血管","小叶间静脉","小叶间动脉"],"a":2,"e":"肾的血管中胶体渗透压高的是球后毛细血管。血液流经血管球时大量水分和小分子被滤出，剩余血液中蛋白质浓度升高，故出球微动脉延续形成的球后毛细血管内胶体渗透压很高，有利于肾小管重吸收的物质进入血液。入球微动脉、球内毛细血管、小叶间动脉、小叶间静脉均未经历大量滤过，胶体渗透压相对较低"},{"q":"对骨膜的描述，哪项是错误的","o":["穿通纤维与骨外膜相连","骨的外表面被覆骨外膜","骨的外表面与骨髓腔面均被覆骨外膜","骨髓腔面和骨小梁表面被覆骨内膜","穿通管和中央管内表面也被覆骨内膜"],"a":2,"e":"对骨膜的描述，错误的是骨的外表面与骨髓腔面均被覆骨外膜。骨外表面除关节面被覆骨外膜，骨髓腔面、骨小梁表面、穿通管和中央管内表面被覆的是骨内膜，而非骨外膜。穿通纤维与骨外膜相连、骨外表面被覆骨外膜、骨髓腔面和骨小梁表面被覆骨内膜、穿通管与中央管内表面被覆骨内膜等描述均正确"},{"q":"关于肾上腺皮质束状带的叙述，错误的是","o":["皮质中最厚，腺细胞排列成索状","腺细胞滑面内质网丰富，线粒嵴呈管泡状","腺细胞含较多分泌颗粒","腺细胞含大量的脂滴","细胞间有丰富的血窦"],"a":2,"e":"关于肾上腺皮质束状带，错误的是腺细胞含较多分泌颗粒。束状带细胞为类固醇激素分泌细胞，分泌糖皮质激素，胞质内富含滑面内质网、管泡状嵴的线粒体和大量脂滴，不含分泌颗粒；分泌颗粒为含氮激素分泌细胞的特征。束状带为皮质中最厚、腺细胞排列成索状，细胞间有丰富血窦，这些描述均属实"},{"q":"骨骼肌收缩的结构基础是","o":["肌浆网","肌节","横小管","线粒体","粗面内质网"],"a":1,"e":"骨骼肌收缩的结构基础是肌节。肌节为相邻两条Z线之间的一段肌原纤维，由1/2I带＋A带＋1/2I带构成，含粗、细肌丝及收缩相关蛋白，是骨骼肌纤维结构和功能的基本单位，也是收缩的结构基础。肌浆网为贮存钙的滑面内质网；横小管传导兴奋；线粒体供能；粗面内质网合成蛋白，均非收缩的结构基础本身"},{"q":"卵泡液由","o":["卵泡细胞分泌形成","卵泡膜细胞分泌形成","卵泡膜血管内血液渗出而成","卵泡细胞分泌和卵泡膜血管内血液渗出而成","卵泡细胞和卵泡膜细胞共同分泌形成"],"a":3,"e":"卵泡液由卵泡细胞分泌和卵泡膜血管内血液渗出而成。次级卵泡的卵泡细胞即颗粒细胞分泌产生卵泡液，同时卵泡膜内层血管丰富，血液渗出成分亦汇入卵泡腔，二者共同形成卵泡液。仅归因于卵泡细胞分泌、仅卵泡膜细胞分泌、仅血液渗出或卵泡细胞与卵泡膜细胞共同分泌，均遗漏了血液渗出的成分或混淆了分泌细胞类型"},{"q":"关于支气管树结构的变化错误的是","o":["上皮逐渐变薄，杯状细胞逐渐变少以至消失","管径逐渐变细，管壁逐渐变薄","肌层越来越薄","腺体逐渐变少，最后消失","软骨呈不规则片状，逐渐减少以至消失"],"a":2,"e":"关于支气管树结构的变化，错误的是肌层越来越薄。支气管自上而下分支，管径变细、管壁变薄，上皮渐薄、杯状细胞减少至消失，腺体与软骨逐渐减少消失，但平滑肌相对增多，至终末细支气管形成完整的环行平滑肌，并非越来越薄。其余各项关于上皮、管径管壁、腺体、软骨的变化描述均符合支气管树的结构演变规律"},{"q":"排卵时，随卵泡液释放出的成分是","o":["成熟卵细胞","成熟卵细胞和透明带","成熟卵细胞、透明带和放射冠","初级卵母细胞、透明带和放射冠","次级卵母细胞、透明带和放射冠"],"a":4,"e":"排卵时，随卵泡液释放出的成分是次级卵母细胞、透明带和放射冠。排卵前初级卵母细胞已完成第一次减数分裂形成次级卵母细胞，排卵时次级卵母细胞连同其外面的透明带和放射冠一并从卵泡壁脱落，随卵泡液排出。成熟卵细胞为第二次减数分裂完成后才有；初级卵母细胞在排卵前已转变，故含初级卵母细胞或成熟卵细胞的选项均不符排卵时的实际状态"},{"q":"关于嗜酸性粒细胞，哪项错误","o":["嗜酸性颗粒含组胺酶和芳基硫酸酯酶","具有抗寄生虫作用","在血流中停留6～8小时","占白细胞总数0.5%～3%","导致过敏反应"],"a":4,"e":"关于嗜酸性粒细胞，错误的是导致过敏反应。嗜酸性粒细胞胞质颗粒含组胺酶、芳基硫酸酯酶，可分解组胺、灭活白三烯，发挥抗过敏及抗寄生虫作用，并不导致过敏反应；导致过敏反应的是肥大细胞和嗜碱性粒细胞。其颗粒含组胺酶和芳基硫酸酯酶、具抗寄生虫作用、血流中停留6至8小时、占白细胞总数0.5%至3%均属实"},{"q":"肥大细胞较大，胞质内充满丰富的嗜碱性颗粒，颗粒内含有多种细胞因子和生物活性物质，发挥多种生理功能。当细胞脱颗粒时会","o":["使毛细血管通透性降低","减轻炎症反应","减轻支气管痉挛","导致荨麻疹","导致血压升高"],"a":3,"e":"肥大细胞脱颗粒会导致荨麻疹。肥大细胞脱颗粒释放组胺、白三烯等，使皮肤微静脉和毛细血管扩张、通透性增强，形成红肿即荨麻疹；还可致支气管痉挛、哮喘及全身小动脉扩张、血压下降甚至休克。脱颗粒使毛细血管通透性升高而非降低；引发而非减轻炎症；导致而非减轻支气管痉挛；引起血压下降而非升高，故这些选项均与脱颗粒效应相反"},{"q":"关于肾单位的组成，哪项是正确的","o":["肾小体和泌尿小管","肾小体，近曲小管，远曲小管和髓袢","肾小体和髓袢","肾小体和近端小管","肾小体和远端小管"],"a":1,"e":"关于肾单位的组成，正确的是肾小体、近曲小管、远曲小管和髓袢。肾单位由肾小体和与其相连的肾小管组成，肾小管包括近端小管、细段和远端小管，近曲小管、远曲小管与髓袢共同构成肾小管。肾小体和泌尿小管的组合错误，因泌尿小管含集合管而集合管不属于肾单位；仅髓袢或仅近端、远端小管的组合均不完整"},{"q":"关于子宫内膜分泌期的描述中，哪项是错误的","o":["为月经周期的第15～28天","又称黄体期","固有层呈生理性水肿","子宫腺腔增大，腔内可见分泌物","螺旋动脉短暂扩张，导致功能层血管破裂"],"a":4,"e":"关于子宫内膜分泌期，错误的是螺旋动脉短暂扩张，导致功能层血管破裂。分泌期为月经周期第15至28天，又称黄体期，固有层呈生理性水肿，子宫腺腔增大并可见分泌物。螺旋动脉短暂扩张致功能层血管破裂、出血剥落是月经期的变化，而非分泌期；分泌期为内膜增厚分泌旺盛阶段，故该项张冠李戴"},{"q":"人体组织常被归纳为四大类型，通常指","o":["上皮组织、疏松结缔组织、肌组织、神经组织","上皮组织、结缔组织、骨骼肌组织、神经组织","上皮组织、结缔组织、肌组织、神经组织","上皮组织、固有结缔组织、肌组织、神经组织","被覆上皮组织、结缔组织、肌组织、神经组织"],"a":2,"e":"人体组织常归纳的四大类型是上皮组织、结缔组织、肌组织和神经组织。此四类为基本组织，是构成机体器官的基本成分，各有一定分布规律和功能。疏松结缔组织、固有结缔组织、被覆上皮均为结缔组织或上皮组织的亚类，不能与四大基本组织并列；骨骼肌组织亦只是肌组织的一种，故含这些亚类并列或以亚类替换的选项均不符合四大类型的划分"},{"q":"腺垂体调节下丘脑的主要方式是","o":["交感神经调节","副交感神经调节","反馈方式调节","分泌释放激素调节","分泌释放抑制激素调节"],"a":2,"e":"腺垂体远侧部分泌的促激素经血流反馈作用于下丘脑，调节其释放激素与释放抑制激素的分泌，构成下丘脑-腺垂体-靶腺轴的负反馈调节，故为反馈方式。分泌释放激素与释放抑制激素是下丘脑调节腺垂体的方式，D、E项方向相反。交感与副交感神经调节并非腺垂体与下丘脑之间的主要联系"},{"q":"在淋巴结和脾，以B细胞为主的结构是","o":["副皮质区和淋巴小结","副皮质区和脾索","副皮质区和动脉周围淋巴鞘","淋巴小结和动脉周围淋巴鞘","淋巴小结和脾小体"],"a":4,"e":"淋巴小结（脾内称脾小体）主要由大量B淋巴细胞构成，是体液免疫应答的部位，故淋巴结与脾中以B细胞为主的结构是淋巴小结和脾小体。副皮质区和动脉周围淋巴鞘为胸腺依赖区，以T细胞为主，A、B、C、D项均属此类。脾索属红髓，含B细胞与巨噬细胞，但非以B细胞为主的特征性结构"},{"q":"皮肤的表皮中可见","o":["毛细血管","触觉小体","环层小体","游离神经末梢","肌梭"],"a":3,"e":"游离神经末梢的细支裸露，广泛分布于表皮、角膜与毛囊的上皮细胞之间，感受温度、应力及化学物质刺激，参与冷、热、轻触和痛觉，故表皮中可见游离神经末梢。毛细血管位于真皮，表皮无血管。触觉小体与环层小体为有被囊末梢，位于真皮乳头和深层；肌梭位于骨骼肌内，均不进入表皮"},{"q":"增生期子宫内膜的子宫腺细胞光镜下的核下空泡是","o":["分泌颗粒聚集而成","脂滴聚集而成","糖原聚集而成","核糖体聚集而成","过氧化物酶体聚集而成"],"a":2,"e":"增生晚期腺细胞顶部出现分泌颗粒，核下区糖原集聚，切片染色时糖原被溶解而显示为空泡，故核下空泡为糖原聚集而成。分泌颗粒位于腺细胞顶部而非核下，A项不符。脂滴聚集是蜕膜细胞的特征，与增生期腺细胞无关；核糖体与过氧化物酶体均不会在光镜下形成可被溶解的核下空泡"},{"q":"关于成骨细胞的形态描述，哪项正确","o":["胞体较大，有多个大而圆的细胞核","胞质嗜酸性","细胞表面有许多细小突起，可与邻近成骨细胞形成缝隙连接","有大量线粒体和溶酶体","有许多吞噬泡和吞噬体"],"a":2,"e":"成骨细胞胞体较大，表面有许多细小突起，可与邻近成骨细胞及骨细胞形成缝隙连接以利细胞间通讯，故该描述正确。成骨细胞核大而圆但为单核，非多个大核；胞质呈弱嗜碱性而非嗜酸性；胞质含丰富粗面内质网和高尔基复合体，大量溶酶体与吞噬泡为破骨细胞特征，故其余各项不符"},{"q":"虹膜上皮来自胚胎的","o":["视杯口边缘部","视柄","视杯内层","视杯外层","视杯口周围间充质"],"a":0,"e":"视杯口边缘部内层上皮不增厚，与外层色素上皮相贴并向晶状体泡与角膜之间的间充质内延伸，形成视网膜盲部即睫状体与虹膜的上皮，故虹膜上皮来自视杯口边缘部。视杯外层分化为色素上皮层，内层分化为视网膜视部神经层；视柄形成视神经；视杯口周围间充质形成虹膜基质而非上皮"},{"q":"在光镜下进行观察的石蜡包埋切片厚度一般是","o":["0.1～0.5μm","1μm左右","5～10μm","50μm","100μm"],"a":2,"e":"光镜观察的石蜡包埋组织切片一般切成5～10μm，此厚度既保证透光又能清晰显示组织结构，故为5～10μm。0.1～0.5μm与1μm左右为电镜超薄切片厚度，光镜下过薄难辨结构；50μm与100μm过厚，组织重叠、透光差，均不适于常规石蜡切片观察"},{"q":"粗面内质网和高尔基复合体是合成蛋白质相关的细胞器。在疏松结缔组织内，数量最多，具有丰富粗面内质网和发达高尔基复合体，可合成和分泌胶原蛋白和弹性蛋白的细胞是","o":["巨噬细胞","肥大细胞","白细胞","脂肪细胞","成纤维细胞"],"a":4,"e":"成纤维细胞是疏松结缔组织中数目最多、最主要的细胞，电镜下含丰富粗面内质网与发达高尔基复合体，属持续型蛋白质分泌细胞，合成并分泌胶原蛋白、弹性蛋白及无定形基质。巨噬细胞主司吞噬与抗原呈递；肥大细胞释放组胺、肝素；脂肪细胞贮存脂肪；白细胞为游走免疫细胞，均不以合成胶原纤维为职能"},{"q":"淋巴细胞从血液进入脾内淋巴组织的重要通道","o":["动脉周围淋巴鞘","脾血窦","脾索","边缘窦","淋巴小结"],"a":3,"e":"中央动脉侧支末端在边缘区膨大形成边缘窦，是血液内抗原及淋巴细胞进入白髓的通道，故为边缘窦。高内皮微静脉是淋巴细胞进入淋巴结等周围淋巴组织的重要通道，但脾内无此结构；动脉周围淋巴鞘与淋巴小结为白髓的T、B细胞区，脾血窦与脾索属红髓，均非该通道"},{"q":"以下对心肌纤维超微结构的描述，哪项是错误的","o":["肌原纤维不如骨骼肌的明显","横小管位于明带和暗带交界处","肌浆网不如骨骼肌的发达","仅形成二联体","心肌纤维连接处形成闰盘"],"a":1,"e":"心肌纤维横小管较粗，位于Z线水平；骨骼肌横小管才位于明带与暗带交界处，故该项描述错误。心肌肌原纤维粗细不等、界限不如骨骼肌明显，肌质网不发达仅形成二联体，相邻纤维连接处形成闰盘，其余各项均为心肌纤维的正确特征"},{"q":"胎盘中分泌HPL的主要是","o":["细胞滋养层","合体滋养层","基蜕膜","包蜕膜","壁蜕膜"],"a":1,"e":"HPL即人胎盘催乳素，由胎盘绒毛的合体滋养层合成并分泌，该层是胎盘行使内分泌与物质交换功能的主要细胞层。细胞滋养层为增殖性干细胞层，主要分化为合体滋养层；基蜕膜、包蜕膜与壁蜕膜为妊娠期子宫内膜的蜕膜部分，均不分泌HPL"},{"q":"假单极神经元存在于","o":["大脑皮质","小脑皮质","自主神经节","脊髓灰质","脑脊神经节"],"a":4,"e":"脊神经节与脑神经节属感觉神经节，其内感觉神经元绝大部分为假单极神经元，故假单极神经元存在于脑脊神经节。自主神经节内为多极运动神经元；大脑皮质与小脑皮质神经元为多极神经元；脊髓灰质内为多极运动神经元与中间神经元，均非假单极神经元"},{"q":"来自内胚层的是","o":["外耳道和中耳鼓室的上皮","中耳鼓室和咽鼓管的上皮","外耳道和咽鼓管的上皮","中耳鼓室和膜迷路的上皮","膜迷路和咽鼓管的上皮"],"a":1,"e":"第1对咽囊伸长演化为咽鼓管，末端膨大演化为中耳鼓室，二者上皮均来自内胚层，故中耳鼓室和咽鼓管的上皮来自内胚层。外耳道由第1鳃沟形成，其上皮来自外胚层；膜迷路由听泡演化，上皮亦来自外胚层，故含外耳道或膜迷路的各项均不符"},{"q":"关于近曲小管上皮细胞的特征，哪项是错误的","o":["细胞分界清晰","腔面有刷状缘","细胞基部有纵纹","胞质嗜酸性","细胞核呈圆形，位于近基底部"],"a":0,"e":"近曲小管上皮细胞侧面有许多侧突，相邻细胞侧突相互嵌合，故光镜下细胞分界不清，细胞分界清晰为错误描述。其腔面有刷状缘，基部有质膜内褶形成的纵纹，胞质嗜酸性，核圆形位于近基底部，余项均正确；分界清楚是远端小管与集合管上皮的特点"},{"q":"下列哪种细胞的滑面内质网最发达","o":["催乳素细胞","肾上腺皮质细胞","肾上腺髓质细胞","滤泡旁细胞","滤泡上皮细胞"],"a":1,"e":"类固醇激素分泌细胞的超微结构特点是胞质含丰富滑面内质网，肾上腺皮质细胞与性腺内分泌细胞属此类，尤以束状带最典型，故其滑面内质网最发达。催乳素细胞、滤泡旁细胞、滤泡上皮细胞均为含氮激素分泌细胞，以粗面内质网与高尔基复合体为主；肾上腺髓质细胞分泌肾上腺素，亦非滑面内质网发达者"},{"q":"关于输尿管芽，下列哪项错误","o":["是中肾管末端近泄殖腔处长出的盲管","属于中胚层组织","部分分化物参与构成泌尿小管","其分支末端诱导生后肾原基形成肾小体","其分支末端将与肾小管接通"],"a":3,"e":"输尿管芽末端反复分支形成肾盂、肾盏和集合管，集合管末端诱导生后肾组织形成肾小管，肾小管一端膨大凹陷成肾小囊包绕毛细血管球才形成肾小体，故诱导肾小体形成的是生后肾组织而非输尿管芽分支末端，该项错误。输尿管芽为近泄殖腔处中肾管长出的盲管，属中胚层，其分支末端将与肾小管接通，余项正确"},{"q":"关于单层柱状上皮的描述，哪项正确","o":["由一层棱柱状细胞组成","胞核长圆形，位细胞中央","常分布于消化道、呼吸管道","以保护功能为主","游离面常见微绒毛和纤毛"],"a":0,"e":"单层柱状上皮由一层棱柱状细胞组成，表面观细胞呈六角形或多角形，垂直切面呈柱状，核椭圆形且长轴与细胞长轴一致，故该描述正确。胞核位于近基底部而非中央；主要分布于胃肠与子宫，呼吸管道为假复层纤毛柱状上皮；以吸收分泌为主而非保护；游离面常为微绒毛，纤毛并非其常见结构"},{"q":"消化系统和呼吸系统的发生在一章内叙述，是因为","o":["两者都是管道性器官组成","两者的主要器官均来自原始消化管","两者均经口与鼻与外界相通","两者的管壁均分黏膜、黏膜下层、肌层和外膜","机体通过两者从外界摄取物质"],"a":1,"e":"消化系统和呼吸系统的主要器官均来自原始消化管，其黏膜上皮、腺上皮与肺泡上皮均来自内胚层，二者发生同源且密切关联，故合于一章叙述。管道性器官、经口鼻与外界相通、管壁分层及摄取物质仅描述形态或功能的相似，均非合章叙述的发生学依据"},{"q":"胆囊的主要功能是","o":["合成胆汁","贮存、浓缩和释放胆汁","分解胆汁","分泌消化脂类的酶","贮存消化的食物"],"a":1,"e":"胆囊贮存并浓缩胆汁，进食尤其高脂食物后，在缩胆囊素-促胰酶素作用下胆囊持续收缩、胆总管括约肌松弛，将胆汁排入肠腔，故其主要功能为贮存、浓缩和释放胆汁。胆汁由肝细胞合成，胆囊不分解胆汁；分泌消化脂类酶的是胰腺；贮存食物为胃的功能"},{"q":"关于红细胞描述错误的是","o":["外周血红细胞均无细胞器","胞质中充满血红蛋白","细胞呈双凹圆盘状","细胞膜上有ABO血型抗原","向全身的组织和细胞供给氧气，带走二氧化碳"],"a":0,"e":"成熟红细胞无核、无任何细胞器，但外周血中尚有少量网织红细胞，其胞质内仍残留核糖体等结构，故外周血红细胞均无细胞器的表述绝对化，为错误项胞质充满血红蛋白、呈双凹圆盘状、膜上有ABO血型抗原、运输氧与二氧化碳均为红细胞的正确描述"},{"q":"参与室间隔膜部形成的结构有","o":["第一房间隔和第二房间隔的结缔组织","心内膜垫和左右心球嵴的结缔组织","半月瓣基部未分化的结缔组织","房室瓣基部未分化的结缔组织","心球和心内膜垫的结缔组织"],"a":1,"e":"第7周末左右心球嵴对向生长融合并向下延伸与室间隔肌部融合，同时心内膜垫间充质增生、室间隔肌部上缘上长与心球嵴融合，共同形成室间隔膜部封闭室间孔，故参与结构为心内膜垫和左右心球嵴的结缔组织。第一、二房间隔参与心房分隔；半月瓣与房室瓣基部不参与膜部形成"},{"q":"骨板由（ ）组成","o":["骨细胞、胶原纤维和钙盐","弹性纤维、有机基质和钙盐","胶原纤维、弹性纤维和钙盐","胶原纤维、有机基质和钙盐","胶原纤维、弹性纤维、网状纤维和钙盐"],"a":3,"e":"骨板由大量胶原纤维（主要为Ⅰ型胶原蛋白，约占有机成分九成）、少量无定形有机基质（蛋白聚糖等）及沉积的钙盐构成，故为胶原纤维、有机基质和钙盐。骨细胞位于骨陷窝内并非骨板组成成分；骨组织有机成分为胶原纤维与基质，不含弹性纤维，故含弹性纤维的各项均不符"},{"q":"心外膜的组成是","o":["间皮","脂肪组织","间皮和结缔组织","间皮和脂肪组织","结缔组织和平滑肌"],"a":2,"e":"心外膜即心包脏层，为浆膜，其外表面为间皮，间皮深部为疏松结缔组织，故心外膜由间皮和结缔组织组成。单纯间皮不完整；心外膜下可含脂肪组织但非基本组成；结缔组织和平滑肌为血管外膜或某些器官被膜特点，均非心外膜的构成"},{"q":"下面对软骨细胞的描述，哪项是错误的","o":["近软骨膜处的软骨细胞较幼稚","软骨中央处的软骨细胞较成熟","同源细胞群是由一个软骨细胞分裂增殖而来","同源细胞群是软骨细胞逐渐集合而成","同源细胞群中每个细胞都有各自的软骨陷窝和软骨囊"],"a":3,"e":"同源细胞群由一个幼稚软骨细胞增殖分裂形成，一般2～8个，并非多个软骨细胞逐渐集合而成，故该项错误。近软骨膜处软骨细胞幼稚、中央处成熟；同源细胞群中每个细胞都有各自的软骨陷窝和软骨囊，其余各项均正确"},{"q":"形成原条的胚层是","o":["下胚层","上胚层","胚内中胚层","胚外中胚层","内胚层"],"a":1,"e":"第3周时上胚层部分细胞增殖较快，向胚盘一端中线迁移聚集形成原条，原条细胞进而迁移形成中胚层并取代下胚层形成内胚层，故原条由上胚层形成。下胚层被取代形成内胚层；胚内、胚外中胚层与内胚层均为原条细胞迁移或分化的产物，非原条来源"},{"q":"子宫内膜为分泌期时，卵巢的结构是","o":["卵泡开始发育和成熟","卵泡退化阶段","黄体正在形成和发育","黄体正在退化","卵泡膜正在形成"],"a":2,"e":"月经周期第14天排卵后内膜转入分泌期，此时卵巢内黄体形成并发育，分泌孕激素和雌激素使内膜继续增厚并出现分泌变化，又称黄体期，故为黄体正在形成和发育。卵泡发育成熟在增生期；黄体退化在月经前；卵泡膜形成于卵泡发育早期；卵泡退化见于闭锁"},{"q":"关于胸腺细胞的描述，错误的是","o":["是胸腺内分化发育的各期T细胞","外皮质层的大淋巴细胞为前胸腺细胞","深皮质层的淋巴细胞体积较小，为普通胸腺细胞，数量多","凡不能与自身抗原相结合或与自身MHC抗原相容的胸腺细胞将被灭活或淘汰","成熟的普通胸腺细胞，其CD4和CD8中有一种增强，另一种减弱或消失"],"a":3,"e":"胸腺细胞的阴性选择淘汰的是能与自身抗原发生反应的T细胞，阳性选择保留能与自身MHC适度结合者，该项把不能与自身抗原结合当作淘汰条件，逻辑颠倒，故错误。胸腺细胞为各期T细胞，外皮质大淋巴细胞为前胸腺细胞，深皮质小淋巴细胞为普通胸腺细胞且数量多，成熟细胞CD4或CD8之一增强，余项正确"},{"q":"在口腔开口处渐变为复层扁平上皮的导管是","o":["闰管","纹状管","小叶间导管","总导管","小叶内导管"],"a":3,"e":"大唾液腺导管由闰管、纹状管、小叶间导管逐级汇合为总导管，总导管开口于口腔，其管壁由假复层柱状上皮逐渐移行为复层扁平上皮，与口腔黏膜相续，故为总导管。闰管为单层扁平或立方上皮，纹状管为单层高柱状上皮，小叶间导管为单层柱状至假复层柱状上皮，均不移行为复层扁平上皮"},{"q":"足月分娩时羊水量为","o":["500～1000ml","500～1500ml","500～2000ml","1000～1500ml","1000～2000ml"],"a":3,"e":"羊水量随胚胎增长而增多，足月分娩时约1000～1500ml。羊水过少（300ml以下）易致羊膜与胎儿粘连，羊水过多（2000ml以上）也影响胎儿发育，故500ml级的各项偏少，1000～2000ml上限过高，均不符合足月正常量"},{"q":"神经元内的尼氏体是电镜下的","o":["溶酶体","粗面内质网和游离核糖体","线粒体","高尔基复合体","游离核糖体和滑面内质网"],"a":1,"e":"尼氏体光镜下呈强嗜碱性，电镜下由发达的粗面内质网和游离核糖体构成，是神经元合成蛋白质的部位，故为粗面内质网和游离核糖体。溶酶体、线粒体、高尔基复合体虽存在于胞质但非尼氏体成分；尼氏体不含滑面内质网，故含滑面内质网者不符"},{"q":"胎儿血循环中，以下哪个血管中的血液含氧量最低","o":["主动脉弓","肺动脉","脐动脉","降主动脉","动脉导管"],"a":2,"e":"脐动脉将胎儿含代谢废物、含氧量低的静脉血输送至胎盘绒毛进行物质交换，是胎儿循环中含氧量最低的血管。脐静脉含经胎盘交换后的富氧血，含量最高；主动脉弓、降主动脉与动脉导管内为混合血，肺动脉内为右心室输出的静脉血，含氧量均高于脐动脉"},{"q":"分泌物含黏液的腺体是","o":["舌下腺","腮腺","汗腺","胰腺","泪腺"],"a":0,"e":"舌下腺为混合腺，以黏液腺泡为主并多见混合腺泡，分泌物含黏液，故为舌下腺。腮腺为纯浆液腺，分泌唾液淀粉酶而不含黏液；汗腺与泪腺分泌物为水样液体；胰腺为浆液性腺，分泌消化酶，均不以黏液分泌为主"},{"q":"脑脊液是由下列哪种结构分泌的","o":["脉络丛上皮下的毛细血管","脉络膜","脉络丛上皮","室管膜上皮","蛛网膜"],"a":2,"e":"脉络丛由脑室壁软膜与室管膜相贴突入脑室形成，室管膜分化为有分泌功能的脉络丛上皮，其细胞不断分泌脑脊液，故为脉络丛上皮。上皮下毛细血管提供物质基础但不直接分泌；脉络膜为眼球血管膜；一般室管膜无分泌功能；蛛网膜粒负责吸收脑脊液而非分泌"},{"q":"淋巴小结生发中心内主要增殖的细胞是","o":["T淋巴细胞","B淋巴细胞","K细胞","NK细胞","浆细胞"],"a":1,"e":"淋巴小结生发中心暗区以B淋巴细胞和Th细胞为主，明区亦以B细胞为主并有滤泡树突状细胞与巨噬细胞，接触抗原后B细胞在此大量增殖分化，故主要增殖细胞为B淋巴细胞。T淋巴细胞主要位于副皮质区；K细胞与NK细胞非生发中心主要增殖细胞；浆细胞为B细胞分化的效应细胞，多位于髓索等处"},{"q":"关于螺旋器的描述，哪项错误","o":["位于膜蜗管的基底膜上","每个耳蜗中的螺旋器为一连续性的整体","上皮由毛细胞和支持细胞组成","内毛细胞排成3～4列，外毛细胞排成1列","毛细胞的游离面有规则排列的静纤毛"],"a":3,"e":"螺旋器毛细胞分为1列内毛细胞和3～4列外毛细胞，该项将二者列数颠倒，故错误。螺旋器位于膜蜗管基底膜上，每个耳蜗中为一连续整体，上皮由毛细胞与支持细胞组成，毛细胞游离面有规则排列的静纤毛，其余各项均正确"},{"q":"关于胎儿血液循环，哪项错误","o":["脐静脉血主要从静脉导管流入下腔静脉","进入右心房的血主要经卵圆孔入左心房","肺动脉的血大部经动脉导管入主动脉","主动脉弓的血大部分布到头颈部","脐动脉富含氧气的血流向胎盘"],"a":4,"e":"脐动脉将胎儿含氧低、含代谢废物的静脉血输送至胎盘，而非富氧血，故该项错误。脐静脉血大部分经静脉导管入下腔静脉，进入右心房的血主要经卵圆孔入左心房，肺动脉血大部经动脉导管入主动脉，主动脉弓血大部分布至头颈部，余项均正确"},{"q":"诱导神经管发生的结构是","o":["脊索","原条","原结","体节","神经沟"],"a":0,"e":"脊索形成后诱导其背侧中线外胚层增厚为神经板，神经板凹陷成神经沟，神经沟闭合形成神经管，故诱导神经管发生的结构是脊索。原条为三胚层形成的结构；原结与脊索、中胚层发生相关；体节为轴旁中胚层产物；神经沟本身即神经管的前身，均非诱导者"},{"q":"浦肯野纤维位于","o":["心室的内皮下层","心室的心内膜下层","心房的心肌层浅部","心肌层深部","心房的心内膜下层"],"a":1,"e":"心室的心内膜下层含心脏传导系统的分支即浦肯野纤维，其为房室束及其分支的主要细胞，在心室位于心内膜下层并伸入心肌膜，故位于心室的心内膜下层。心内皮下层不含浦肯野纤维；心房心肌层与心房心内膜下层非其主要分布区，心肌层深部亦非其所在"},{"q":"以下哪种细胞不产生纤维和基质","o":["成纤维细胞","成软骨细胞","成骨细胞","肥大细胞","腱细胞"],"a":3,"e":"成纤维细胞、成软骨细胞、成骨细胞与腱细胞均能合成并分泌纤维和基质，而肥大细胞主要合成释放组胺、肝素、白三烯等参与过敏反应，不产生纤维和基质，故为肥大细胞"},{"q":"来源于B淋巴细胞的是","o":["巨噬细胞","浆细胞","肥大细胞","嗜碱性粒细胞","嗜酸性粒细胞"],"a":1,"e":"初始B细胞在相应抗原刺激下转化为大淋巴细胞并增殖分化，其大部分子细胞成为效应B细胞即浆细胞，分泌抗体，故浆细胞来源于B淋巴细胞。巨噬细胞与肥大细胞来源于单核细胞或间充质；嗜碱性粒细胞与嗜酸性粒细胞来源于骨髓造血祖细胞，均非B细胞来源"},{"q":"以下关于皮肤的描述，正确的是","o":["是上皮组织，具备上皮组织的特点","可分为5层：基底层、棘层、颗粒层、透明层和角质层","是一个独立的器官","由表皮、真皮和皮下组织共同组成","可见丰富的神经末梢，但是没有血管分布"],"a":2,"e":"皮肤由表皮、真皮构成并含皮肤附属器，执行保护、感觉、调节体温等多种功能，是人体最大的器官，故皮肤是一个独立的器官。皮肤并非单纯上皮组织；五层分层仅是手掌足底厚皮的表皮分层；皮下组织不属于皮肤本身；真皮内血管丰富，故其余各项均不准确"},{"q":"小脑皮质的传出神经元是","o":["浦肯野细胞","高尔基细胞","篮状细胞","颗粒细胞","星形细胞"],"a":0,"e":"小脑皮质神经元包括浦肯野细胞、颗粒细胞、星形细胞、篮状细胞和高尔基细胞五种，其中浦肯野细胞是唯一的传出神经元，其轴突组成小脑皮质唯一传出纤维终止于小脑白质内神经核。高尔基细胞、篮状细胞、星形细胞为抑制性中间神经元；颗粒细胞为兴奋性中间神经元，其轴突形成平行纤维"},{"q":"近端小管管壁上皮游离面的微绒毛在光镜下称为","o":["微绒毛","纹状缘","刷状缘","皱褶缘","螺旋缘"],"a":2,"e":"近端小管上皮细胞游离面微绒毛在光镜下呈刷状缘，电镜下由大量较长微绒毛整齐排列构成，可扩大表面积以利重吸收，故为刷状缘。纹状缘为小肠吸收细胞微绒毛的光镜名称；皱褶缘为破骨细胞特有；微绒毛为电镜术语；螺旋缘属内耳结构，均不适用"},{"q":"质膜内褶处细胞质内常含有丰富的","o":["粗面内质网","滑面内质网","溶酶体","高尔基复合体","线粒体"],"a":4,"e":"质膜内褶是上皮细胞基底面细胞膜折向胞质形成的内褶，内褶间含有与其平行的长杆状线粒体，二者共同扩大基底部表面积以利水和电解质转运，故含丰富线粒体。粗面内质网、滑面内质网与高尔基复合体参与蛋白质或脂质合成，溶酶体参与消化，均非质膜内褶处的特征性成分"},{"q":"下一对甲状旁腺和上一对甲状旁腺的发生是","o":["第3对咽囊腹侧份的上皮增生分化而成","第3对咽囊背侧份的上皮增生分化而成","第4对咽囊腹侧份的上皮增生分化而成","第3和第4对咽囊腹侧份的上皮增生分化而成","第3和第4对咽囊背侧份的上皮增生分化而成"],"a":4,"e":"第3对咽囊背侧份细胞增生下移至甲状腺原基背侧分化为下一对甲状旁腺，第4对咽囊细胞增生迁移至甲状腺背侧上方分化为上一对甲状旁腺，故为第3和第4对咽囊背侧份的上皮增生分化而成。第3对咽囊腹侧份形成胸腺原基，仅取第3对或仅取背侧笼统表述均不完整"},{"q":"透明膜病是由于","o":["Ⅱ型肺泡细胞发育不良","Ⅰ型肺泡细胞发育不良","肺泡表面活性物质分泌过多","肺泡表面有一层纤毛","肺泡不能扩张"],"a":0,"e":"透明膜病又称新生儿呼吸窘迫综合征，因Ⅱ型肺泡细胞分化不良，不能产生足够表面活性物质，致肺泡表面张力增大，出生后肺泡不能随呼吸扩张而呼吸困难，故为Ⅱ型肺泡细胞发育不良。Ⅰ型肺泡细胞主要构成气-血屏障；表面活性物质分泌过少而非过多；肺泡无纤毛；肺泡不能扩张是结果而非病因"},{"q":"胚内体腔发生于","o":["侧中胚层","体节","间介中胚层","内胚层","轴旁中胚层"],"a":0,"e":"侧中胚层内部先出现小腔隙，后融合为一个大的胚内体腔，并将侧中胚层分为体壁中胚层和脏壁中胚层，故胚内体腔发生于侧中胚层。体节分化为骨骼肌与骨等；间介中胚层形成泌尿生殖系统；内胚层形成消化呼吸上皮；轴旁中胚层形成体节，均不形成胚内体腔"},{"q":"心脏房室束及其分支位于","o":["内皮下层","心肌膜浅层","心内膜下层","心肌膜深层","心外膜"],"a":2,"e":"房室结、房室束及其主要分支位于心内膜下层，在心室的房室束分支还进一步伸入心肌膜，故房室束及其分支位于心内膜下层。内皮下层为心内膜表层；心肌膜浅层与深层为心肌纤维所在，房室束分支仅部分伸入；心外膜为心包脏层，均非其所在"},{"q":"胚泡植入的正常部位是","o":["子宫底和体部内膜的功能层","子宫颈部黏膜","子宫内膜基底层与肌层之间","子宫内膜基底层","输卵管黏膜"],"a":0,"e":"胚泡正常植入于子宫底和体部内膜的功能层，该层较厚、靠近子宫腔，月经时脱落，受雌孕激素调节保持分泌期以利植入。子宫颈黏膜不适宜植入；基底层与肌层之间及基底层不发生周期性脱落，不参与正常植入；输卵管黏膜植入属宫外孕"},{"q":"对于大部分静脉来说，最厚的部分是","o":["内膜","内皮下层","中膜","环形平滑肌","外膜"],"a":4,"e":"静脉管壁薄、管腔大，与伴行动脉相比中膜薄而外膜厚，大部分静脉最厚的部分为外膜，内含结缔组织及纵行平滑肌束。内膜与内皮下层很薄；中膜较动脉薄；环形平滑肌主要见于动脉中膜或静脉特定部位，均非静脉最厚层"},{"q":"静脉瓣","o":["内皮凸入管腔折叠而成，见于全部静脉","内皮凸入管腔折叠而成，见于中静脉和大静脉","内膜凸入管腔折叠而成，见于全部静脉","内膜凸入管腔折叠而成，仅见于大静脉","内膜凸入管腔折叠而成，见于中静脉和大静脉"],"a":4,"e":"静脉瓣常见于管径2mm以上的静脉，由内膜凸入管腔折叠而成，表面覆以内皮，内部为含弹性纤维的结缔组织，主要见于中静脉和大静脉，故该描述正确。其由内膜而非单纯内皮凸入形成；微静脉与小静脉无瓣，并非见于全部静脉；也非仅见于大静脉"},{"q":"以下哪项不是淋巴细胞的特点","o":["约为白细胞总数的50%～70%","根据细胞形态分为大、中、小三种","血液中小淋巴细胞数量最多","根据功能的不同又可分为T、B、NK等","B淋巴细胞参与机体的体液免疫"],"a":0,"e":"淋巴细胞占白细胞总数的20%～40%，而50%～70%为中性粒细胞的比例，故该项不是淋巴细胞的特点。淋巴细胞依形态分大、中、小三种，血液中小淋巴细胞最多，依功能分T、B、NK等，B细胞参与体液免疫，余项均正确"},{"q":"下列不是中央乳糜管的结构特点的是","o":["管壁由一层内皮组成","内皮细胞间隙较大","基膜明显","通透性强","乳糜微粒容易进入管内"],"a":2,"e":"中央乳糜管管腔较大，内皮细胞间隙宽，无基膜，通透性大，乳糜微粒易进入，故基膜明显不是其结构特点。管壁由一层内皮组成、内皮间隙大、通透性强、乳糜微粒容易进入均为其特征"},{"q":"关于垂体的中间部，以下哪项正确","o":["比远侧部小，比神经部大","含神经胶质细胞","无分泌细胞","属神经垂体","有滤泡"],"a":4,"e":"腺垂体中间部仅占垂体体积约2%，由滤泡及其周围的嗜碱性细胞和嫌色细胞构成，滤泡内含胶质，故中间部有滤泡。中间部比远侧部小且比神经部小；不含神经胶质细胞，神经部才含；含嗜碱性等分泌细胞；属腺垂体而非神经垂体，余项均不符"},{"q":"神经元的轴突内缺少","o":["神经丝","微管","微丝","粗面内质网","线粒体"],"a":3,"e":"轴突内无粗面内质网和游离核糖体，不能合成蛋白质，所需蛋白由胞体合成后经轴突运输而来，故轴突内缺少粗面内质网。神经丝、微管、微丝构成轴质网架，线粒体供应能量，均存在于轴突内"},{"q":"以下关于光镜下神经元的特征，哪项是错误的","o":["细胞形态多种多样，均有突起","分为细胞体、树突和轴突三部分","核大而圆，异染色质少，核仁明显","胞体及突起内均有尼氏体","胞体及突起内均有神经原纤维"],"a":3,"e":"尼氏体仅分布于胞体和树突内，轴突及轴丘内无尼氏体，故胞体及突起内均有尼氏体为错误描述。神经元形态多样均有突起，分胞体、树突、轴突三部分，核大而圆、异染色质少、核仁明显，神经原纤维分布于胞体及突起内，余项均正确"},{"q":"支气管哮喘时，环形平滑肌发生痉挛性收缩的管道主要是","o":["叶支气管","段支气管","小支气管","终末细支气管","呼吸性细支气管"],"a":3,"e":"细支气管与终末细支气管壁中环行平滑肌明显，可在自主神经支配下收缩舒张以调节气流量，哮喘时终末细支气管环行平滑肌痉挛性收缩致气道狭窄，故主要为终末细支气管。叶、段、小支气管管壁有软骨片支撑、平滑肌不发达；呼吸性细支气已有肺泡开口、平滑肌稀少"},{"q":"神经元胞体不分布于","o":["神经","神经丛","神经节","灰质","神经核"],"a":0,"e":"神经由神经纤维集结而成，仅含轴突及神经胶质细胞，无神经元胞体，故神经元胞体不分布于神经。神经丛内含神经节细胞胞体；神经节内含节细胞胞体；灰质与神经核为中枢神经系统内胞体聚集处，均含神经元胞体"},{"q":"关于皮肤黑素细胞，哪项错误","o":["是多突起的细胞","内含黑素颗粒比角质形成细胞多","可把黑素颗粒转移给角质形成细胞","白种人和黑种人的黑素细胞数量相差不大","酪氨酸酶丰富"],"a":1,"e":"黑素细胞内形成的黑素颗粒迅速迁移至突起末端并被角质形成细胞吞入，故黑素颗粒在黑素细胞中很少、在角质形成细胞中反而较多，该项错误。黑素细胞为多突起细胞，白种人与黑种人黑素细胞数量相差不大、差异在颗粒大小与分布，酪氨酸酶丰富，可将颗粒转移给角质形成细胞，余项正确"},{"q":"无毛细血管分布的组织是","o":["骨骼肌","软骨组织","肌腱","平滑肌","韧带"],"a":1,"e":"软骨组织内无血管、淋巴管和神经，其营养靠软骨膜内血管供应并经基质渗透，故无毛细血管分布的是软骨组织。骨骼肌、平滑肌、肌腱与韧带内均有毛细血管分布"},{"q":"嗜碱性粒细胞的颗粒内含有","o":["白三烯和组胺","白三烯和肝素","组胺、肝素","芳基硫酸酯酶","组胺酶"],"a":2,"e":"嗜碱性颗粒属分泌颗粒，内含肝素、组胺、中性粒细胞趋化因子及嗜酸性粒细胞趋化因子等，故为组胺、肝素。白三烯为细胞受刺激后合成释放，并非颗粒内预先储存的主要成分；芳基硫酸酯酶与组胺酶为嗜酸性粒细胞颗粒所含，故含这两者的选项不符"},{"q":"中肾发生的描述中，哪一项错误","o":["发生于前肾尾侧的中肾嵴内","中肾小管的一端膨大，并内陷成肾小囊","背主动脉分支而来的毛细血管与肾小囊共同构成肾小体","中肾小管的另一端开口于体腔","中肾管由前肾管演化而来"],"a":3,"e":"中肾小管一端膨大内陷成肾小囊，与背主动脉分支的毛细血管共同构成肾小体，另一端与中肾管相通，而非开口于体腔，开口于体腔的是前肾小管，故该项错误。中肾发生于前肾尾侧中肾嵴内，中肾管由前肾管演化而来，余项均正确"},{"q":"关于前列腺的描述，哪项是错误的","o":["分泌物为稀薄的乳白色液体","腺实质分3带，即尿道周带、内带和外带","分泌部腺腔不规则，腔内可见凝固体或结石","其分泌活动受雄激素的影响","前列腺癌多发生于尿道周带"],"a":4,"e":"前列腺癌多发生于外带（主腺），而尿道周带（黏膜腺）与内带（黏膜下腺）是老年前列腺增生肥大的好发部位，故该项错误。前列腺分泌物为稀薄乳白色液体，腺实质分尿道周带、内带和外带三带，腺腔不规则可见凝固体或结石，分泌活动受雄激素影响，余项正确"},{"q":"一名医学生在做解剖实验时发现肝的脏面有一条纤维索，其一端连着下腔静脉，另一端连着门静脉左支。这条纤维索胚胎时期对应的结构是","o":["静脉韧带","静脉导管","肝圆韧带","脐动脉","脐静脉"],"a":1,"e":"静脉导管一端与左脐静脉相连，另一端通入下腔静脉，将胎盘回流血液导入下腔静脉，出生后闭锁形成静脉韧带，题干所述连于下腔静脉与门静脉左支的纤维索即其遗迹，故胚胎时期对应结构为静脉导管。肝圆韧带为脐静脉闭锁形成；脐动脉与脐静脉为胎儿血管；静脉韧带是出生后的名称"},{"q":"关于成神经细胞正确的是","o":["由室管膜层迁移至神经上皮外周","有分裂增生的能力","位于神经管套层，分化为神经元","位于边缘层","分化为神经元和神经胶质细胞"],"a":2,"e":"神经管管壁的套层由神经上皮细胞增殖迁移形成，其中成神经细胞分化为神经元，故成神经细胞位于神经管套层并分化为神经元。成神经细胞由神经上皮迁移而来而非由室管膜层向外迁移；其已失去分裂能力；边缘层为神经纤维所在无胞体；神经胶质细胞由神经胶质细胞分化，非成神经细胞分化"},{"q":"下列哪项结构不是起源于内胚层","o":["生精细胞","阴道前庭","男性尿道海绵体部","膀胱与输尿管交界处","女性尿道"],"a":3,"e":"膀胱与输尿管交界处即膀胱三角区，其上皮来自中肾管（中胚层），而非内胚层，故该项不是起源于内胚层。生精细胞来自原始生殖细胞（卵黄囊内胚层来源），阴道前庭、男性尿道海绵体部与女性尿道的上皮均来自尿生殖窦内胚层"},{"q":"结肠不同于小肠的结构在于","o":["有环行皱襞和绒毛，杯状细胞多，固有层内肠腺发达，有结肠带","有环行皱襞，无绒毛，杯状细胞特别多，固有层内肠腺较少，有结肠带","有半环行皱襞和绒毛，杯状细胞多，固有层内肠腺发达，有结肠带","有半环行皱襞，无绒毛，杯状细胞较少，固有层内肠腺发达，有结肠带","有半环行皱襞，无绒毛，杯状细胞特别多，固有层内肠腺发达，有结肠带"],"a":4,"e":"结肠黏膜有半月形皱襞而无绒毛，杯状细胞特别多，固有层内结肠腺发达，外纵行肌局部增厚形成3条结肠带，故该描述正确。环行皱襞与绒毛为小肠特征；杯状细胞较少或肠腺较少的各项均不符合结肠的结构特点"},{"q":"生精上皮的基底室内","o":["无生精细胞","有精母细胞","有精原细胞，初级和次级精母细胞","只有初级精母细胞","只有精原细胞"],"a":4,"e":"支持细胞侧面近基底部形成紧密连接，将生精上皮分为基底室与近腔室，基底室位于基膜与紧密连接之间，其内只有精原细胞，故为只有精原细胞。初级精母细胞、次级精母细胞及更晚期生精细胞均位于近腔室，不在基底室"},{"q":"对骨骼肌的描述，错误的一项是","o":["长圆柱状","单核","横纹明显","含大量肌原纤维","肌纤维周围有肌卫星细胞"],"a":1,"e":"骨骼肌纤维为多核细胞，一条肌纤维含几十甚至几百个核，故单核描述错误。骨骼肌纤维呈长圆柱状，横纹明显，含大量肌原纤维，周围有肌卫星细胞，余项均正确；单核且核位于中央为心肌或平滑肌特点"},{"q":"脾脏不具有下列哪项功能","o":["产生抗体和效应淋巴细胞","边缘区和脾索有滤血功能","脾脏可储存部分血细胞","脾小体可分泌激素","严重缺血时可恢复造血功能"],"a":3,"e":"脾小体（淋巴小结）主要由B淋巴细胞构成，参与体液免疫应答，不分泌激素，故脾不具有该功能。脾可产生抗体和效应淋巴细胞，边缘区与脾索有滤血功能，可储存部分血细胞，严重缺血时可恢复造血，余项均为脾的功能"},{"q":"具有趋化性的细胞是","o":["成纤维细胞","巨噬细胞","肥大细胞","浆细胞","脂肪细胞"],"a":1,"e":"巨噬细胞可沿趋化因子浓度梯度定向移动至产生和释放这些物质的部位，趋化性是其发挥吞噬与免疫应答功能的前提，故为巨噬细胞。成纤维细胞、肥大细胞、浆细胞与脂肪细胞均无典型趋化性"},{"q":"肺泡Ⅰ型细胞的特征正确的是","o":["不参与构成气-血屏障","细胞为立方形，染色浅","胞质内细胞器少，但含有大量吞饮小泡","损伤后可自我增殖分化补充","细胞菲薄处有大量窗孔"],"a":2,"e":"Ⅰ型肺泡细胞扁平菲薄，胞质内细胞器少但含大量吞饮小泡，可吞饮吸入的微小尘埃与表面活性物质，故该描述正确。Ⅰ型肺泡细胞参与构成气-血屏障；细胞呈扁平状而非立方形；损伤后不能自我增殖，由Ⅱ型肺泡细胞增殖分化补充；菲薄处无窗孔，有孔的是毛细血管内皮"},{"q":"关于表皮各层细胞结构特点的描述，哪项错误","o":["基底层细胞能不断增殖，分化为表皮其他层的细胞","基底层细胞胞质内含板层颗粒","颗粒层细胞质内有透明角质颗粒，板层颗粒多","透明层细胞的胞核和细胞器退化，光镜下为嗜酸均质状","角质层细胞胞质内充满角蛋白丝"],"a":1,"e":"板层颗粒出现于棘层上部和颗粒层细胞，基底层细胞胞质内不含板层颗粒，故该项错误。基底层为干细胞能不断增殖分化为其他各层细胞；颗粒层含透明角质颗粒和较多板层颗粒；透明层细胞核与细胞器退化呈嗜酸均质状；角质层胞质充满角蛋白丝，余项正确"},{"q":"关于呼吸性细支气管，下列哪项错误","o":["是终末细支气管的分支，一条终末细支气管可分支形成2～3条呼吸性细支气管","是肺呼吸部的一部分","上皮为假复层纤毛柱状上皮，有纤毛细胞和分泌细胞两种","上皮下结缔组织中有少量结缔组织和环行平滑肌","已开始具有气体交换的功能"],"a":2,"e":"呼吸性细支气管管壁开始出现肺泡，其上皮为单层立方上皮，而非假复层纤毛柱状上皮，故该项错误。其为终末细支气管的分支，一条终末细支气管分2～3条；属肺呼吸部；上皮下有少量结缔组织和环行平滑肌；已开始具气体交换功能，余项正确"},{"q":"分泌醛固酮的结构是","o":["肾上腺皮质网状带","肾上腺髓质嗜铬细胞","嫌色细胞","肾上腺皮质球状带","垂体细胞"],"a":3,"e":"肾上腺皮质球状带位于被膜下方，分泌盐皮质激素主要为醛固酮，作用于远曲小管和集合管促进钠重吸收与钾排出，故为肾上腺皮质球状带。网状带分泌雄激素；髓质嗜铬细胞分泌肾上腺素与去甲肾上腺素；嫌色细胞为垂体细胞；垂体细胞为神经胶质细胞"},{"q":"关于初级精母细胞的描述，错误的是","o":["位于精原细胞近腔侧","细胞大，核大而圆，染色质粗网状","染色体核型为46，XY","经两次分裂形成4个次级精母细胞","成熟分裂过程历时较长，故生精小管切面上易于见到"],"a":3,"e":"初级精母细胞经第一次减数分裂形成2个次级精母细胞，次级精母细胞再经第二次分裂形成4个精子细胞，故经两次分裂形成4个次级精母细胞错误。初级精母细胞位于精原细胞近腔侧，细胞大、核大染色质粗网状，核型46，XY，第一次减数分裂前期历时长故切片中易见，余项正确"},{"q":"关于视网膜色素上皮细胞描述，错误的是","o":["单层矮柱状细胞，基部附于玻璃膜","细胞顶部胞质突伸入视细胞之间","胞质内含有黑素颗粒和吞噬体","储存维生素A，参与视紫红质的合成","能感受强光，增强视锥细胞的功能"],"a":4,"e":"感受强光和颜色的是视锥细胞，色素上皮细胞无感光功能，其功能为保护视细胞、贮存维生素A、吞噬脱落膜盘并参与视紫红质再生，故该项错误。色素上皮为单层矮柱状、基部附于玻璃膜，顶部胞质突伸入视细胞之间，胞质含黑素颗粒和吞噬体，贮存维生素A参与视紫红质合成，余项正确"},{"q":"老花眼是由于","o":["角膜曲度改变","晶状体弹性减弱","玻璃体混浊","房水减少","房水过多"],"a":1,"e":"老年人晶状体弹性减退，睫状肌收缩时晶状体不能充分变凸，导致近距离视物不清，称老花眼，故为晶状体弹性减弱。角膜曲度改变导致散光；玻璃体混浊导致飞蚊症；房水减少或过多影响眼压，均与本病无关"},{"q":"从小肠吸收来的营养物质运输至肝细胞的途径为","o":["肝动脉→小叶间动脉→肝血窦→肝细胞","肝静脉→小叶间静脉→肝血窦→肝细胞","门静脉→小叶间静脉→肝血窦→肝细胞","门静脉→小叶下静脉→肝血窦→肝细胞","肝静脉→小叶下静脉→肝血窦→肝细胞"],"a":2,"e":"小肠吸收的营养物质经门静脉入肝，门静脉分支为小叶间静脉，血液注入肝血窦，与肝细胞充分进行物质交换，故途径为门静脉→小叶间静脉→肝血窦→肝细胞。肝动脉为肝提供氧气；肝静脉为血液流出通道；小叶下静脉汇集中央静脉血液，均非营养物质入肝途径"},{"q":"胸腺小体位于胸腺的","o":["皮质","皮质与髓质交界处","皮质和髓质","小叶间隔内","髓质"],"a":4,"e":"胸腺小体是胸腺髓质的特征性结构，由胸腺上皮细胞呈同心圆状排列而成，故位于髓质。皮质以胸腺细胞密集为特点；皮质与髓质交界处及小叶间隔内无胸腺小体；笼统称皮质和髓质亦不准确"},{"q":"内耳的内淋巴液来自","o":["脑脊液","组织液","骨膜内的毛细血管","血管纹","内淋巴囊"],"a":3,"e":"膜迷路腔内充满内淋巴，内淋巴由膜蜗管的血管纹产生，经内淋巴导管和内淋巴囊导入硬膜下隙，故内淋巴来自血管纹。脑脊液与组织液为外淋巴的来源相关；骨膜内毛细血管不产生内淋巴；内淋巴囊为引流结构而非产生部位"},{"q":"原始生殖细胞发生于","o":["尿囊内胚层","卵黄囊的胚外中胚层","未分化性腺的初级性索","生殖腺嵴的表面上皮","卵黄囊顶近尿囊处的内胚层"],"a":4,"e":"人胚第4周初，靠近尿囊根部的卵黄囊壁内胚层出现大而圆的原始生殖细胞，其沿后肠背系膜迁移至生殖嵴，故原始生殖细胞发生于卵黄囊顶近尿囊处的内胚层。尿囊内胚层与卵黄囊胚外中胚层均不产生该细胞；初级性索与生殖腺嵴表面上皮为迁移到达或参与形成的结构"},{"q":"神经元尼氏体是","o":["发出轴突的部位","合成蛋白质的场所","接受刺激的部位","轴突运输的载体","储存神经递质的结构"],"a":1,"e":"尼氏体由粗面内质网和游离核糖体构成，是神经元合成蛋白质的部位，主要合成更新细胞器所需结构蛋白、神经递质酶类和肽类神经调质，故为合成蛋白质的场所。发出轴突的部位为轴丘；接受刺激的部位为树突与胞体膜；轴突运输载体为微管；储存神经递质的是突触小泡"},{"q":"长骨骨干的间骨板位于","o":["骨单位与环骨板之间","骨单位中央","骨单位之间或骨单位与环骨板之间","外环骨板内","内环骨板"],"a":2,"e":"间骨板位于骨单位之间或骨单位与环骨板之间，为骨生长和重建过程中较早期的骨单位与环骨板的残留部分，故为该位置。骨单位中央为中央管；外环骨板内与内环骨板为环骨板本身；仅说骨单位与环骨板之间表述不完整"},{"q":"关于肾小体的滤过作用，下列哪项是错误的","o":["毛细血管球的内皮细胞有孔","基膜具有通透性","裂孔膜可通透分子量为70KD以下的物质","血管球，位于皮质迷路和髓放线内","入球小动脉短粗，出球小动脉细长，致使血管球内血压较高"],"a":3,"e":"肾小体（血管球）位于皮质迷路和肾柱内，而不在髓放线内，髓放线与肾锥体内为肾小管直行部分与集合管，故该项错误。毛细血管球内皮细胞有孔、基膜具通透性、裂孔膜可通透70KD以下物质、入球小动脉短粗而出球小动脉细长使球内血压较高，余项均正确"},{"q":"脊髓内分化为躯体运动神经元的成神经细胞位于","o":["基板","翼板","顶板","底板","基板和翼板之间"],"a":0,"e":"基板形成脊髓灰质前角，其中成神经细胞主要分化为躯体运动神经元，故位于基板。翼板形成后角，其成神经细胞分化为中间神经元；顶板与底板为连接板；基板和翼板之间形成侧角，其成神经细胞分化为内脏传出神经元"},{"q":"喉气管先天性狭窄或闭锁是由于","o":["平滑肌痉挛收缩","软骨环增生肥大","间质水肿压迫","甲状腺增生肥大压迫","管腔重建过程受阻"],"a":4,"e":"喉气管发生时曾出现上皮过度增生致管腔狭窄或闭锁，随后增生细胞凋亡、上皮变薄、管腔恢复正常，若这一管腔重建过程受阻则导致先天性狭窄或闭锁，故为管腔重建过程受阻。平滑肌痉挛、软骨环增生、间质水肿与甲状腺压迫均非先天性管道畸形的发生机制"},{"q":"关于子宫内膜，下列哪项错误","o":["内膜全层均有周期性脱落变化","其周期性变化受下丘脑分泌的激素影响","上皮中分泌细胞多于纤毛细胞","子宫腺也可有少量纤毛细胞","卵泡刺激素可通过影响卵巢功能进而影响子宫内膜周期性变化"],"a":0,"e":"子宫内膜分功能层和基底层，月经期仅功能层脱落，基底层不脱落并增生修复内膜，故内膜全层均有周期性脱落变化错误。周期性变化受下丘脑-垂体-卵巢轴激素影响，上皮中分泌细胞多于纤毛细胞，子宫腺可有少量纤毛细胞，卵泡刺激素通过影响卵巢功能进而影响内膜，余项正确"},{"q":"关于单卵双胎结果的描述，哪一项不可能","o":["均为男性","均为女性","性别各异","可能发生连体畸形","可能发生寄生胎"],"a":2,"e":"单卵双胎由一个受精卵发育而来，两个胎儿遗传基因完全相同，性别一致，故性别各异不可能。单卵双胎可均为男性或均为女性；分离不完全可发生连体畸形；两胎发育速度相差甚大可形成寄生胎"},{"q":"长骨骨干骨密质内的血管走行于","o":["中央管和骨小管内","中央管和穿通管内","穿通管和骨小管内","只在中央管内","骨小管内"],"a":1,"e":"骨单位中央管为细长管道，内有小血管与神经纤维穿行以提供营养；穿通管横向穿越环骨板并连接各中央管，亦含血管神经，故血管走行于中央管和穿通管内。骨小管内为骨细胞突起，无血管；仅中央管的表述遗漏穿通管"},{"q":"次级性索来自","o":["未分化性腺的表面上皮","初级性索","皮质索","脏壁中胚层","体壁中胚层"],"a":0,"e":"人胚第10周后卵巢发生过程中初级性索退化，未分化性腺表面上皮增生再次向间充质伸入，形成次级性索（又称皮质索），故次级性索来自未分化性腺的表面上皮。初级性索退化成为卵巢髓质；皮质索为其次级性索的别称而非来源；脏壁与体壁中胚层均非其来源"},{"q":"在心肌闰盘的纵向连接面上有","o":["紧密连接","中间连接","桥粒","缝隙连接","中间连接和桥粒"],"a":3,"e":"心肌闰盘纵向部分存在缝隙连接，便于细胞间化学信息交流和电冲动传导，使心房肌、心室肌同步舒缩，故纵向连接面上有缝隙连接。横位连接面有中间连接与桥粒起黏着作用；紧密连接主要见于上皮细胞，非闰盘纵向面的主要结构"},{"q":"淋巴结内发生细胞免疫应答时，结构明显增大的是","o":["浅层皮质","副皮质区","髓索","髓窦","毛细血管后微静脉"],"a":1,"e":"副皮质区为胸腺依赖区，含大量T细胞，细胞免疫应答时其细胞分裂相增多、区域范围迅速扩大，故结构明显增大的是副皮质区。浅层皮质含淋巴小结为B细胞区，体液免疫应答时增大；髓索与髓窦属髓质；毛细血管后微静脉为再循环通道，非应答增大区"},{"q":"化学突触内与神经冲动传递直接相关的结构是","o":["线粒体","微管","突触小泡","微丝","神经丝"],"a":2,"e":"突触前成分内的突触小泡含神经递质或神经调质，冲动到达时释放递质作用于突触后膜，是神经冲动传递的关键结构，故为突触小泡。线粒体供能；微管、微丝与神经丝为细胞骨架成分，参与小泡运输或维持形态，均非直接传递递质的结构"},{"q":"分泌具有抗恶性贫血的内因子的细胞是","o":["表面黏液细胞","颈黏液细胞","主细胞","壁细胞","Paneth细胞"],"a":3,"e":"胃底腺壁细胞分泌盐酸和内因子，内因子与维生素B12结合促进其在回肠吸收，壁细胞减少致内因子缺乏可引起恶性贫血，故为壁细胞。表面黏液细胞与颈黏液细胞分泌黏液；主细胞分泌胃蛋白酶原；Paneth细胞位于小肠腺分泌防御素等，均不分泌内因子"},{"q":"附睾管起源于","o":["中肾旁管","中肾管","生殖腺索","中肾小管","输尿管芽"],"a":1,"e":"睾丸形成后间质细胞分泌雄激素，促使中肾管延长弯曲形成附睾管、输精管、精囊和射精管，故附睾管起源于中肾管。中肾旁管在男性退化；生殖腺索形成睾丸索；中肾小管分化为输出小管；输尿管芽参与泌尿系统发生"},{"q":"肾上腺髓质的特征中哪项是错误的","o":["具有分泌类固醇激素细胞的超微结构特征","胞质中有许多嗜铬颗粒","细胞索互联成网，网孔中有窦状毛细血管","有少量交感神经节细胞分布","可分泌肾上腺素和去甲肾上腺素"],"a":0,"e":"肾上腺髓质嗜铬细胞分泌肾上腺素与去甲肾上腺素，属含氮激素分泌细胞，以粗面内质网、高尔基复合体和分泌颗粒为特征，而非类固醇激素分泌细胞的丰富滑面内质网，故该项错误。胞质含嗜铬颗粒，细胞索网孔中有窦状毛细血管，有少量交感神经节细胞，可分泌两种激素，余项正确"},{"q":"下列哪种细胞不是单核吞噬细胞系统的细胞成员","o":["血液内的单核细胞","神经组织的少突胶质细胞","结缔组织内的巨噬细胞","尘细胞","库普弗细胞"],"a":1,"e":"单核吞噬细胞系统包括单核细胞及其分化的巨噬细胞、破骨细胞、小胶质细胞、库普弗细胞、尘细胞等；少突胶质细胞为中枢神经系统髓鞘形成细胞，不属该系统，故为神经组织的少突胶质细胞。血液单核细胞、结缔组织巨噬细胞、尘细胞与库普弗细胞均属该系统"},{"q":"关于中耳的描述，哪项错误","o":["鼓室内表面有黏膜","听小骨表面无黏膜","听小骨之间有关节连接","咽鼓管近鼓室段的黏膜上皮为单层柱状","咽鼓管近鼻咽段的黏膜上皮为假复层纤毛柱状"],"a":1,"e":"鼓室内表面和3块听小骨表面均覆有薄层黏膜，故听小骨表面无黏膜错误。鼓室内表面有黏膜，听小骨间形成关节连接，咽鼓管近鼓室段上皮为单层柱状、近鼻咽段为假复层纤毛柱状，余项均正确"},{"q":"视杆细胞和视锥细胞共有的特征不包括","o":["属高度分化的感觉神经元","细胞分为胞体、内突和外突","外突和双极神经元形成突触","外节基部细胞膜内褶形成膜盘","膜盘上镶嵌有感光物质"],"a":2,"e":"视细胞的内突末端与双极神经元形成突触，而非外突；外突伸向色素上皮，分为内节与外节，外节膜盘含感光物质，故该项说法错误，不属于共有特征。视杆与视锥均属高度分化的感觉神经元，分胞体、内突、外突三部分，外节基部膜内褶形成膜盘，膜盘镶嵌感光物质，余项为共有特征"},{"q":"肾内可分泌肾素的细胞是","o":["球内系膜细胞","球旁细胞","球外系膜细胞","间质细胞","足细胞"],"a":1,"e":"球旁细胞为入球微动脉近血管极处平滑肌细胞分化的上皮样细胞，胞质内含肾素分泌颗粒，肾素释放入血参与血压与钠平衡调节，故为球旁细胞。球内系膜细胞有收缩与吞噬功能；球外系膜细胞位于血管球三角区中心；间质细胞分泌前列腺素等；足细胞构成裂孔膜参与滤过"},{"q":"视网膜视部的感光部位是","o":["视细胞所在的部位","视细胞内突所在的部位","视细胞胞体所在的部位","视细胞外突的内节所在的部位","视细胞外突的外节所在的部位"],"a":4,"e":"视细胞外突分内节和外节，外节含膜盘及感光物质（如视紫红质），是感受光线的部位，故感光部位为视细胞外突的外节所在的部位。内突为与双极细胞形成突触处，胞体含核，内节含线粒体等为外节供能，均非感光部位"},{"q":"在妊娠后期，乳汁内的初乳小体是","o":["乳蛋白凝块","吞噬脂滴的巨噬细胞","分泌抗体的浆细胞","脱落的导管上皮细胞","脱落的腺细胞"],"a":1,"e":"初乳中常含吞噬脂滴的巨噬细胞，称初乳小体，故为吞噬脂滴的巨噬细胞。乳蛋白凝块、脱落的导管上皮细胞或腺细胞均非初乳小体；浆细胞分泌抗体但本身不构成初乳小体"},{"q":"光镜下表皮颗粒层细胞嗜碱性，是因为含有大量","o":["游离核糖体","张力丝","板层颗粒","透明角质颗粒","角蛋白"],"a":3,"e":"颗粒层细胞质内含形状不规则、强嗜碱性的透明角质颗粒，故光镜下颗粒层呈嗜碱性。游离核糖体虽嗜碱性但非颗粒层特征性颗粒；张力丝即角蛋白丝；板层颗粒为含糖脂的膜被颗粒；角蛋白为角蛋白丝与均质物质的复合物，主要见于角质层，均非嗜碱性主因"},{"q":"有关单核细胞的描述，哪项错误","o":["是体积最大的血细胞","细胞核多呈肾形","胞质染成蓝灰色","胞质内无颗粒","在血流中停留12～48小时"],"a":3,"e":"单核细胞胞质内含许多细小的嗜天青颗粒（溶酶体），故胞质内无颗粒错误。单核细胞是体积最大的血细胞，核多呈肾形，胞质染成蓝灰色，在血流中停留12～48小时后进入组织分化为巨噬细胞，余项均正确"},{"q":"胎儿遗传性别的决定因素是","o":["受精前母体精神状态","参与受精的卵子性染色体","参与受精的精子性染色体","受精后激素作用","受精前环境作用"],"a":2,"e":"受精决定新个体遗传性别，带Y染色体的精子与卵结合发育为男性，带X染色体的精子与卵结合发育为女性，故遗传性别由参与受精的精子性染色体决定。卵子性染色体均为X；母体精神状态、受精后激素与受精前环境均不决定遗传性别"},{"q":"来源于尿生殖嵴内侧份的结构是","o":["尿生殖窦","生殖腺嵴","脊索","生肾索","尿生殖结节"],"a":1,"e":"尿生殖嵴分为外侧的中肾嵴和内侧的生殖嵴（生殖腺嵴），故来源于内侧份的是生殖腺嵴。尿生殖窦为泄殖腔分化结构；脊索来自中胚层轴部；生肾索增生形成尿生殖嵴，为更原始的结构；尿生殖结节为外生殖器原基"},{"q":"生精细胞中存在时间最短的是","o":["精原细胞","初级精母细胞","次级精母细胞","精子细胞","精子"],"a":2,"e":"次级精母细胞不进行DNA复制，迅速进入第二次减数分裂，存在时间短暂，生精小管切面中不易见到，是存在时间最短的生精细胞。精原细胞长期存在并增殖；初级精母细胞第一次减数分裂前期历时长；精子细胞需经变形，精子在附睾中成熟储存，均较其长"},{"q":"大脑皮质中的大锥体细胞主要位于","o":["外颗粒层","多形细胞层","内颗粒层","内锥体细胞层","外锥体细胞层"],"a":3,"e":"大脑皮质内锥体细胞层由大、中型锥体细胞组成，中央前回有巨大的贝兹细胞，故大锥体细胞主要位于内锥体细胞层。外颗粒层与内颗粒层以颗粒细胞为主；多形细胞层为梭形细胞等；外锥体细胞层为中、小型锥体细胞，均非大锥体细胞主要所在"},{"q":"锥体细胞分布于","o":["小脑皮质","大脑皮质","脊髓灰质","脊髓后角","脊髓前角"],"a":1,"e":"大脑皮质高尔基Ⅰ型神经元包括大、中型锥体细胞与梭形细胞，其轴突组成投射纤维或联合传出纤维，故锥体细胞分布于大脑皮质。小脑皮质传出神经元为浦肯野细胞；脊髓灰质前角为运动神经元、后角为中间神经元，均无锥体细胞"},{"q":"关于甲状腺的结构特征，哪项是错误的","o":["甲状腺滤泡主要由滤泡上皮细胞构成","上皮的高低与细胞功能状态密切相关","功能活跃时滤泡上皮细胞内粗面内质网丰富","甲状腺素储存在胞质的分泌颗粒中","滤泡腔内含嗜酸性的胶状物质"],"a":3,"e":"甲状腺球蛋白在粗面内质网和高尔基复合体合成加工后经胞吐排入滤泡腔贮存，甲状腺激素以碘化甲状腺球蛋白形式储存于滤泡腔胶质中，而非胞质分泌颗粒内，故该项错误。滤泡主要由滤泡上皮细胞构成，上皮高度与功能相关，功能活跃时粗面内质网丰富，滤泡腔含嗜酸性胶质，余项正确"},{"q":"关于主肺动脉隔的发育，哪项是错误的","o":["来自动脉干和心球的心内膜下组织","起初为一对纵行的嵴","以后左、右嵴在中线愈合，形成主肺动脉隔","主肺动脉隔垂直下行","将动脉干和心球分隔成肺动脉干和升主动脉"],"a":3,"e":"主肺动脉隔（主动脉肺动脉隔）呈螺旋状走行，将动脉干和心球分隔为肺动脉干和升主动脉；若呈直的间隔则导致主动脉与肺动脉错位，故垂直下行错误。其来自动脉干和心球的心内膜下组织，起初为一对纵行嵴，左右嵴中线愈合形成隔，完成分隔，余项正确"},{"q":"神经嵴不分化为","o":["脑神经节","神经垂体","周围神经","肾上腺髓质","脊神经节"],"a":1,"e":"神经外胚层先形成神经管和神经嵴，神经管分化为中枢神经系统、神经垂体与松果体等，神经嵴分化为周围神经系统（神经节、周围神经）与肾上腺髓质等，故神经垂体来自神经管，神经嵴不分化为神经垂体。脑神经节、脊神经节、周围神经与肾上腺髓质均由神经嵴分化"},{"q":"对血细胞发生的描述，哪项错误","o":["血细胞发生大致分为原始阶段、幼稚阶段和成熟阶段","红、粒系的幼稚阶段又可分为早、中、晚三阶段","红、粒系，单核和巨核细胞系的幼稚阶段也分为早、中、晚三阶段","单核和巨核细胞的幼稚阶段不分早、中、晚三阶段","单核经幼单核、单核，进一步分化为巨噬细胞"],"a":2,"e":"各种血细胞发生分原始、幼稚、成熟三阶段，其中红系与粒系的幼稚阶段又分早、中、晚三期，而单核细胞与巨核细胞的幼稚阶段不分早中晚，故该项描述错误，与单核和巨核幼稚阶段不分期相矛盾。血细胞发生分三阶段、红粒系分早中晚、单核经幼单核与单核分化为巨噬细胞，余项正确"},{"q":"构成神经原纤维的是","o":["神经丝和微丝","微管和微丝","神经丝和张力丝","神经丝和微管","微管和张力丝"],"a":3,"e":"神经原纤维在电镜下由神经丝和微管构成，神经丝由神经丝蛋白构成属中间丝，微管由微管相关蛋白2构成，镀银染色下呈棕黑色细丝，故为神经丝和微管。张力丝为上皮细胞内角蛋白丝；微丝参与细胞骨架但非神经原纤维的主要成分"},{"q":"关于骨单位的特点，下列哪项错误","o":["多层骨板环绕中央管作同心圆排列","骨单位中央管之间有穿通管相互连通","中央管内无血管及神经","中央管内衬有骨膜","骨单位顺骨干长轴作纵向排列"],"a":2,"e":"骨单位中央管为细长管道，内有小血管与神经纤维穿行以提供营养，故中央管内无血管及神经错误。骨单位由多层骨板环绕中央管同心圆排列，中央管间有穿通管连通，管内衬骨膜，骨单位顺骨干长轴纵向排列，余项均正确"},{"q":"关于呼吸道上皮内分泌细胞，哪项错误","o":["属于APUD系统","分泌5-羟色胺","矮柱状，基部胞质内含分泌颗粒","参与神经上皮小体的构成","分泌物必须通过血循环发挥作用"],"a":4,"e":"呼吸道内分泌细胞属DNES/APUD系统，其分泌物有的经血流作用于远处靶细胞，有的直接作用于邻近细胞（旁分泌），并非必须通过血循环，故该项错误。其属APUD系统，可分泌5-羟色胺，矮柱状且基部胞质含分泌颗粒，参与神经上皮小体构成，余项正确"},{"q":"在神经元的胞体、轴突、树突内均存在的结构是","o":["神经原纤维","高尔基复合体","粗面内质网","中心体","核糖体"],"a":0,"e":"神经原纤维由神经丝和微管构成，分布于神经元胞体并伸入树突与轴突，在三者内均存在，故为神经原纤维。高尔基复合体、粗面内质网与核糖体主要位于胞体和树突，轴突内无粗面内质网与核糖体；中心体存在于胞体，成熟神经元突起内无"},{"q":"角膜基质来源于","o":["神经嵴","间充质","神经外胚层","视杯口边缘部的间充质","表面外胚层"],"a":1,"e":"在晶状体泡诱导下，表面外胚层分化为角膜上皮，角膜上皮后面的间充质分化为角膜其余各层（包括基质层），故角膜基质来源于间充质。神经嵴为部分面部间充质的来源，但角膜基质直接来自间充质；神经外胚层形成神经组织；视杯口边缘部间充质形成虹膜基质与睫状体；表面外胚层形成角膜上皮"},{"q":"电镜下，纹状管单层高柱状上皮细胞基部具有","o":["丰富的分泌颗粒","发达的质膜内褶和线粒体","滑面内质网","粗面内质网和核糖体","溶酶体"],"a":1,"e":"纹状管为单层高柱状上皮，细胞基部可见垂直纵纹，电镜下为发达的质膜内褶和纵行排列的线粒体，可扩大基底部表面积以利水和电解质转运，故为发达的质膜内褶和线粒体。分泌颗粒位于细胞顶部；滑面内质网、粗面内质网与核糖体、溶酶体均非基部纵纹的结构基础"},{"q":"肝小叶内产生网状纤维的细胞是","o":["肝巨噬细胞","血窦内皮细胞","肝细胞","贮脂细胞","大颗粒淋巴细胞"],"a":3,"e":"贮脂细胞位于窦周隙，参与维生素A代谢和贮存脂肪，病理条件下被激活后产生细胞外基质（含网状纤维、胶原纤维），致肝内纤维增多甚至肝硬化，故为贮脂细胞。肝巨噬细胞主司吞噬，血窦内皮细胞参与滤过，肝细胞合成胆汁和血浆蛋白，大颗粒淋巴细胞为免疫细胞，均非产生网状纤维者"},{"q":"形成小脑的平行纤维的是","o":["高尔基细胞的树突","浦肯野细胞的轴突","篮状细胞的轴突","星形细胞的树突","颗粒细胞的轴突"],"a":4,"e":"小脑颗粒细胞轴突上行进入分子层后呈T形分支，与小脑叶片长轴平行，称平行纤维，垂直穿过浦肯野细胞扇形树突并与其树突棘形成突触，故平行纤维由颗粒细胞轴突形成。高尔基细胞树突、篮状细胞轴突与星形细胞树突为抑制性中间神经元突起；浦肯野细胞轴突为小脑唯一传出纤维"},{"q":"周围神经系统有髓神经纤维的髓鞘形成细胞是","o":["星形胶质细胞","施万细胞","小胶质细胞","卫星细胞","少突胶质细胞"],"a":1,"e":"周围神经系统有髓神经纤维的髓鞘由施万细胞膜反复卷绕轴突形成，施万细胞一个接一个套在轴突外，故为施万细胞。少突胶质细胞为中枢神经系统有髓纤维的髓鞘形成细胞；星形胶质细胞与小胶质细胞为中枢神经胶质；卫星细胞包绕神经节神经元胞体，均不形成周围神经髓鞘"},{"q":"分泌甲状旁腺激素的细胞是","o":["主细胞","嗜碱性细胞","滤泡旁细胞","滤泡上皮细胞","嗜酸性细胞"],"a":0,"e":"甲状旁腺主细胞分泌甲状旁腺激素，作用于骨细胞和破骨细胞使骨盐溶解，并促进肠及肾小管吸收钙使血钙升高。嗜碱性细胞为垂体远侧部细胞；滤泡旁细胞分泌降钙素；滤泡上皮细胞分泌甲状腺激素；嗜酸性细胞为甲状旁腺内功能不明细胞"},{"q":"关于子宫颈的结构和功能特点，错误的是","o":["黏膜上皮为单层柱状","外口处上皮移行为变移上皮","上皮移行处是宫颈癌的好发部位","黏膜的分泌受卵巢激素的影响","妊娠时分泌物黏稠，可阻止微生物进入子宫"],"a":1,"e":"宫颈外口处为单层柱状上皮与复层扁平上皮的移行区，是宫颈癌好发部位，而非移行为变移上皮，故该项错误。黏膜上皮为单层柱状，移行处是宫颈癌好发部位，黏膜的分泌受卵巢激素影响，妊娠时分泌物黏稠可阻止微生物进入子宫，余项正确"},{"q":"表皮中的哪种细胞来源于血液中的单核细胞","o":["基底细胞","黑素细胞","胶质细胞","梅克尔细胞","朗格汉斯细胞"],"a":4,"e":"朗格汉斯细胞来源于骨髓造血干细胞（单核细胞/树突状细胞系），散在于棘层浅部，为抗原呈递细胞，故来源于血液单核细胞的是朗格汉斯细胞。基底细胞为表皮干细胞来自外胚层；黑素细胞与梅克尔细胞来自神经嵴；胶质细胞为神经胶质，均非单核细胞来源"},{"q":"胞质易染色颗粒中含有白三烯的细胞是","o":["巨噬细胞","嗜酸性粒细胞","淋巴细胞","肥大细胞","中性粒细胞"],"a":3,"e":"肥大细胞胞质颗粒含组胺、肝素等，受刺激脱颗粒并合成释放白三烯，参与荨麻疹、哮喘与休克等过敏反应，故为肥大细胞。巨噬细胞主司吞噬；嗜酸性粒细胞颗粒含组胺酶与芳基硫酸酯酶，可分解白三烯；淋巴细胞与中性粒细胞均非白三烯主要来源"},{"q":"人胚发育过程中，能根据外生殖器分辨性别是在","o":["第6周","第7周","第12周","第4个月","第5个月"],"a":2,"e":"人类遗传性别在受精时由精子核型确定，生殖腺到第7周才能辨认性别，外生殖器的性别到第12周时才可分辨，故为第12周。第6周过早，第7周为生殖腺可辨性别而非外生殖器，第4个月与第5个月均过晚"},{"q":"形成精子顶体的细胞器是","o":["中心体","核糖体","线粒体","滑面内质网","高尔基复合体"],"a":4,"e":"精子形成过程中，高尔基复合体形成顶体，覆盖于细胞核一端并含顶体酶以助力受精，故为高尔基复合体。中心体迁移至核另一端并形成轴丝构成尾部；线粒体聚集形成线粒体鞘；核糖体合成蛋白质；滑面内质网不参与顶体形成"},{"q":"抗利尿激素从何处释放入血","o":["视上核","室旁核","垂体神经部","垂体远侧部","垂体漏斗部"],"a":2,"e":"下丘脑视上核与室旁核合成抗利尿激素（血管升压素）和催产素，经轴突运输至垂体神经部贮存并释放入血，故从垂体神经部释放入血。视上核与室旁核为合成部位而非释放入血处；垂体远侧部为腺垂体；漏斗部为轴突经过部位"},{"q":"下列哪项不是血管纹的特点","o":["为复层上皮","含有血管","位于椭圆囊外侧壁","覆盖于螺旋韧带表面","能产生内淋巴"],"a":2,"e":"血管纹位于膜蜗管外侧壁，为含毛细血管的复层上皮，覆盖于螺旋韧带表面，能产生内淋巴，故位于椭圆囊外侧壁错误，椭圆囊壁无血管纹。复层上皮、含血管、覆盖螺旋韧带表面及产生内淋巴均为血管纹的特点"},{"q":"关于骨骼肌纤维的光镜结构，哪项是错误的","o":["为细长圆柱形的细胞","有多个细胞核","肌原纤维顺肌纤维的长轴平行排列","细胞核位于肌纤维中央","肌原纤维有明暗相间的横纹"],"a":3,"e":"骨骼肌纤维为多核细胞，核呈扁椭圆形，位于肌膜下方，而非肌纤维中央；核位于中央是心肌纤维的特点，故该项错误。骨骼肌纤维呈细长圆柱形、多核、肌原纤维顺长轴平行排列并有明暗相间横纹，余项均正确"},{"q":"淋巴组织最丰富的部位是","o":["结肠","回肠","空肠","食管","胃幽门部"],"a":1,"e":"回肠固有层与黏膜下层内许多淋巴小结聚集形成集合淋巴小结，是消化管淋巴组织最丰富的部位之一，故为回肠。结肠与空肠淋巴组织较少；食管与胃幽门部仅有少量弥散淋巴组织，均不如回肠丰富"},{"q":"下列关于隐睾的描述中，哪一项是错误的","o":["睾丸可停留在腹股沟管内","睾丸可停留在腹腔内","双侧隐睾可造成不育症","常影响间质细胞的雄激素分泌","出生后1年内仍可降入阴囊"],"a":3,"e":"隐睾主要是睾丸下降受阻，可停留在腹腔或腹股沟管内，双侧隐睾因温度影响生精可致不育，但一般不影响间质细胞分泌雄激素，故该项错误。睾丸可停留腹股沟管与腹腔、双侧可致不育、出生后1年内仍可降入阴囊，余项均正确"},{"q":"浆液性腺细胞的结构特点不包括","o":["细胞核扁平，贴于细胞基底面","基底部胞质嗜碱性","细胞顶部含分泌颗粒","细胞核上区有发达的高尔基复合体","细胞基底部含丰富的粗面内质网"],"a":0,"e":"浆液性腺细胞呈锥形或柱状，核圆形位于细胞中下部，基部胞质嗜碱性富含粗面内质网，核上区有发达高尔基复合体，顶部含分泌颗粒；核扁平贴于基底面且核上方充满黏原颗粒为黏液性腺细胞特点，故该项不包括。其余各项均为浆液性腺细胞的结构特点"},{"q":"关于人耳蜗的描述，哪项错误","o":["蜗轴为锥体形，为骨性结构","蜗轴内含螺旋神经节","骨蜗管围绕蜗轴盘旋2周半","骨蜗管自上而下分依次为前庭阶、鼓室阶和膜蜗管","前庭阶和鼓室阶在蜗顶经蜗孔相通"],"a":3,"e":"骨蜗管被膜蜗管分隔为上下两部分，上为前庭阶、下为鼓室阶，膜蜗管为独立的螺旋形膜性管道，并非骨蜗管自上而下的第三部分，故该项归属与排列均错误。蜗轴为锥体形骨性结构且内含螺旋神经节，骨蜗管盘旋2周半，前庭阶与鼓室阶在蜗顶经蜗孔相通，余项正确"},{"q":"气管黏膜表面产生sIgA的细胞是","o":["上皮细胞和浆细胞","上皮细胞和巨噬细胞","内分泌细胞","纤毛细胞和克拉拉细胞","巨噬细胞和克拉拉细胞"],"a":0,"e":"浆细胞主要产生IgA，与上皮细胞（吸收细胞）基底面膜中的分泌片结合形成分泌型IgA，经内吞释放入黏膜腔发挥免疫作用，故气管黏膜产生sIgA的为上皮细胞和浆细胞。巨噬细胞主司吞噬；内分泌细胞分泌激素；纤毛细胞摆动排痰、克拉拉细胞分泌表面活性物质，均不产生sIgA"},{"q":"关于甲状腺素的形成，哪项错误","o":["滤泡上皮细胞自血中摄取氨基酸","在溶酶体内水解成T3、T4后释放入血","摄入的碘与甲状腺球蛋白在细胞内结合成碘化甲状腺球蛋白","分泌颗粒以胞吐方式入滤泡腔贮存","甲状腺球蛋白在粗面内质网和高尔基复合体合成加工"],"a":2,"e":"滤泡上皮细胞摄入的碘离子经氧化物酶活化后进入滤泡腔，在滤泡腔内与甲状腺球蛋白结合形成碘化甲状腺球蛋白，而非在细胞内结合，故该项错误。细胞自血中摄取氨基酸，在溶酶体内水解T3、T4释放入血，分泌颗粒胞吐入滤泡腔贮存，甲状腺球蛋白在粗面内质网和高尔基复合体合成加工，余项正确"},{"q":"关于心肌纤维，哪一项是错误的","o":["单核，有的肌纤维可见双核","肌纤维短圆柱状","有不明显的横纹","肌纤维分支吻合成网","细胞核位于肌膜下"],"a":4,"e":"心肌纤维核呈卵圆形，位于细胞中央，单核或偶见双核；核位于肌膜下是骨骼肌纤维特点，故该项错误。心肌纤维呈短圆柱状并有分支吻合成网，横纹不明显，余项均正确"},{"q":"具有很强分裂能力的细胞是","o":["黑素细胞","梅克尔细胞","基底细胞","棘细胞","朗格汉斯细胞"],"a":2,"e":"基底细胞为表皮的干细胞，位于基底层，具有很强的分裂增殖能力，不断产生新细胞并向浅层推移分化为棘层等各层，故为基底细胞。黑素细胞、梅克尔细胞与朗格汉斯细胞为已分化的非角质形成细胞，无强分裂能力；棘细胞进入棘层后即失去分裂能力"},{"q":"眼最重要的屈光结构是","o":["角膜","房水","晶状体","玻璃体","黄斑"],"a":2,"e":"晶状体为有弹性的双凸透明体，是眼球中最重要的屈光装置，充当生物透镜，其曲度可调以改变屈光力，故为晶状体。角膜为屈光系统组成部分但屈光力固定；房水与玻璃体主要起透明和维持眼压作用；黄斑为视网膜感光敏锐区，非屈光结构"},{"q":"关于间质细胞的描述，哪项是错误的","o":["位于睾丸纵隔内","常成群分布","具有分泌类固醇激素细胞的超微结构特点","体积较大，圆形或立方形","胞质嗜酸性"],"a":0,"e":"睾丸间质细胞位于生精小管之间的疏松结缔组织（睾丸间质）内，常成群分布，而非位于睾丸纵隔内（纵隔内为睾丸网），故该项错误。间质细胞成群分布，具类固醇激素分泌细胞超微结构特点，体积大呈圆形或立方形，胞质嗜酸性，余项正确"},{"q":"肺的呼吸部指","o":["终末细支气管及以下分支至肺泡","呼吸性细支气管及以下分支至肺泡","肺泡管及以下分支至肺泡","细支气管及以下分支至肺泡","全部肺泡"],"a":1,"e":"肺实质从叶支气管到终末细支气管为导气部，呼吸性细支气管以下各段因管壁出现肺泡而具气体交换功能，为呼吸部，包括呼吸性细支气管、肺泡管、肺泡囊和肺泡，故为呼吸性细支气管及以下分支至肺泡。终末细支气管以下含导气部末端；肺泡管以下与全部肺泡范围不全；细支气管以下含导气部"},{"q":"下列哪种细胞是抗原提呈细胞","o":["中性粒细胞","郎格汉斯细胞","浆细胞","网状细胞","嗜酸性粒细胞"],"a":1,"e":"郎格汉斯细胞能捕获皮肤抗原，处理后形成抗原肽-MHC分子复合物分布于细胞表面，随淋巴迁至淋巴结将抗原呈递给T细胞，是一种抗原呈递细胞，故为郎格汉斯细胞。中性粒细胞与嗜酸性粒细胞为吞噬细胞；浆细胞分泌抗体；网状细胞为支架细胞，均非抗原提呈细胞"},{"q":"原始卵泡来源于","o":["尿生殖窦","中肾小管","中肾旁管","次级性索","生殖腺嵴"],"a":3,"e":"卵巢发生时未分化性腺表面上皮增生形成次级性索（皮质索），其细胞团逐渐包绕原始生殖细胞形成原始卵泡，故原始卵泡来源于次级性索。尿生殖窦、中肾小管与中肾旁管为泌尿生殖管道来源；生殖腺嵴为性腺原基，非原始卵泡的直接来源"},{"q":"生精细胞逐批同步发育的基础是","o":["缝隙连接","桥粒","紧密连接","胞质桥","细胞间桥"],"a":3,"e":"一个精原细胞增殖分化所产生的各级生精细胞之间由细胞质桥相连，形成同步发育的同源细胞群，利于细胞间信息传递并保证同步发育，故基础是胞质桥。缝隙连接、桥粒与紧密连接为一般细胞连接，非生精细胞同步发育的结构；细胞间桥为干扰表述，教材术语为细胞质桥"},{"q":"淋巴结内的毛细血管后微静脉主要分布于","o":["浅层皮质","副皮质区","淋巴小结","髓窦","髓索"],"a":1,"e":"淋巴结副皮质区有许多高内皮微静脉（毛细血管后微静脉），约一成淋巴细胞穿越其内皮进入副皮质区，是淋巴细胞再循环的重要部位，故主要分布于副皮质区。浅层皮质与淋巴小结为B细胞区；髓窦与髓索属髓质，均非其主要分布区"},{"q":"胎儿血液循环中含氧量最高的血液位于","o":["主动脉","肺动脉","肺静脉","脐动脉","脐静脉"],"a":4,"e":"来自胎盘富含氧和营养物质的血液经脐静脉进入胚体，故脐静脉是胎儿循环中含氧量最高的血管。肺动脉内为右心室静脉血；脐动脉将含氧最低的血液送回胎盘；主动脉内为混合血；胎儿期肺循环血量少，肺静脉含氧不及脐静脉"},{"q":"上皮组织的主要结构特点是","o":["细胞多，细胞间质少","有丰富的毛细血管","分为单层、复层两类","感觉神经末梢少见","组成的细胞无序排布"],"a":0,"e":"上皮组织由密集排列的细胞组成，细胞多、细胞间质少，细胞间以连接结构相连形成连续细胞层，故主要结构特点为细胞多、细胞间质少。上皮内一般无血管；分单层、复层及变移等类型，仅说两类不全面；感觉神经末梢丰富而非少见；细胞排列规则有序而非无序"},{"q":"关于心肌纤维的叙述，错误的是","o":["心肌纤维呈短圆柱状，有分支并互相连接成网","心肌纤维纵切面上可见横纹，但不如骨骼肌的明显","心肌纤维之间有丰富的毛细血管","新生儿心肌纤维内的脂褐素含量更多","闰盘在HE染色的标本中呈着色较深的阶梯状粗线"],"a":3,"e":"心肌纤维核周围胞质内的脂褐素随年龄增长而增多，老年人心肌脂褐素含量更多，新生儿含量少，故该项错误。心肌纤维呈短圆柱状有分支并连接成网，纵切面横纹不如骨骼肌明显，间质有丰富毛细血管，闰盘在HE染色标本中呈着色较深的阶梯状粗线，余项正确"},{"q":"脂肪组织主要由大量密集的脂肪细胞构成，根据脂肪细胞结构和功能的不同，脂肪组织分为黄色和棕色脂肪组织。有关黄色脂肪组织的描述，哪一项错误","o":["为通常所说的脂肪组织","在人呈黄色，在某些哺乳动物呈白色","由大量多泡脂肪细胞聚集而成","见于皮下组织、网膜和肠系膜等处","具有储存脂肪和维持体温等作用"],"a":2,"e":"黄色脂肪组织即通常所说的脂肪组织，由大量单泡脂肪细胞聚集而成，分布于皮下、网膜和系膜，是体内最大贮能库并维持体温。多泡脂肪细胞是棕色脂肪组织的特征，其胞质含多个脂滴、线粒体丰富，以产热为主，C项把它误置于黄色脂肪组织；B项颜色、D项分布、E项贮能保温均符合黄色脂肪组织"},{"q":"下列哪项共同超微结构特点与软骨细胞和成骨细胞合成基质和纤维的功能相适应","o":["粗面内质网丰富，高尔基复合体发达","线粒体和粗面内质网丰富","滑面内质网和管状嵴线粒体丰富","含有较多的溶酶体、吞饮小泡和吞噬体","含有较多的脂滴"],"a":0,"e":"软骨细胞和成骨细胞均合成、分泌蛋白质类基质与纤维，故胞质内粗面内质网密集、高尔基复合体发达，属蛋白质分泌细胞的超微结构特征。B项线粒体与粗面内质网丰富无此特异组合；C项滑面内质网和管状嵴线粒体是类固醇激素分泌细胞特点；D项大量溶酶体、吞噬体是巨噬细胞或破骨细胞的特征"},{"q":"对于成纤维细胞的描述，哪项不正确","o":["是疏松结缔组织的主要细胞","细胞呈扁平、多突起","细胞核，较大，核仁明显","细胞质较丰富，呈弱嗜酸性","富含粗面内质网和发达的高尔基复合体"],"a":3,"e":"成纤维细胞是疏松结缔组织主要细胞，光镜下扁平多突起，核大卵圆、着色浅、核仁明显，胞质丰富呈弱嗜碱性，电镜下粗面内质网丰富、高尔基复合体发达。弱嗜酸性实为纤维细胞的特点，D项与成纤维细胞实际染色性相反；A、B、C、E各处描述均与成纤维细胞的形态和超微结构相符"},{"q":"消化吸收的重要部位是","o":["绒毛表面的黏液","微绒毛表面的细胞衣","吸收细胞的细胞内小管","吸收细胞之间的间隙","吸收细胞之间的连接复合体"],"a":1,"e":"小肠吸收细胞游离面微绒毛表面的细胞衣含双糖酶、肽酶及吸附的胰酶，是食物消化的关键部位，微绒毛又使表面积扩大约20倍。A项黏液主司润滑保护；C项细胞内小管参与吸收后转运而非消化；D项细胞间隙是物质旁路途径；E项连接复合体起封闭屏障作用，均不承担消化功能"},{"q":"没有细胞核也没有细胞器的是","o":["红细胞","血小板","间充质细胞","脂肪细胞","网织红细胞"],"a":0,"e":"成熟红细胞无细胞核也无任何细胞器，胞质充满血红蛋白，依靠无氧糖酵解供能，故不能合成新蛋白与酶。网织红细胞虽已脱核，仍残留少量核糖体等结构；血小板是巨核细胞脱落的胞质小块，无核但含颗粒与细胞器；间充质细胞和脂肪细胞均为完整细胞，有核及细胞器"},{"q":"抗利尿激素和醛固酮的作用部位是","o":["近端小管和远端小管","髓袢","远端小管和集合管","髓袢和集合管","近端小管和髓袢"],"a":2,"e":"醛固酮促进远曲小管和集合管重吸收Na⁺、排出K⁺，抗利尿激素促进此二段对水的重吸收使尿液浓缩，二者作用部位一致。近端小管重吸收大部分水钠但不依赖此二激素，髓袢主要参与髓质渗透梯度建立，A、B、D、E所列组合把激素靶段前移或错配"},{"q":"关于浆细胞的描述，哪项正确","o":["细胞形态多样，可伸出突起","细胞核圆形，位于细胞中央","核内异染色质呈辐射状分布","胞质内有丰富的滑面内质网","胞质中充满异染性颗粒"],"a":2,"e":"浆细胞呈卵圆形，核圆多偏于细胞一侧，异染色质粗条块状自核中心向核膜呈辐射状分布，胞质富含粗面内质网，核旁浅染区为高尔基复合体所在。B项细胞核居中属未极化细胞；D项滑面内质网丰富见于类固醇分泌细胞；E项异染性颗粒是肥大细胞的特征，A、B、D、E均不符合浆细胞"},{"q":"下列哪个结构不分布在髓放线内","o":["集合管","近端小管直部","远端小管直部","细段","乳头管"],"a":4,"e":"髓放线内走行直集合管、近端小管直部、远端小管直部及细段，弓形集合管亦由皮质迷路弯入其中。乳头管是直集合管在肾乳头处的改称，位于肾锥体深部并开口于肾小盏，不在髓放线范围内；把乳头管归入髓放线，混淆了皮质与髓质的分界"},{"q":"生精上皮的组成是","o":["支持细胞和生精细胞","肌样细胞和生精细胞","支持细胞，肌样细胞和精原细胞","支持细胞和肌样细胞","生精细胞和间质细胞"],"a":0,"e":"生精小管由生精上皮构成，生精上皮由支持细胞和5～8层生精细胞组成，后者自基底至腔面依次为精原细胞、初级精母细胞、次级精母细胞、精子细胞与精子。肌样细胞位于生精小管界膜，属管壁成分而非上皮；间质细胞位于睾丸间质分泌雄激素，B、C、D、E混淆了上皮与间质或管壁的归属"},{"q":"中肠袢在人胚胎发育演变中共逆时针旋转","o":["90°","120°","180°","270°","360°"],"a":3,"e":"中肠袢在脐腔内以肠系膜上动脉为轴逆时针旋转90°，由矢状位转为水平位；退回腹腔过程中继续逆时针旋转180°，两次合计270°。胃沿纵轴顺时针旋转90°属消化道另一段事件，120°、180°单次、360°等数值与胚胎肠袢的实际旋转过程不符"},{"q":"不属于角膜特征的是","o":["分角膜上皮、前界层、角膜基质、后界层和角膜内皮5层","富含感觉神经末梢","毛细血管丰富","角膜上皮再生能力强","前界层损伤后不能再生"],"a":2,"e":"角膜是透明无血管的组织，营养来自房水及角膜缘血管网，故毛细血管丰富不属于角膜特征。角膜由上皮、前界层、基质、后界层和内皮5层构成，含丰富感觉神经末梢，上皮再生能力强，前界层损伤后不能再生，A、B、D、E均为角膜的正确描述"},{"q":"下列哪种神经元不是多极神经元","o":["运动神经元","大脑锥体细胞","中间神经元","脊神经节的节细胞","自主神经节的节细胞"],"a":3,"e":"脊神经节属感觉神经节，其节细胞绝大部分为假单极神经元，胞体发出一个突起呈T形分叉，故不属于多极神经元。运动神经元、大脑锥体细胞、中间神经元及自主神经节内的节细胞均为多极神经元，具有多个树突和一个轴突"},{"q":"关于破骨细胞的结构与功能，下列哪项错误","o":["只溶解骨质而不能吸收骨质","有2～50个核","来源于单核细胞","位于骨质的表面","胞质内含大量溶酶体"],"a":0,"e":"破骨细胞由单核细胞融合而成，含2～50个核，贴附于骨质表面，胞质含大量溶酶体，释放水解酶和有机酸溶解骨盐、分解有机成分，并将溶解物内吞降解，故既溶解又吸收骨质。只溶解不吸收的说法与其皱褶缘和吞饮泡的功能相悖；B、C、D、E关于核数、来源、位置和溶酶体的描述均正确"},{"q":"一个肺小叶的组成是","o":["一个终末细支气管及其分支和肺泡","一个细支气管及其分支和肺泡","一个呼吸性细支气管及其分支和肺泡","一个小支气管及其分支和肺泡","一个主支气管及其分支和肺泡"],"a":1,"e":"每一细支气管连同其各级分支及所属肺泡组成一个肺小叶，呈锥形，尖向肺门、底向肺表面，是肺的结构单位，小叶性肺炎即累及若干肺小叶。终末细支气管和呼吸性细支气管只是导气部与呼吸部的分级，小支气管、主支气管管径更大，以其为起点划分小叶均不符合定义"},{"q":"骨基质中的有机质不包括","o":["以羟基磷灰石结晶存在的骨盐","胶原纤维","蛋白聚糖","骨钙蛋白","骨粘连蛋白"],"a":0,"e":"骨基质有机质主要由Ⅰ型胶原纤维、蛋白聚糖及骨钙蛋白、骨粘连蛋白等非胶原蛋白构成。羟基磷灰石结晶是骨盐的存在形式，属无机成分，占干骨重量约65%，故不属于有机质；B、C、D、E均为有机质成分，把骨盐列入有机质即混淆了有机与无机的分界"},{"q":"球旁细胞由下列哪种成分演变而成","o":["出球微动脉的内皮细胞","入球微动脉的内皮细胞","近曲小管上皮细胞","球外系膜细胞","近血管球处入球微动脉的平滑肌细胞"],"a":4,"e":"入球微动脉行至近肾小体血管极处，管壁中膜平滑肌细胞分化为上皮样细胞，即球旁细胞，内含分泌肾素的颗粒。出球微动脉内皮与近曲小管上皮均不参与其形成；球外系膜细胞位于血管极三角区中心，与球旁细胞相邻但来源不同，D项即为易混点"},{"q":"关于胆汁正确的是","o":["进食后胆管括约肌收缩利于胆汁在胆囊内的浓缩","交感神经兴奋促使胆囊肌收缩","胆管上皮能通过吸收胆汁中的水和无机盐而浓缩胆汁","胃大部切除患者由于迷走神经兴奋易发生胆石症","Oddi括约肌功能紊乱可导致胰腺炎或肝功能异常"],"a":4,"e":"Oddi括约肌位于胆总管与胰管开口处，其痉挛或紊乱使胆汁胰液排出受阻，反流可引发胰腺炎，胆汁淤积则损害肝功能。进食后该括约肌应舒张而非收缩；迷走神经兴奋促胆囊收缩，交感兴奋使其舒张；浓缩胆汁的是胆囊上皮而非胆管上皮；胃大部切除后胆石症与迷走神经切断有关，A、B、C、D均错"},{"q":"胰腺的泡心细胞是一种","o":["内分泌细胞","腺泡细胞","导管的上皮细胞","未分化细胞","从血管渗出的白细胞"],"a":2,"e":"泡心细胞是伸入胰腺腺泡腔内的闰管起始部上皮细胞，细胞扁平或立方形，胞质染色淡，故属导管上皮而非腺实质细胞。腺泡细胞呈锥体形、顶部含酶原颗粒；内分泌细胞散在于胰岛；未分化细胞和渗出白细胞均不构成泡心细胞，A、B、D、E的归属均不成立"},{"q":"关于真皮的网织层，正确的是","o":["为致密结缔组织","与表皮相邻接","形成许多真皮乳头以增加与表皮的接触面","含有触觉小体","不含神经末梢器"],"a":0,"e":"真皮网织层位于乳头层深面，由致密结缔组织构成，胶原纤维束粗大交织排列，含较多神经末梢器。与表皮相邻接并形成真皮乳头、含触觉小体的是乳头层，其为疏松结缔组织；网织层含环层小体等神经末梢，E项称不含神经末梢器与事实相反"},{"q":"睾丸间质细胞来源于","o":["生殖腺嵴的间充质","次级性索","初级性索","中肾管","中肾旁管"],"a":0,"e":"睾丸索之间的间充质细胞在胚胎第8周分化为睾丸间质细胞，位于生精小管之间，分泌雄激素。初级性索上皮细胞演变为支持细胞，原始生殖细胞分化为精原细胞，二者来源均不同；中肾管与中肾旁管分别演化为男、女生殖管道，B、C、D、E均非间质细胞来源"},{"q":"在肾内的动脉分布中，发自叶间动脉的是","o":["弓形动脉","直小动脉","入球微动脉","出球微动脉","小叶间动脉"],"a":0,"e":"肾动脉入肾后分支为叶间动脉，在肾柱内上行至皮质与髓质交界处横向分支为弓形动脉，弓形动脉再分出小叶间动脉进入皮质迷路。入球微动脉、出球微动脉位于肾小体血管极，直小动脉伴髓袢下行，均不直接发自叶间动脉，B、C、D、E的层级关系错位"},{"q":"子宫内膜处于分泌期时，卵巢内","o":["即将排卵","黄体生长","黄体退化","卵泡生长","卵泡成熟"],"a":1,"e":"月经周期第15～28天为分泌期，排卵后卵泡壁形成黄体，黄体分泌孕激素和雌激素使子宫内膜继续增厚、腺体弯曲，故此时卵巢内黄体生长。即将排卵和卵泡成熟发生在增生期末；黄体退化出现在月经前，卵泡生长属增生期，A、C、D、E与分泌期的卵巢状态不符"},{"q":"构成粗肌丝的蛋白质是","o":["肌动蛋白","肌球蛋白","肌钙蛋白","原肌球蛋白","肌红蛋白"],"a":1,"e":"粗肌丝由肌球蛋白分子平行排列集合而成，肌球蛋白头部突出于粗肌丝表面形成横桥，可与细肌丝的肌动蛋白结合。肌动蛋白、原肌球蛋白和肌钙蛋白共同构成细肌丝，其中原肌球蛋白掩盖结合位点、肌钙蛋白结合Ca²⁺；肌红蛋白是肌质内储氧蛋白，均不参与粗肌丝构成"},{"q":"周围神经系统神经纤维的神经膜细胞是指","o":["星形胶质细胞","少突胶质细胞","小胶质细胞","施万细胞","卫星细胞"],"a":3,"e":"周围神经系统的神经膜细胞即施万细胞，包绕轴突形成有髓或无髓神经纤维，其基膜对神经损伤后再生的轴突起诱导作用。星形胶质细胞、少突胶质细胞和小胶质细胞属中枢神经系统胶质；卫星细胞包绕神经节节细胞，不形成神经纤维的神经膜，A、B、C、E均错"},{"q":"单核细胞","o":["发生过程中与中性粒细胞源自同一造血祖细胞","数量少于任何一种有粒白细胞","穿出血管后具有变形运动和趋化性","吞噬作用和免疫功能较巨噬细胞弱","胞质内只含有大量溶酶体"],"a":3,"e":"单核细胞穿出血管后分化为巨噬细胞，后者体积增大5～10倍、溶酶体增多、吞噬能力显著增强，故单核细胞吞噬与免疫功能较弱。其与中性粒细胞源自不同祖细胞，数量多于嗜碱性粒细胞，趋化与变形运动在分化后才明显，胞质并非只含溶酶体，A、B、C、E均不成立"},{"q":"关于虹膜的描述，哪项错误","o":["为环形板状薄膜","虹膜基质含黑素细胞","虹膜不含血管和神经","虹膜上皮为视网膜盲部","瞳孔开大肌由上皮特化而成"],"a":2,"e":"虹膜基质为富含血管和黑素细胞的疏松结缔组织，并含神经纤维，故不含血管和神经的说法错误。虹膜呈环形板状，由前缘层、基质和上皮构成，其上皮属视网膜盲部，瞳孔开大肌由上皮细胞特化而成，A、B、D、E均为虹膜的正确描述"},{"q":"具有屏障作用的细胞连接是","o":["桥粒","缝隙连接","中间连接","紧密连接","通讯连接"],"a":3,"e":"紧密连接由相邻细胞膜上的蛋白颗粒对接并封闭细胞间隙，阻挡物质经细胞间隙穿越，具有屏障作用，胃上皮黏液屏障和血-睾屏障均依赖它。桥粒与中间连接主要起机械黏着作用；缝隙连接又称通讯连接，是离子和小分子交换通道，B、C、E均不承担屏障功能"},{"q":"关于胰腺腺泡细胞的结构特征，正确的是","o":["细胞为圆形","有丰富的滑面内质网","细胞基底部有许多酶原颗粒","基部胞质嗜碱性","核圆，位于细胞中央"],"a":3,"e":"胰腺腺泡细胞为蛋白质分泌细胞，基部胞质富含粗面内质网故呈嗜碱性，核上区高尔基复合体发达，顶部聚集酶原颗粒。滑面内质网丰富是类固醇分泌细胞特点；酶原颗粒位于顶部而非基部；细胞呈锥体形、核圆多位于基部，A、B、C、E的描述均与腺泡细胞不符"},{"q":"精子形成是指","o":["精子细胞经过复杂的形态变化形成精子的过程","从精原细胞发育成精子的过程","从初级精母细胞至精子形成的过程","生精细胞的两次成熟分裂","精子形成以后到受精的过程"],"a":0,"e":"精子形成指圆形精子细胞经核浓缩、顶体形成、鞭毛装配等复杂变态转变为蝌蚪状精子的过程，此阶段细胞不再分裂。从精原细胞到形成精子称精子发生；两次成熟分裂属减数分裂阶段；精子形成后至受精已超出该过程，B、C、D、E分别混淆了发生、分裂与后续阶段"},{"q":"排卵发生在月经周期的","o":["月经期","增生早期","分泌期中期","分泌期晚期","增生期末"],"a":4,"e":"排卵一般发生在月经周期第14天左右，此时卵泡发育成熟并排出，子宫内膜仍处于增生期末，随后转入分泌期。月经期功能层脱落；增生早期为修复阶段；分泌期中期和晚期均在排卵之后，A、B、C、D的时间与排卵节点不符"},{"q":"关于壶腹嵴的结构和功能，哪项错误","o":["位于膜半规管的壶腹内","由支持细胞、毛细胞和壶腹帽构成","毛细胞顶部有许多静纤毛","壶腹帽的糖蛋白由毛细胞分泌","感受头部旋转运动的开始和终止"],"a":3,"e":"壶腹帽的糖蛋白由支持细胞分泌，毛细胞的动、静纤毛仅插入其基部，故该项归因错误。壶腹嵴位于膜半规管壶腹内，由支持细胞和Ⅰ、Ⅱ型毛细胞及壶腹帽构成，毛细胞顶部有动纤毛和静纤毛，感受头部旋转变速运动的开始与终止，A、B、C、E均正确"},{"q":"关于透明软骨的叙述，错误的是","o":["它是体内分布最广的一类软骨","细胞间质内无纤维","软骨细胞存在间质中的软骨陷窝内","其新鲜标本呈淡蓝色半透明状","基质染色嗜碱性"],"a":1,"e":"透明软骨的细胞间质含由Ⅱ型胶原蛋白构成的胶原原纤维，纤维交织成三维网格，只是纤维极细、折光率与基质接近而在光镜下不可分辨，并非无纤维。透明软骨分布最广、新鲜标本淡蓝半透明、软骨细胞位于软骨陷窝内、基质嗜碱性，其余各项均与其特征相符"},{"q":"以下哪项不是箭头所指细胞的特征","o":["能够吞噬异物及自身衰老细胞","能够分泌抗体","细胞膜表面表达有MHCⅠ类及MHCⅡ类分子","分布广泛，淋巴组织内常见","具有抗原呈递能力"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。从选项特征看，所指细胞具备吞噬异物与衰老细胞、表面表达MHCⅠ和Ⅱ类分子、分布广泛并具抗原呈递能力，实为巨噬细胞。分泌抗体是浆细胞的功能，故该项不属于其特征；其余各项均为巨噬细胞的典型属性\n\n官方题库中缺失图片"},{"q":"增生隆起最后形成耳廓的是","o":["第Ⅰ鳃沟周围的间充质","第Ⅱ鳃沟周围的间充质","第Ⅲ鳃沟周围的间充质","第Ⅳ鳃沟周围的问充质","第Ⅰ咽囊周围的间充质"],"a":0,"e":"第1鳃沟周围间充质在胚胎第6周增生形成6个耳丘，围绕外耳道口演变为耳郭；外耳道本身由第1鳃沟演变而成。第Ⅱ、Ⅲ、Ⅳ鳃沟周围间充质不参与耳郭形成；第1咽囊主要演化为中耳鼓室和咽鼓管，B、C、D、E的解剖来源均不对"},{"q":"关于位觉斑，哪项错误","o":["呈圆斑状隆起","毛细胞顶端有许多动纤毛","毛细胞夹在支持细胞之间","位砂膜内有位砂沉着","位于球囊和椭圆囊内"],"a":1,"e":"位觉斑毛细胞顶部有40～80根静纤毛，动纤毛仅1根，位于最长静纤毛一侧，故许多动纤毛的说法错误。毛细胞夹在支持细胞之间，顶端纤毛插入含位砂的耳石膜，位觉斑位于球囊和椭圆囊内，感受直线变速运动与静止状态，A、C、D、E均正确"},{"q":"HE染色的透明软骨切片中看不到纤维的原因是","o":["软骨组织不含纤维","纤维在HE染色中不着色","纤维与基质的折光率相同","纤维密集排列","纤维平行排列"],"a":2,"e":"透明软骨的胶原原纤维极细，直径仅10～20nm，且折光率与基质接近，故HE切片光镜下不能分辨，并非纤维不着色或软骨不含纤维。纤维交织排列成网而非密集或平行排列，其与基质折光率相近才是看不见的根本原因，A、B、D、E均未抓住这一关键"},{"q":"与伴行动脉相比，关于静脉的描述，以下哪项是错误的","o":["管腔大、管壁薄","可有瓣膜","外膜中的滋养血管较少","外膜中可有纵行平滑肌束","内弹性膜不明显"],"a":2,"e":"静脉管腔大、管壁薄，三层膜分界不清，内弹性膜不明显，中膜薄而平滑肌稀疏，外膜较厚并含较多滋养血管，故滋养血管较少的说法错误。大静脉外膜滋养血管尤其丰富，以供应厚壁代谢需要，A、B、D、E对静脉结构的描述均成立"},{"q":"属于单核吞噬细胞系统的细胞是","o":["少突胶质细胞","星形胶质细胞","小胶质细胞","施万细胞","卫星细胞"],"a":2,"e":"小胶质细胞由血液单核细胞迁入神经组织后演化而成，神经系统损伤时可转变为巨噬细胞吞噬碎屑，属单核吞噬细胞系统。少突胶质细胞形成中枢髓鞘，星形胶质细胞起支持与屏障作用，施万细胞和卫星细胞属周围神经胶质，A、B、D、E均不具单核来源与吞噬属性"},{"q":"关于肾小体的特征描述，下列哪项错误","o":["由血管球及肾小囊组成","可分为血管极和尿极","尿极与远端小管曲部相连","血管极有入球和出球微动脉出入","致密斑位于血管极两条微动脉之间"],"a":2,"e":"肾小体的尿极与近端小管曲部（近曲小管）相连续，远端小管曲部位于皮质迷路、最终汇入集合管，故该项连接关系错误。肾小体由血管球和肾小囊组成，分血管极和尿极，血管极有入球、出球微动脉出入，致密斑位于两微动脉之间，A、B、D、E均正确"},{"q":"关于睾丸支持细胞的功能，哪项是错误的","o":["构成血-睾屏障","能吞噬精子形成时丢失的胞质","为生精细胞提供营养","能合成和分泌雄激素，促进精子发生","分泌少量液体有利于精子的输送"],"a":3,"e":"雄激素由睾丸间质细胞合成分泌；支持细胞在FSH作用下合成雄激素结合蛋白，保持生精小管内高雄激素水平，本身不分泌雄激素。支持细胞构成血-睾屏障，吞噬精子形成时丢失的胞质，为生精细胞提供营养，并分泌少量液体助精子输送，A、B、C、E均为其功能"},{"q":"在脑的发生过程中，菱脑泡的腔演变为","o":["第三脑室","中脑水管","侧脑室","侧脑室和第三脑室","第四脑室"],"a":4,"e":"菱脑泡的腔演变为宽大的第四脑室，其后脑部形成小脑和脑桥，末脑部形成延髓。前脑泡腔演变为侧脑室和第三脑室，中脑泡腔形成狭窄的中脑导水管，A、B、C、D分别对应前脑或中脑衍化物，与菱脑泡的归属不符"},{"q":"胎盘的组成是","o":["基蜕膜和平滑绒毛膜","壁蜕膜和丛密绒毛膜","壁蜕膜和平滑绒毛膜","包蜕膜和丛密绒毛膜","丛密绒毛膜和基蜕膜"],"a":4,"e":"基蜕膜侧血供充足，绒毛反复分支生长茂密形成丛密绒毛膜，与母体基蜕膜共同组成胎盘，胎儿面覆羊膜并有脐带附着。平滑绒毛膜与包蜕膜、壁蜕膜融合后参与构成胎膜而非胎盘主体，A、B、C、D的配对均混淆了丛密与平滑绒毛膜或蜕膜的层次"},{"q":"关于疏松结缔组织的特点，哪项错误","o":["细胞少，细胞外基质多","细胞外基质包括纤维和基质","细胞有极性，分布于细胞外基质内","基质的化学成分主要是蛋白聚糖","蛋白聚糖聚集形成有许多微孔的分子筛"],"a":2,"e":"疏松结缔组织的细胞散在分布于细胞外基质内，无极性，故有极性之说错误。其特点是细胞少、细胞外基质多，基质由纤维和无定形基质构成，化学成分以蛋白聚糖为主，蛋白聚糖聚集形成带微孔的分子筛，A、B、D、E均符合疏松结缔组织的结构"},{"q":"心肌纤维闰盘的横位部分位于","o":["M线水平","A带水平","A带与l带交界处","I带水平","Z线水平"],"a":4,"e":"心肌纤维闰盘的横位部分位于Z线水平，含黏着小带与桥粒，使相邻心肌纤维连接牢固；其横小管亦位于Z线水平并与一侧终池构成二联体。骨骼肌横小管位于明暗带交界处，A带、I带、M线均非闰盘横位部分的所在水平，A、B、C、D的定位不对"},{"q":"关于肾的球外系膜细胞，描述正确的是","o":["位于肾小体血管极处，与球内系膜细胞相延续","位于肾小体血管极处，与足细胞相延续","位于肾小体尿极处，与球内系膜细胞相延续","位于肾小体尿极处，与肾小囊壁层相延续","位于肾小体血管极处，与肾小囊壁层相延续"],"a":0,"e":"球外系膜细胞位于肾小体血管极的三角区中心，与球内系膜相延续，形态相似，并与球旁细胞、球内系膜细胞形成缝隙连接，参与信息传递。尿极与近曲小管相连，足细胞构成肾小囊脏层，肾小囊壁层在尿极移行为近曲小管上皮，B、C、D、E的延续关系均错"},{"q":"成熟女性的月经周期一般为","o":["7天","14天","28天","35天","60天"],"a":2,"e":"育龄期妇女子宫内膜每隔约28天发生一次剥脱出血与修复增生，形成一个月经周期，可分月经期、增生期和分泌期。14天是排卵及增生期末的时间点，7天近似行经期，35天和60天均偏离正常周期范围，A、B、D、E不符合一般月经周期长度"},{"q":"关于胸腺，哪项错误","o":["是培育T细胞的中枢淋巴器官","胸腺细胞增殖分化成T细胞","与皮质相比，髓质内的T细胞较少","胸腺小体仅分布于髓质","胸腺小体由胸腺细胞呈同心圆排列而成"],"a":4,"e":"胸腺小体由胸腺上皮细胞呈同心圆状排列而成，是髓质特征性结构，并非胸腺细胞构成，故该项错误。胸腺是培育初始T细胞的中枢淋巴器官，胸腺细胞增殖分化为T细胞，髓质T细胞少于皮质，胸腺小体仅见于髓质，A、B、C、D均正确"},{"q":"关于阑尾的描述哪项正确","o":["有少量的绒毛，肠腺少而短，有丰富的淋巴组织","有少量的绒毛，肠腺少而短，杯状细胞较少，有丰富的淋巴组织","无绒毛，肠腺少而短，杯状细胞较多，有丰富的淋巴组织，肌层薄","无绒毛，肠腺少而短，黏膜肌完整，有丰富的淋巴组织，肌层薄","无绒毛，肠腺少而短，黏膜肌不完整，有丰富的淋巴组织，肌层薄"],"a":4,"e":"阑尾腔小而不规则，大肠腺短而少，无绒毛，固有层内极丰富的淋巴小结突入黏膜下层致黏膜肌层不完整，肌层薄。绒毛是小肠特征，杯状细胞较多见于结肠与小肠；黏膜肌完整与阑尾淋巴组织浸润破坏的事实相悖，A、B、C、D的描述均有不符"},{"q":"对远端小管继续吸收水和钠离子有调节作用的是","o":["雌激素","胰岛素","甲状腺素","醛固酮","黄体酮"],"a":3,"e":"醛固酮作用于远端小管和集合管，促进Na⁺重吸收和K⁺排出，伴水潴留，血管紧张素Ⅱ可刺激其分泌。雌激素与黄体酮属性激素，主要作用于生殖系统；胰岛素调节糖代谢；甲状腺素提高基础代谢，均不直接调节远端小管的水钠重吸收，A、B、C、E错"},{"q":"关于软骨的叙述，哪项正确","o":["富含钙离子","三种软骨均含纤维","羟基磷灰石结晶比骨组织少","对长骨的生长作用甚微","基质中埋藏有成软骨细胞"],"a":1,"e":"透明软骨含Ⅱ型胶原原纤维，纤维软骨含大量粗大胶原纤维束，弹性软骨含丰富弹性纤维，故三种软骨均含纤维。软骨基质不含大量钙盐与羟基磷灰石，那是骨组织的特征；软骨通过软骨内成骨参与长骨生长，作用重要；基质中埋藏的是软骨细胞而非成软骨细胞，A、C、D、E均错"},{"q":"胆道堵塞内压增大时出现","o":["胆汁通过肝板上的孔流入中央静脉","胆汁通过肝板上的孔流入肝血窦","胆汁通过闰管流入肝血窦","胆汁通过胆小管周围破坏的细胞连接进入肝血窦","胆汁通过胆小管周围破坏的细胞连接进入中央静脉"],"a":3,"e":"胆小管周围相邻肝细胞膜形成含紧密连接、桥粒的连接复合体，封闭细胞间隙防止胆汁外溢。胆道堵塞内压增高时该复合体破坏，胆汁先溢入窦周隙再进入肝血窦，引起黄疸。胆汁不经肝板孔流入中央静脉或血窦，也不经闰管逆流，A、B、C、E的路径均不存在"},{"q":"胞质内有异染性颗粒的细胞","o":["成纤维细胞","浆细胞","肥大细胞","巨噬细胞","纤维细胞"],"a":2,"e":"肥大细胞胞质内充满异染性颗粒，颗粒含肝素、组胺及趋化因子，参与过敏反应和炎症，甲苯胺蓝染色呈异染性。成纤维细胞与纤维细胞分泌胶原纤维而无异染颗粒；浆细胞胞质富含粗面内质网呈嗜碱性；巨噬细胞以溶酶体和吞噬体为主，A、B、D、E均不符"},{"q":"患寄生虫感染时，血液中何种白细胞增高","o":["中性粒细胞","嗜酸性粒细胞","嗜碱性粒细胞","单核细胞","淋巴细胞"],"a":1,"e":"嗜酸性粒细胞胞质充满嗜酸性颗粒，其阳离子蛋白对寄生虫有强杀灭作用，组胺酶和芳基硫酸酯酶可抑制过敏反应，故寄生虫感染与过敏性疾病时血液中该细胞增多。中性粒细胞主司细菌吞噬；嗜碱性粒细胞和肥大细胞参与过敏但数量少；单核细胞、淋巴细胞与抗寄生虫直接杀伤无关，A、C、D、E错"},{"q":"原始消化管管壁的构成是","o":["内胚层和体壁中胚层","内胚层","外胚层和脏壁中胚层","脏壁中胚层","内胚层和脏壁中胚层"],"a":4,"e":"原始消化管由内胚层被包入胚体形成，其外面覆盖脏壁中胚层，后者分化为消化呼吸管的肌组织、血管、结缔组织和间皮。体壁中胚层衬于外胚层侧并参与体壁形成，与消化管无关；单层内胚层或脏壁中胚层均不足以构成管壁，A、B、C、D的配对不全或错配"},{"q":"肌质网的膜上有钙泵蛋白，它可以","o":["调节线粒体内的Na＋浓度","调节肌浆中的Ca2＋浓度","抑制兴奋传递","是一种ATP酶，可与肌动蛋白接触","抑制横桥发生屈伸运动"],"a":1,"e":"肌质网膜上的钙泵为Ca²⁺-ATP酶，可逆浓度差把肌质中的Ca²⁺泵入肌质网贮存，使网内浓度远高于肌质，从而调节肌浆Ca²⁺水平并终止收缩。它不调节线粒体Na⁺；不抑制兴奋传递或横桥屈伸；与肌动蛋白接触的是肌球蛋白横桥而非钙泵，A、C、D、E均错"},{"q":"内分泌细胞数量和种类最多的内分泌器官是","o":["脑垂体","肾上腺","消化道","甲状腺","松果体"],"a":2,"e":"胃肠黏膜面积巨大，其上皮和腺体内散布40余种内分泌细胞，总量超过所有内分泌腺腺细胞之和，故消化道是体内数量与种类最多的内分泌器官，以胃幽门部和十二指肠上段为多。脑垂体、肾上腺、甲状腺、松果体虽为典型内分泌腺，但细胞总量与种类均不及胃肠，A、B、D、E错"},{"q":"圈中结构为","o":["弥散淋巴组织","初级淋巴小结","次级淋巴小结","胸腺小体","脾小体"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，含生发中心的淋巴小结称次级淋巴小结，生发中心分暗区和明区，接触抗原后约2周达高峰。初级淋巴小结无生发中心；胸腺小体由胸腺上皮细胞同心圆排列；脾小体是脾内的淋巴小结，A、B、D、E的结构归属各不同\n\n官方题库中缺失图片"},{"q":"以下关于环层小体的描述，哪项正确","o":["分布于皮肤真皮乳头内","感受压觉和振动觉","圆形，与触觉小体大小相似","有髓神经纤维穿行于中央","薄层结缔组织组成被囊"],"a":1,"e":"环层小体体积较大，中心为一条失去髓鞘的神经纤维末梢，周围包绕多层同心圆板层被囊，感受较强应力，参与压觉和振动觉。触觉小体位于真皮乳头、较小，感受触觉；有髓纤维进入环层小体时已失髓鞘；被囊为多层而非薄层，A、C、D、E均属触觉小体或错误描述"},{"q":"构成神经组织的基本成分是","o":["神经元和神经纤维","神经元和神经丝","神经元和神经胶质细胞","神经元和神经末梢","神经元和神经"],"a":2,"e":"神经组织由神经元和神经胶质细胞两类细胞组成，神经元是结构与功能单位，胶质细胞起支持、绝缘、营养和保护作用。神经纤维由神经元突起及包绕它的胶质细胞构成，属结构而非基本细胞成分；神经丝是胞内骨架；神经末梢与神经均为派生结构，A、B、D、E不完整"},{"q":"关于脾血窦的描述哪项错误","o":["窦壁的内皮细胞呈扁平状","内皮细胞处基膜不完整","窦周围有许多巨噬细胞","内皮细胞之间有较明显的间隙","形状不规则，位于红髓的脾索之间"],"a":0,"e":"脾血窦壁由一层纵向平行排列的长杆状内皮细胞围成，而非扁平状，内皮外有不完整基膜和环行网状纤维，故该项错误。血窦形态不规则、位于红髓脾索之间，窦壁内皮细胞间有明显间隙，周围有较多巨噬细胞附着，B、C、D、E对脾血窦的描述均正确"},{"q":"关于Ⅱ型肺泡细胞，哪项错误","o":["是一种立方或圆形的细胞","含板层小体","板层小体是分泌颗粒，含磷脂","可由Ⅰ型肺泡细胞分化而来","可分化为Ⅰ型肺泡细胞"],"a":3,"e":"Ⅱ型肺泡细胞呈立方或圆形，含嗜锇性板层小体，内含磷脂、蛋白质和糖的复合物，分泌表面活性物质；它可增殖并分化为Ⅰ型肺泡细胞以修复上皮。Ⅰ型细胞为高度扁平的气体交换细胞，不再分化为Ⅱ型，故反向分化的说法错误，A、B、C、E均符合Ⅱ型细胞特征"},{"q":"放射冠细胞是","o":["初级卵母细胞","次级卵母细胞","卵原细胞","成熟卵细胞","卵泡细胞"],"a":4,"e":"放射冠是紧贴透明带的一层高柱状卵泡细胞，呈放射状排列，属卵泡细胞而非生殖细胞。初级卵母细胞、次级卵母细胞、卵原细胞和成熟卵细胞均为不同发育阶段的生殖细胞，位于透明带之内，不形成放射冠，A、B、C、D的细胞属性均错"},{"q":"垂体细胞是","o":["嫌色细胞","神经内分泌细胞","神经胶质细胞","神经元","特化的成纤维细胞"],"a":2,"e":"垂体细胞是神经垂体内的神经胶质细胞，起支持、营养和绝缘作用，不具内分泌或神经元功能。嫌色细胞属腺垂体腺细胞；神经内分泌细胞指下丘脑等分泌激素的神经元；特化的成纤维细胞亦非其来源，A、B、D、E的分类均与垂体细胞不符"},{"q":"关于深层皮质单位的描述，哪项错误","o":["细胞免疫功能活跃时，此区明显扩大","是一片弥散淋巴组织","位于淋巴小结与髓质之间","含有毛细血管后微静脉","是B细胞聚集处"],"a":4,"e":"深层皮质单位即副皮质区，位于淋巴小结与髓质之间，是一片弥散淋巴组织，含毛细血管后微静脉，为T细胞聚集区，细胞免疫活跃时明显扩大，故B细胞聚集处的说法错误。B细胞主要聚集于浅层皮质的淋巴小结内，A、B、C、E均为副皮质区的正确特征"},{"q":"血细胞最早出现的部位是","o":["卵黄囊血岛","骨髓","肝","淋巴结","脾"],"a":0,"e":"最早造血发生于胚胎卵黄囊壁的胚外中胚层血岛，血岛周边细胞分化为内皮细胞，中央细胞分化成造血干细胞。肝、脾、胸腺于胚胎时期相继造血，骨髓为出生后主要造血器官，淋巴结主要生成淋巴细胞，B、C、D、E在时间或性质上均非最早造血部位"},{"q":"能进行物质交换的主要血管是","o":["微动脉","中间微动脉","真毛细血管","直捷通路","小动脉"],"a":2,"e":"真毛细血管由中间微动脉分支吻合成网，血流缓慢、行程迂回，是物质交换的主要部位，其起始部有毛细血管前括约肌调节血流。微动脉与中间微动脉主要分配血流；直捷通路管径较粗、血流快，使血液快速回流；小动脉属阻力血管，A、B、D、E均非交换主力"},{"q":"视近物时，晶状体曲度增大是由于","o":["睫状肌收缩，睫状小带紧张","睫状肌舒张，睫状小带紧张","睫状肌收缩，睫状小带松弛","睫状肌舒张，睫状小带松弛","与睫状肌和睫状小带无关"],"a":2,"e":"视近物时睫状肌收缩，睫状体向前内方移位，睫状小带随之松弛，晶状体因自身弹性变凸、曲度增大以聚焦近物。睫状肌舒张时睫状小带紧张、晶状体扁平，用于视远物；其余组合把肌肉状态与小带张力错配，A、B、D、E均不符合近视调节机制"},{"q":"中胚层自中轴向外侧依次为","o":["间介中胚层、轴旁中胚层、侧中胚层","轴旁中胚层、侧中胚层、间介中胚层","轴旁中胚层、间介中胚层、侧中胚层","侧中胚层、间介中胚层、轴旁中胚层","侧中胚层、轴旁中胚层、间介中胚层"],"a":2,"e":"胚内中胚层自中轴向外依次为轴旁中胚层、间介中胚层和侧中胚层：轴旁中胚层紧邻脊索并裂为体节，间介中胚层为泌尿生殖系统原基，侧中胚层分为体壁与脏壁两层。其余选项颠倒了三者的内外次序，A、B、D、E的排列均与自中轴外侧的序列不符"},{"q":"肌节","o":["1个明带＋1个暗带","位于M线与Z线之间","位于相邻两条Z线之间","位于相邻两条M线之间","1/2暗带＋明带＋1/2暗带"],"a":2,"e":"肌节是相邻两条Z线之间的一段肌原纤维，为骨骼肌结构和功能的基本单位，由1/2明带＋暗带＋1/2明带构成。M线位于暗带中央，两条M线之间跨度为暗带加两侧半个暗带；1/2暗带＋明带＋1/2暗带的组合把明暗带顺序颠倒，A、B、D、E均错"},{"q":"胰腺中哪种细胞退化可引起糖尿病","o":["A细胞","B细胞","D细胞","PP细胞","浆液性腺细胞"],"a":1,"e":"胰岛B细胞分泌胰岛素，其退化或破坏致胰岛素绝对或相对不足，血糖升高并从尿中排出形成糖尿病，1型即因B细胞被破坏。A细胞分泌胰高血糖素，D细胞分泌生长抑素，PP细胞分泌胰多肽，浆液性腺细胞属外分泌部，A、C、D、E与胰岛素缺乏无关"},{"q":"淋巴结内发生体液免疫应答的主要变化是","o":["浅层皮质变小","髓质增大","初级淋巴小结增多增大","次级淋巴小结增多增大","副皮质区增厚"],"a":3,"e":"体液免疫应答以B细胞在浅层皮质淋巴小结增殖分化为主，淋巴小结增多增大、出现生发中心是重要标志，髓索内浆细胞增多、抗体升高。T细胞介导的细胞免疫主要表现为副皮质区增厚；初级淋巴小结无生发中心；髓质增大非特异性指标，A、B、C、E归属错"},{"q":"可对原尿进行重吸收的部位是","o":["肾小囊和肾小管","肾小体和肾小管","肾小管和集合管","肾小体和肾小囊","集合管"],"a":2,"e":"肾小体滤过生成原尿后，原尿流经肾小管和集合管时绝大部分水、营养物质与无机盐被重吸收入血，部分离子在此交换并排出代谢产物。肾小体与肾小囊只参与滤过，不具重吸收功能；集合管单独概括又遗漏了肾小管，A、B、D、E的范围均不完整"},{"q":"神经垂体来源于","o":["间脑底部的神经外胚层","端脑底部的神经外胚层","中脑底部的神经外胚层","后脑底部的神经外胚层","末脑底部的神经外胚层"],"a":0,"e":"神经垂体由间脑底部神经外胚层向腹侧突出的漏斗状芽（神经垂体芽）发育而来，主要由无髓神经纤维和神经胶质细胞构成。腺垂体源自口凹表面外胚层形成的拉特克囊；端脑、中脑、后脑、末脑底部均不产生神经垂体芽，B、C、D、E的来源不对"},{"q":"食管的组织结构特点不包括","o":["黏膜上皮为复层扁平上皮","上、下端固有层可有少许黏液性腺","黏膜下层含食管腺","肌层为纵行的平滑肌","外膜为纤维膜"],"a":3,"e":"食管肌层由内环行和外纵行两层构成，上段为骨骼肌、下段移行为平滑肌，并非单纯的纵行平滑肌，故该项不属于食管结构特点。食管黏膜上皮为未角化复层扁平上皮，上、下端固有层可有少量黏液腺，黏膜下层含食管腺，外膜为纤维膜，A、B、C、E均正确"},{"q":"食管及胃的上皮分别为","o":["单层扁平上皮及复层扁平上皮","复层扁平上皮及复层柱状上皮","复层扁平上皮及单层柱状上皮","单层柱状上皮及变移上皮","单层扁平上皮及变移上皮"],"a":2,"e":"食管腔面为未角化的复层扁平上皮，耐摩擦起机械保护作用；胃腔面为单层柱状上皮，由表面黏液细胞组成，形成胃黏膜屏障。单层扁平上皮见于血管和肺泡；复层柱状上皮见于睑结膜；变移上皮见于泌尿道，A、B、D、E的上皮类型与两器官均不匹配"},{"q":"小肠是消化吸收主要场所，下列哪组结构有助于扩大小肠的表面积","o":["纵行皱襞、小肠绒毛和微绒毛","环行皱襞、小肠绒毛和杯状细胞","环行皱襞、小肠绒毛和纹状缘","纵行皱襞、小肠绒毛和吸收细胞","环行皱襞、小肠腺和小肠绒毛"],"a":2,"e":"小肠黏膜形成环行皱襞，上皮与固有层向腔面突出成小肠绒毛，吸收细胞游离面微绒毛密集排列成纹状缘，皱襞与绒毛约扩大30倍，微绒毛再加约20倍。纵行皱襞并不存在；杯状细胞分泌黏液；小肠腺位于绒毛根部；吸收细胞本身不是扩大结构，A、B、D、E均错"},{"q":"具有吞噬功能的神经胶质细胞是","o":["少突胶质细胞","室管膜细胞","星形胶质细胞","小胶质细胞","卫星细胞"],"a":3,"e":"小胶质细胞由血液单核细胞迁入神经组织演化而成，损伤时可转变为巨噬细胞吞噬死亡细胞碎屑，是中枢神经系统具吞噬功能的胶质细胞，亦属单核吞噬细胞系统。少突胶质细胞形成髓鞘，星形胶质细胞支持并参与屏障，室管膜细胞衬脑室，卫星细胞属周围神经，A、B、C、E均无此吞噬属性"},{"q":"以下关于骨骼肌纤维超微结构的描述，哪项是错误的","o":["每条肌原纤维由更细的肌丝构成","肌丝分粗肌丝、细肌丝两种","横小管位于Z线水平","肌浆网在靠近横小管处膨大形成终池","横小管和两侧终池组成三联体"],"a":2,"e":"骨骼肌纤维的横小管位于明带与暗带交界处，与两侧终池组成三联体；横小管位于Z线水平是心肌纤维的特点，故该项错误。每条肌原纤维由粗、细肌丝构成，肌浆网在横小管附近膨大形成终池，终池与横小管共同完成兴奋-收缩耦联，A、B、D、E均符合骨骼肌"},{"q":"心脏传导系统的细胞实际上是","o":["感觉上皮细胞","特殊的心肌细胞","特殊的神经细胞","特殊的运动神经元","结缔组织细胞"],"a":1,"e":"心脏传导系统由特殊分化的心肌纤维组成，窦房结、房室结、房室束及浦肯野纤维能产生并传导动作电位，使心肌按节律舒缩，并非神经组织。感觉上皮细胞见于感受器；神经细胞和运动神经元属神经组织；结缔组织细胞只构成支架，A、C、D、E的归属均错"},{"q":"关于静脉的结构特点，哪项是错误的","o":["3层膜界限清楚","管壁较薄而管腔较大","内弹性膜不发达或缺如","中膜薄，平滑肌稀疏","外膜较厚"],"a":0,"e":"静脉无明显内、外弹性膜，三层膜界限不如动脉清楚，故该项错误。静脉管壁薄、管腔大，内弹性膜不发达或缺如，中膜薄、平滑肌稀疏，外膜较厚，常呈塌陷状；这些特点与动脉形成对照，B、C、D、E对静脉结构的描述均成立"},{"q":"对视锥细胞的描述，错误的是","o":["细胞核较大，染色较浅","外节膜盘与细胞膜分离，顶部膜盘不断脱落","细胞分3类，分别含红敏视色素、蓝敏视色素和绿敏视色素","缺少含红（绿）敏视色素的视锥细胞会引起红绿色盲","黄斑中央凹处只有视锥细胞"],"a":1,"e":"视锥细胞外节的膜盘大多与细胞膜不分离，顶端膜盘也不脱落；膜盘分离并不断脱落被色素上皮吞噬是视杆细胞的特点，故该项错误。视锥细胞核较大染色浅，分三类含不同视色色素，缺红绿敏视色素致红绿色盲，中央凹处只有视锥细胞，A、C、D、E均正确"},{"q":"系膜增生性肾炎和膜增生性肾炎都有光镜下系膜增生的表现，关于球内系膜（血管系膜）的描述，下列哪项是错误的","o":["由球内系膜细胞和基质组成","球内系膜细胞有突起伸到内皮细胞与基膜间，但决不能到达毛细血管腔内","系膜细胞的胞质内可含有中间丝","目前认为球内系膜细胞为特化的平滑肌细胞","球内系膜细胞有合成、分泌和吞噬作用及收缩能力"],"a":1,"e":"球内系膜细胞形态不规则，突起可伸入内皮细胞与基膜之间，并可到达毛细血管腔内，参与滤过调节与吞噬，故绝对不能到达管腔的说法错误。系膜由系膜细胞和基质组成，胞质含中间丝，现多视为特化平滑肌细胞，具合成、分泌、吞噬与收缩能力，A、C、D、E均正确"},{"q":"关于淋巴结，哪项错误","o":["被膜中有输入淋巴管","T细胞主要分布在皮质浅层","髓窦中有巨噬细胞","能过滤淋巴","是免疫应答的场所"],"a":1,"e":"淋巴结浅层皮质含淋巴小结，是B细胞聚集区；T细胞主要分布于深层皮质（副皮质区），故该项错误。被膜中有输入淋巴管，髓窦内巨噬细胞可吞噬异物，淋巴结能过滤淋巴并是免疫应答场所，A、C、D、E对淋巴结结构与功能的描述均正确"},{"q":"中央前回的大脑皮质中哪层较发达","o":["分子层","外颗粒层","外锥体细胞层和内颗粒层","内锥体细胞层","多形细胞层"],"a":3,"e":"大脑皮质内锥体细胞层由大、中型锥体细胞组成，中央前回此处含巨大的贝兹细胞，发出投射纤维支配随意运动，故该层在中央前回特别发达。分子层以神经纤维和少量细胞为主；外颗粒层和外锥体细胞层、多形细胞层均非运动输出的主要层次，A、B、C、E不符"},{"q":"早期晶状体泡由单层上皮组成","o":["其前壁细胞呈立方形，后壁细胞呈高柱状","其前壁细胞呈高柱状，后壁细胞呈立方形","其前壁为单层立方，后壁为假复层柱状","其前壁为单层扁平，后壁为假复层柱状","其前壁为单层扁平，后壁为单层立方"],"a":0,"e":"早期晶状体泡由单层上皮组成，前壁细胞呈立方形，分化为晶状体上皮；后壁细胞呈高柱状，向前伸长形成初级晶状体纤维。前壁高柱状或扁平、后壁立方或假复层柱状等组合均与晶状体泡实际的极性分化相反，B、C、D、E的前后壁细胞形态描述错误"},{"q":"在内分泌腺中，常见腺细胞排列成滤泡状的结构是","o":["肾上腺皮质和髓质","腺垂体结节部和中间部","甲状腺和腺垂体中间部","甲状腺和甲状旁腺","肾上腺髓质和神经垂体"],"a":2,"e":"甲状腺滤泡由滤泡上皮细胞围成，腺垂体中间部亦可见由腺细胞围成的滤泡，故二者呈滤泡状排列。肾上腺皮质细胞成索状、髓质成团状；腺垂体结节部细胞沿血管排列成索；神经垂体为神经纤维与胶质细胞，无滤泡结构，A、B、D、E的排列方式均不符"},{"q":"回肠憩室的成因是","o":["卵黄囊未退化，残留一指状盲囊","卵黄蒂近端退化不全，残留一指状盲囊","尿囊未退化，残留一指状盲囊","尿囊基部未退化，残留一指状盲囊","脐腔未闭锁"],"a":1,"e":"梅克尔憩室又称回肠憩室，因卵黄蒂近端未退化，在距回盲部40～50cm处回肠壁残留一囊状突起，顶端可有纤维索与脐相连。卵黄囊整体未退化致脐肠瘘；尿囊未退化与脐尿管异常相关；脐腔未闭锁致脐疝，A、C、D、E对应的畸形均不同"},{"q":"感冒时，鼻呼吸部黏膜肿胀、通气不畅的主要原因是","o":["固有层深层动脉壁平滑肌收缩，使浅层毛细血管充血肿胀","固有层深层淋巴管平滑肌收缩，使浅层毛细淋巴管充满淋巴液肿胀","固有层深层静脉壁平滑肌收缩，使浅层静脉丛充血肿胀","固有层深层平滑肌收缩，使浅层海绵组织充满组织液肿胀","鼻腺分泌物刺激所致"],"a":2,"e":"鼻呼吸部固有层深层含丰富的静脉丛，其壁平滑肌收缩使静脉回流受阻、浅层静脉丛充血肿胀，导致黏膜增厚、通气不畅，感冒时尤为明显。动脉壁收缩会减少毛细血管血流；淋巴管与组织液积聚不是鼻塞主因；鼻腺分泌物刺激亦非肿胀的机制，A、B、D、E错"},{"q":"未分化生殖腺的初级性索发生于","o":["卵黄囊胚外内胚层","尿囊内胚层","生殖腺嵴表面上皮","次级性索","卵黄囊胚外中胚层"],"a":2,"e":"未分化期第5周，生殖嵴表面的体腔上皮细胞增生并伸入下方间充质，形成初级性索，其上皮细胞将演变为支持细胞。卵黄囊胚外内胚层与中胚层形成原始生殖细胞相关结构而非性索；尿囊内胚层不参与；次级性索由初级性索演化而来，A、B、D、E的来源均错"},{"q":"基膜的特点不包括","o":["位于上皮组织和结缔组织之间","PAS反应阳性","电镜下可见有透明板、基板和网板","化学成分主要为糖蛋白和蛋白聚糖","是一种半透膜"],"a":2,"e":"电镜下基膜由基板和网板两部分构成，其中基板又分透明板和致密板，故把透明板与基板、网板并列为三层结构的说法错误。基膜位于上皮与结缔组织之间，PAS反应阳性，主要成分为糖蛋白和蛋白聚糖，具半透膜性质，A、B、D、E均符合基膜特点"},{"q":"结缔组织中的可以合成分泌胶原蛋白的细胞是","o":["间充质细胞","纤维细胞","成纤维细胞","浆细胞","组织细胞"],"a":2,"e":"成纤维细胞是疏松结缔组织中合成分泌胶原蛋白和弹性蛋白、形成无定形基质的主要细胞，电镜下粗面内质网丰富、高尔基复合体发达。纤维细胞为其静止状态，合成功能低下；间充质细胞为胚胎性未分化细胞；浆细胞分泌抗体；组织细胞以吞噬为主，A、B、D、E均非胶原主要来源"},{"q":"房间隔缺损主要为卵圆孔未闭，成因中不包括","o":["卵圆孔瓣上有许多穿孔","第一房间隔在形成第二房间孔时吸收过多，导致卵圆孔瓣太小","第二房间隔发育异常，形成过大的卵圆孔","心内膜垫发育异常","主动脉肺动脉隔偏位"],"a":4,"e":"卵圆孔未闭多因卵圆孔瓣穿孔、第一房间隔吸收过多致瓣过小、第二房间隔发育异常使孔过大或心内膜垫发育异常所致。主动脉肺动脉隔偏位导致的是动脉干分隔异常，如大动脉错位、主动脉或肺动脉狭窄及法洛四联症，不引起卵圆孔未闭，故该项不属于其成因"},{"q":"关于次级卵泡的叙述，哪项错误","o":["内含一个次级卵母细胞","卵泡细胞间有空隙或存在卵泡腔","卵泡膜分内外两层","放射冠由一层柱状卵泡细胞形成","卵泡细胞层数增至6～12层"],"a":0,"e":"次级卵泡内含的是一个初级卵母细胞，其体积达最大、外包透明带与放射冠；次级卵母细胞在排卵前36～48小时才由第一次减数分裂形成，见于成熟卵泡，故该项错误。卵泡细胞间出现卵泡腔、卵泡膜分内外两层、放射冠由柱状卵泡细胞形成、卵泡细胞增至6～12层，B、C、D、E均正确"},{"q":"由B淋巴细胞分裂、分化的细胞是","o":["树突细胞","巨噬细胞","网状细胞","浆细胞","T淋巴细胞"],"a":3,"e":"B淋巴细胞受抗原刺激后增殖分化为浆细胞，合成并分泌抗体，参与体液免疫，部分分化为记忆B细胞。树突细胞与巨噬细胞属抗原呈递细胞，来源于髓系；网状细胞构成淋巴组织支架；T淋巴细胞在胸腺成熟、介导细胞免疫，A、B、C、E均非B细胞分化产物"},{"q":"电镜观察骨骼肌纤维，只有粗肌丝而无细肌丝的是","o":["I带","H带","A带","A带和H带","I带和H带"],"a":1,"e":"H带位于暗带中央、M线两侧，此处只有粗肌丝而无细肌丝，故电镜下仅见粗肌丝的是H带。明带（I带）仅由细肌丝构成；暗带（A带）除H带外由粗细两种肌丝共同构成；粗细肌丝重叠区不含于单纯H带，A、C、D、E的带区归属均不正确"},{"q":"视网膜最敏锐的视觉部位是","o":["视网膜中部","视网膜周边部","黄斑","中央凹","视盘"],"a":3,"e":"中央凹是黄斑中央最薄处，仅含色素上皮细胞和视锥细胞，且与双极细胞、节细胞呈一对一联系，光线可直接落在视锥细胞上，故视觉最敏锐。黄斑为视网膜后极浅黄区域，范围大于中央凹；视盘为节细胞轴突汇集穿出之处，无感光细胞；视网膜周边部分辨力低，A、B、C、E均错"},{"q":"胃底腺主细胞的超微结构特点是","o":["大量滑面内质网及酶原颗粒","大量粗面内质网及酶原颗粒","大量线粒体及酶原颗粒","大量粗面内质网，无酶原颗粒","高尔基复合体发达，无酶原颗粒"],"a":1,"e":"胃底腺主细胞分泌胃蛋白酶原，属蛋白质分泌细胞，电镜下胞质含大量粗面内质网、发达高尔基复合体及顶部酶原颗粒。滑面内质网丰富是类固醇分泌细胞特点；线粒体丰富主司能量代谢；不含酶原颗粒则无法储备分泌蛋白，A、C、D、E均不符合主细胞的超微结构"},{"q":"男性进入青春期后，激发第二性征的发育，和男性第二性征直接相关的激素是","o":["卵泡刺激素","黄体生成素","醛固酮","雄激素","糖皮质激素"],"a":3,"e":"睾丸间质细胞分泌的雄激素启动并维持精子发生、男性生殖器官发育及第二性征和性功能，是直接相关激素。卵泡刺激素促支持细胞合成雄激素结合蛋白，黄体生成素刺激间质细胞分泌雄激素，二者为间接调节；醛固酮与糖皮质激素属肾上腺皮质激素，A、B、C、E均错"},{"q":"晶状体核来自","o":["晶状体泡的前壁上皮","晶状体泡的后壁上皮","初级晶状体纤维及其胞核","次级级晶状体纤维及其胞核","次级级晶状体纤维"],"a":2,"e":"晶状体泡后壁细胞向前延伸形成初级晶状体纤维，其胞核逐渐退化构成晶状体核；赤道部上皮持续增生形成次级晶状体纤维并逐层添加于核周围。前壁细胞保持单层立方、分化为晶状体上皮，不形成晶状体核；次级纤维只包绕于核外，A、B、D、E的来源均错"},{"q":"微小病变性肾小球病时可见足细胞损伤，以下关于足细胞的正确描述是","o":["是肾小球内的内皮细胞","是肾小囊壁层上皮细胞","是肾小囊脏层上皮细胞","是球旁细胞","是球内系膜细胞"],"a":2,"e":"足细胞是肾小囊脏层上皮细胞，胞体凸向囊腔，伸出突起相互交错，与毛细血管内皮及基膜共同构成滤过屏障，损伤时出现蛋白尿。肾小囊壁层为单层扁平上皮，在尿极移行为近曲小管；内皮细胞、球旁细胞和球内系膜细胞均属血管球或球旁复合体成分，A、B、D、E错"},{"q":"宫内节育器避孕的原理为","o":["杀死卵子","杀死受精卵","阻止精卵相遇","抑制胚胎发育","影响着床"],"a":4,"e":"宫内节育器置于宫腔后引起局部无菌性炎症反应，改变宫腔与内膜环境，干扰胚泡植入（着床）而达到避孕目的，并不直接杀灭卵子或受精卵。抑制胚胎发育与阻止精卵相遇均非其主要机制，A、B、C、D的作用环节与节育器实际避孕原理不符"},{"q":"在心房间隔上的卵圆孔是","o":["在第二房间隔上，位于第二房间隔的上端，左侧被第一房间隔覆盖","在第一房间隔上，位于第二房间孔的下端，右侧被第一房间隔覆盖","在第二房间隔上，位于第二房间孔的上端，右侧被第一房间隔覆盖","在第二房间隔上，位于第二房间孔的下端，右侧被第一房间隔覆盖","在第二房间隔上，位于第二房间孔的下端，左侧被第一房间隔覆盖"],"a":4,"e":"第二房间隔从心房头端腹侧壁长出并覆盖第二房间孔，其下缘留有的卵圆孔位于第二房间孔稍下方，左侧被薄而软的第一房间隔（卵圆孔瓣）覆盖，使血液只能由右向左分流。卵圆孔不在第一房间隔上，也不位于第二房间孔上端或被第一房间隔右侧覆盖，A、B、C、E的方位与覆盖关系错误"},{"q":"关于玻璃体的描述，哪项错误","o":["为无色透明的胶状体","有支撑视网膜的作用","有屈光作用","损伤后可以再生","有一些透明细胞"],"a":3,"e":"玻璃体为无色透明凝胶，含少量透明细胞但无血管和神经，损伤后由纤维组织增生修复而不能再生，故该项错误。玻璃体填充于晶状体与视网膜之间，有屈光和支撑视网膜、维持眼球形态的作用，A、B、C、E对玻璃体性质与功能的描述均成立"},{"q":"关于骨和软骨的共同特征，下列哪项错误","o":["都能以间质生长方式生长","骨细胞与软骨细胞都位于陷窝内","细胞间质含有基质和纤维","软骨膜和骨膜都是致密结缔组织","软骨细胞与骨细胞都来源于骨祖细胞"],"a":0,"e":"软骨可行间质性生长和软骨膜下附加性生长，而骨依靠膜内成骨和软骨内成骨方式发生与重建，不能以间质生长方式生长，故该项错误。骨细胞与软骨细胞均位于陷窝内，细胞间质含基质和纤维，软骨膜与骨膜均为致密结缔组织，两类细胞均源自骨祖细胞，B、C、D、E正确"},{"q":"T淋巴细胞","o":["在胸腺内分化发育而成","在骨髓内分化发育而成","分布于淋巴小结和脾小体","与体液免疫有关","不能进行淋巴细胞再循环"],"a":0,"e":"T淋巴细胞由胚胎第3个月经血入胸腺的淋巴干细胞增殖分化而成，胸腺素等促其成熟，参与细胞免疫并可再循环。B淋巴细胞在骨髓成熟；淋巴小结和脾小体为B细胞区；与体液免疫相关的是B细胞；T细胞能进行淋巴细胞再循环，B、C、D、E均错"}];
